fn governance_car_queue_lookup_response(
    state: &SharedAppState,
    headers: HeaderMap,
    schema: &str,
    query: &str,
    map_name: &str,
    key: &str,
    limit: usize,
) -> Response {
    let (queue, metadata) = match load_governance_dag_car_queue(state) {
        Ok(value) => value,
        Err(response) => return response,
    };
    let segments = match governance_car_queue_lookup_segments(&queue, map_name, key) {
        Ok(segments) if segments.is_empty() => {
            return json_error(
                StatusCode::NOT_FOUND,
                format!("governance DAG CAR queue {query} `{key}` was not found"),
            );
        }
        Ok(segments) => segments,
        Err(response) => return response,
    };
    let limit_component = limit.to_string();
    let etag = governance_dag_representation_etag(
        &metadata.etag,
        "car-queue-lookup",
        &[schema, query, map_name, key, limit_component.as_str()],
    );
    if let Some(response) = governance_dag_not_modified_response(&headers, &etag) {
        return response;
    }
    let count = segments.len();
    let (segments, truncated) = limit_governance_readback_values(segments, limit);
    let mut response = Map::new();
    response.insert("schema".into(), Value::from(schema));
    insert_governance_dag_source_metadata(&mut response, &metadata);
    response.insert("query".into(), Value::from(query));
    response.insert("key".into(), Value::from(key.to_string()));
    response.insert("found".into(), Value::from(true));
    response.insert("count".into(), Value::from(count as u64));
    response.insert("returned_count".into(), Value::from(segments.len() as u64));
    response.insert("limit".into(), Value::from(limit as u64));
    response.insert("truncated".into(), Value::from(truncated));
    response.insert("segments".into(), Value::Array(segments));
    governance_dag_json_response(Value::Object(response), &etag)
}
fn governance_car_queue_archive_lookup_response(
    state: &SharedAppState,
    headers: HeaderMap,
    car_archive_blake3: &str,
) -> Response {
    let (queue, metadata) = match load_governance_dag_car_queue(state) {
        Ok(value) => value,
        Err(response) => return response,
    };
    let segment = match governance_car_queue_lookup_segments(
        &queue,
        "by_car_archive_blake3",
        car_archive_blake3,
    ) {
        Ok(mut segments) if segments.len() == 1 => segments.pop().expect("length checked"),
        Ok(segments) if segments.is_empty() => {
            return json_error(
                StatusCode::NOT_FOUND,
                format!("governance DAG CAR queue archive `{car_archive_blake3}` was not found"),
            );
        }
        Ok(_) => {
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("governance DAG CAR queue archive `{car_archive_blake3}` is ambiguous"),
            );
        }
        Err(response) => return response,
    };
    if let Err(response) = verify_governance_car_segment_artifacts(state, &segment) {
        return response;
    }
    let etag = governance_dag_representation_etag(
        &metadata.etag,
        "car-queue-archive",
        &[car_archive_blake3],
    );
    if let Some(response) = governance_dag_not_modified_response(&headers, &etag) {
        return response;
    }
    let mut response = Map::new();
    response.insert(
        "schema".into(),
        Value::from("sorafs.governance_dag.car_queue.archive.lookup.v1"),
    );
    insert_governance_dag_source_metadata(&mut response, &metadata);
    response.insert("query".into(), Value::from("car_archive_blake3"));
    response.insert("key".into(), Value::from(car_archive_blake3.to_string()));
    response.insert("found".into(), Value::from(true));
    response.insert("segment".into(), segment);
    governance_dag_json_response(Value::Object(response), &etag)
}
fn governance_car_queue_lookup_segments(
    queue: &Value,
    map_name: &str,
    key: &str,
) -> Result<Vec<Value>, Response> {
    let Some(lookup) = queue.get(map_name).and_then(Value::as_object) else {
        return Err(json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            format!("governance DAG CAR queue is missing `{map_name}` lookup"),
        ));
    };
    let Some(positions) = lookup.get(key).and_then(Value::as_array) else {
        return Ok(Vec::new());
    };
    let segments = queue
        .get("segments")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "governance DAG CAR queue is missing `segments` array",
            )
        })?;
    let mut found = Vec::with_capacity(positions.len());
    for position in positions {
        let Some(position) = position.as_u64() else {
            return Err(json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("governance DAG CAR queue `{map_name}` entry is not numeric"),
            ));
        };
        let position = usize::try_from(position).map_err(|_| {
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "governance DAG CAR queue segment position exceeds host limits",
            )
        })?;
        let Some(segment) = segments.get(position).cloned() else {
            return Err(json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "governance DAG CAR queue lookup points outside `segments` array",
            ));
        };
        found.push(segment);
    }
    Ok(found)
}
fn normalize_governance_publish_digest_hex(raw: &str) -> Result<String, Response> {
    let digest_hex = normalize_governance_dag_lookup_hex(raw, "encoded_blake3_hex")?;
    if digest_hex.len() != 64 {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "encoded_blake3_hex must be 64 hexadecimal characters",
        ));
    }
    Ok(digest_hex)
}
fn normalize_governance_car_archive_digest_hex(raw: &str) -> Result<String, Response> {
    let digest_hex = normalize_governance_dag_lookup_hex(raw, "car_archive_blake3_hex")?;
    if digest_hex.len() != 64 {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "car_archive_blake3_hex must be 64 hexadecimal characters",
        ));
    }
    Ok(digest_hex)
}
fn normalize_governance_publish_kind(raw: &str) -> Result<String, Response> {
    let trimmed = raw.trim();
    if trimmed.is_empty() || matches!(trimmed, "." | "..") {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "payload_kind must be a non-reserved component",
        ));
    }
    if trimmed.len() > 128 {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "payload_kind must be 128 characters or fewer",
        ));
    }
    if !trimmed.as_bytes().iter().all(|byte| {
        byte.is_ascii_lowercase() || byte.is_ascii_digit() || matches!(*byte, b'_' | b'-' | b'.')
    }) {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "payload_kind must contain only lowercase ASCII letters, digits, '.', '-', or '_'",
        ));
    }
    Ok(trimmed.to_string())
}
fn governance_dag_json_response(value: Value, etag: &str) -> Response {
    let mut response = JsonBody(value).into_response();
    insert_governance_dag_cache_headers(&mut response, etag);
    response
}
fn governance_dag_representation_etag(
    base_etag: &str,
    domain: &str,
    components: &[&str],
) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"sorafs.governance_dag.http_representation.etag.v1");
    for value in std::iter::once(base_etag)
        .chain(std::iter::once(domain))
        .chain(components.iter().copied())
    {
        hasher.update(&u64::try_from(value.len()).unwrap_or(u64::MAX).to_le_bytes());
        hasher.update(value.as_bytes());
    }
    format!("\"{}\"", encode(hasher.finalize().as_bytes()))
}
fn governance_dag_not_modified_response(headers: &HeaderMap, etag: &str) -> Option<Response> {
    if !if_none_match_matches(headers, etag) {
        return None;
    }
    let mut response = Response::new(Body::empty());
    *response.status_mut() = StatusCode::NOT_MODIFIED;
    insert_governance_dag_cache_headers(&mut response, etag);
    Some(response)
}
fn insert_governance_dag_cache_headers(response: &mut Response, etag: &str) {
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static(GOVERNANCE_DAG_CACHE_CONTROL),
    );
    if let Ok(value) = HeaderValue::from_str(etag) {
        response.headers_mut().insert(ETAG, value);
    }
}
fn limit_governance_publish_index_entries(
    mut index: Value,
    limit: usize,
) -> Result<(Value, usize, bool), Response> {
    let Some(entries) = index.get_mut("entries").and_then(Value::as_array_mut) else {
        return Err(json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "governance DAG publish index is missing `entries` array",
        ));
    };
    let entry_count = entries.len();
    let truncated = entry_count > limit;
    entries.truncate(limit);
    Ok((index, entry_count, truncated))
}
fn ready_reputation_committed_projection(
    state: &SharedAppState,
) -> Result<
    (
        Arc<dyn ReputationCommittedReadApiV1>,
        ReputationCommittedReadProjectionV1,
    ),
    Response,
> {
    let Some(reader) = state.sorafs_reputation_committed_reader.clone() else {
        return Err(json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "committed reputation runtime is unavailable",
        ));
    };
    let projection = reader.committed_read_projection().map_err(|_| {
        json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "committed reputation runtime is unavailable",
        )
    })?;
    if projection.latest.is_none() {
        return Err(json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "committed reputation projection is not ready",
        ));
    }
    Ok((reader, projection))
}
fn reputation_committed_events_since(
    projection: &ReputationCommittedReadProjectionV1,
    since: Option<u64>,
    limit: usize,
) -> Vec<ReputationSnapshotEventV1> {
    let after = since.unwrap_or(0);
    projection
        .events
        .iter()
        .filter(|event| event.sequence > after)
        .take(limit)
        .cloned()
        .collect()
}
fn reputation_snapshot_from_committed_projection(
    projection: &ReputationCommittedReadProjectionV1,
) -> Result<&ReputationSnapshotV1, Response> {
    projection
        .latest
        .as_ref()
        .map(|latest| &latest.signed_result.snapshot)
        .ok_or_else(|| {
            json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "committed reputation projection is not ready",
            )
        })
}
fn require_reputation_canonical_auth(
    state: &SharedAppState,
    headers: &HeaderMap,
    method: &Method,
    uri: &Uri,
    body: &[u8],
) -> Result<(), Response> {
    let authentication_owner =
        match crate::history_producer::HistoryProducerOwner::authentication_read(state) {
            Ok(owner) => owner,
            Err(error) => {
                return Err(error.into_response());
            }
        };

    if method != Method::GET {
        return Err(json_error(
            StatusCode::METHOD_NOT_ALLOWED,
            "SoraFS reputation routes accept GET only",
        ));
    }
    match crate::app_auth::verify_canonical_network_request(
        &state.state,
        state.state.network_id_ref(),
        headers,
        crate::app_auth::CanonicalRequestParts { method, uri, body },
        None,
        authentication_owner.allocation_context(),
    ) {
        Ok(Some(_)) => Ok(()),
        Ok(None) | Err(_) => Err(reputation_authentication_required_response()),
    }
}
fn reputation_authentication_required_response() -> Response {
    let mut response = Response::new(Body::empty());
    *response.status_mut() = StatusCode::UNAUTHORIZED;
    insert_reputation_stream_cache_headers(&mut response);
    response
}
/// Apply authenticated cache isolation to a SoraFS reputation route response.
pub(crate) fn finalize_reputation_route_response(response: Response) -> Response {
    let mut response = normalize_reputation_framework_error(response);
    if response.status().is_client_error() || response.status().is_server_error() {
        insert_reputation_stream_cache_headers(&mut response);
    }
    response
}
fn normalize_reputation_framework_error(response: Response) -> Response {
    let status = response.status();
    if status == StatusCode::UNAUTHORIZED || reputation_response_is_json(&response) {
        return response;
    }
    let message = match status {
        StatusCode::BAD_REQUEST => REPUTATION_FRAMEWORK_BAD_REQUEST_ERROR,
        StatusCode::METHOD_NOT_ALLOWED => REPUTATION_FRAMEWORK_METHOD_NOT_ALLOWED_ERROR,
        StatusCode::PAYLOAD_TOO_LARGE => REPUTATION_FRAMEWORK_PAYLOAD_TOO_LARGE_ERROR,
        StatusCode::UPGRADE_REQUIRED => REPUTATION_FRAMEWORK_UPGRADE_REQUIRED_ERROR,
        _ => return response,
    };
    let (mut parts, _) = response.into_parts();
    let (json_parts, json_body) = json_error(status, message).into_parts();
    for name in [
        header::CONTENT_ENCODING,
        header::CONTENT_LENGTH,
        header::CONTENT_TYPE,
        header::TRANSFER_ENCODING,
    ] {
        parts.headers.remove(name);
    }
    if let Some(content_type) = json_parts.headers.get(header::CONTENT_TYPE) {
        parts
            .headers
            .insert(header::CONTENT_TYPE, content_type.clone());
    }
    Response::from_parts(parts, json_body)
}
fn reputation_response_is_json(response: &Response) -> bool {
    response
        .headers()
        .get(header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| {
            value
                .split_once(';')
                .map_or(value, |(media_type, _)| media_type)
                .trim()
                .eq_ignore_ascii_case("application/json")
        })
}
/// Harden framework-generated SoraFS reputation route failures.
pub(crate) async fn harden_reputation_route_responses(
    request: axum::extract::Request,
    next: axum::middleware::Next,
) -> Response {
    finalize_reputation_route_response(next.run(request).await)
}
fn require_empty_reputation_get_body(body: &[u8]) -> Result<(), Response> {
    if body.is_empty() {
        Ok(())
    } else {
        Err(json_error(
            StatusCode::BAD_REQUEST,
            "SoraFS reputation GET requests must have an empty body",
        ))
    }
}
fn require_reputation_request_target(
    uri: &Uri,
    expected_path: &str,
    raw_query: Option<&str>,
) -> Result<(), Response> {
    if uri.path() != expected_path || uri.query() != raw_query {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "SoraFS reputation request target does not match the canonical route and query",
        ));
    }
    Ok(())
}
fn reputation_page_limit(limit: Option<u16>) -> usize {
    limit.map_or(DEFAULT_LIST_LIMIT, usize::from)
}
fn parse_reputation_snapshot_id(uri: &Uri, snapshot_id_hex: &str) -> Result<[u8; 16], Response> {
    let expected_path = format!("{REPUTATION_SNAPSHOT_PATH_PREFIX_V1}{snapshot_id_hex}");
    if uri.path() != expected_path {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "snapshot_id_hex path segment must use its exact canonical spelling",
        ));
    }
    let snapshot_id = parse_canonical_hex_fixed::<16>(snapshot_id_hex, "snapshot_id_hex")
        .map_err(|error| json_error(StatusCode::BAD_REQUEST, error))?;
    if snapshot_id == [0; 16] {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "snapshot_id_hex must be non-zero",
        ));
    }
    Ok(snapshot_id)
}
fn validate_reputation_provider_id(uri: &Uri, provider_id: &str) -> Result<(), Response> {
    let expected_path = format!("{REPUTATION_PROVIDER_PATH_PREFIX_V1}{provider_id}");
    if uri.path() != expected_path {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "provider_id path segment must use its exact canonical spelling",
        ));
    }
    if provider_id.is_empty()
        || matches!(provider_id, "." | "..")
        || provider_id.len() > 256
        || !provider_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b':'))
    {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "provider_id must be 1..=256 ASCII bytes from [A-Za-z0-9_.:-], excluding . and ..",
        ));
    }
    Ok(())
}
pub(crate) async fn handle_get_sorafs_reputation_latest(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    body: Bytes,
) -> Response {
    let response = async move {
        if let Err(response) =
            require_reputation_canonical_auth(&state, &headers, &method, &uri, body.as_ref())
        {
            return response;
        }
        if let Err(response) = require_empty_reputation_get_body(body.as_ref()) {
            return response;
        }
        if let Err(response) =
            require_reputation_request_target(&uri, REPUTATION_LATEST_PATH_V1, raw_query.as_deref())
        {
            return response;
        }
        if !state.sorafs_node.is_enabled() {
            return feature_disabled("sorafs reputation API is not enabled on this node");
        }
        let query = match ReputationSnapshotReadbackQuery::parse(raw_query.as_deref()) {
            Ok(query) => query,
            Err(err) => return err.into_response(),
        };
        let limit = reputation_page_limit(query.limit);
        let (_, projection) = match ready_reputation_committed_projection(&state) {
            Ok(projection) => projection,
            Err(response) => return response,
        };
        let snapshot = match reputation_snapshot_from_committed_projection(&projection) {
            Ok(snapshot) => snapshot,
            Err(response) => return response,
        };
        let etag = reputation_snapshot_etag(snapshot, limit);
        match authenticated_reputation_not_modified_response(&headers, &etag) {
            Ok(Some(response)) => return response,
            Ok(None) => {}
            Err(response) => return response,
        }
        match reputation_snapshot_summary_json(snapshot, limit) {
            Ok(value) => authenticated_reputation_json_response(value, &etag),
            Err(err) => json_error(StatusCode::INTERNAL_SERVER_ERROR, err),
        }
    }
    .await;
    finalize_reputation_route_response(response)
}
pub(crate) async fn handle_get_sorafs_reputation_snapshot(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    Path(snapshot_id_hex): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    body: Bytes,
) -> Response {
    let response = async move {
        if let Err(response) =
            require_reputation_canonical_auth(&state, &headers, &method, &uri, body.as_ref())
        {
            return response;
        }
        if let Err(response) = require_empty_reputation_get_body(body.as_ref()) {
            return response;
        }
        let expected_path = format!("{REPUTATION_SNAPSHOT_PATH_PREFIX_V1}{snapshot_id_hex}");
        if let Err(response) =
            require_reputation_request_target(&uri, &expected_path, raw_query.as_deref())
        {
            return response;
        }
        if !state.sorafs_node.is_enabled() {
            return feature_disabled("sorafs reputation API is not enabled on this node");
        }
        let query = match ReputationSnapshotReadbackQuery::parse(raw_query.as_deref()) {
            Ok(query) => query,
            Err(err) => return err.into_response(),
        };
        let limit = reputation_page_limit(query.limit);
        let snapshot_id = match parse_reputation_snapshot_id(&uri, &snapshot_id_hex) {
            Ok(snapshot_id) => snapshot_id,
            Err(response) => return response,
        };
        let (reader, _) = match ready_reputation_committed_projection(&state) {
            Ok(projection) => projection,
            Err(response) => return response,
        };
        let snapshot = match reader.committed_snapshot_by_id(snapshot_id) {
            Ok(Some(snapshot)) => snapshot,
            Ok(None) => {
                return json_error(
                    StatusCode::NOT_FOUND,
                    format!("reputation snapshot `{snapshot_id_hex}` was not found"),
                );
            }
            Err(_) => {
                return json_error(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "committed reputation runtime is unavailable",
                );
            }
        };
        let etag = reputation_snapshot_etag(&snapshot, limit);
        match authenticated_reputation_not_modified_response(&headers, &etag) {
            Ok(Some(response)) => return response,
            Ok(None) => {}
            Err(response) => return response,
        }
        match reputation_snapshot_summary_json(&snapshot, limit) {
            Ok(value) => authenticated_reputation_json_response(value, &etag),
            Err(err) => json_error(StatusCode::INTERNAL_SERVER_ERROR, err),
        }
    }
    .await;
    finalize_reputation_route_response(response)
}
