#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ModerationCommandRouteV1 {
    SubmitAppeal,
    RegisterEligibility,
    FinalizeSortition,
    AcceptAssignment,
    ActivateCase,
    SubmitCommit,
    RaiseChallenge,
    ResolveChallenge,
    SubmitReveal,
    FinalizeCase,
}
async fn submit_moderation_signed_transaction(
    state: SharedAppState,
    headers: HeaderMap,
    accept: Option<ExtractAccept>,
    transaction: SignedTransaction,
    route: ModerationCommandRouteV1,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs moderation ballot API is not enabled on this node");
    }
    if let Err(response) = validate_moderation_signed_transaction(&state, &transaction, route) {
        return response;
    }
    match crate::submit_signed_transaction_for_ingress(state, headers, accept, transaction).await {
        Ok(response) => response,
        Err(error) => error.into_response(),
    }
}
fn validate_moderation_signed_transaction(
    state: &SharedAppState,
    transaction: &SignedTransaction,
    route: ModerationCommandRouteV1,
) -> Result<(), Response> {
    if transaction.network_id() != Some(state.state.network_id_ref()) {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "SoraFS moderation transaction chain does not match this peer",
        ));
    }
    transaction.verify_signature().map_err(|_| {
        json_error(
            StatusCode::FORBIDDEN,
            "SoraFS moderation transaction signature or authority binding is invalid",
        )
    })?;

    if transaction.creation_time().is_zero()
        || transaction.time_to_live()
            != Some(Duration::from_millis(
                sorafs_node::moderation_orchestrator::MODERATION_TRANSACTION_TTL_MS_V1,
            ))
        || transaction.nonce().is_some()
        || !transaction.metadata().is_empty()
        || transaction.fee_payment_intent().validate().is_err()
        || transaction.attachments().is_some()
    {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "SoraFS moderation transaction violates the exact V1 signed-envelope policy",
        ));
    }
    let canonical_transaction = norito::to_bytes(transaction).map_err(|_| {
        json_error(
            StatusCode::BAD_REQUEST,
            "failed to encode canonical SoraFS moderation transaction",
        )
    })?;
    if canonical_transaction.len()
        > sorafs_node::moderation_orchestrator::MODERATION_SIGNED_TRANSACTION_MAX_BYTES_V1
    {
        return Err(json_error(
            StatusCode::PAYLOAD_TOO_LARGE,
            "SoraFS moderation transaction exceeds the canonical V1 byte bound",
        ));
    }
    let Executable::Instructions(instructions) = transaction.instructions() else {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "SoraFS moderation command transaction must contain one native instruction",
        ));
    };
    if instructions.len() != 1 {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "SoraFS moderation command transaction must contain exactly one native instruction",
        ));
    }
    let instruction = &instructions[0];
    let action = match route {
        ModerationCommandRouteV1::SubmitAppeal => instruction
            .as_any()
            .downcast_ref::<SubmitSorafsModerationAppeal>()
            .cloned()
            .map(ModerationNativeActionV1::SubmitAppeal),
        ModerationCommandRouteV1::RegisterEligibility => instruction
            .as_any()
            .downcast_ref::<RegisterSorafsModerationJurorEligibility>()
            .cloned()
            .map(ModerationNativeActionV1::RegisterEligibility),
        ModerationCommandRouteV1::FinalizeSortition => instruction
            .as_any()
            .downcast_ref::<FinalizeSorafsModerationSortition>()
            .cloned()
            .map(ModerationNativeActionV1::FinalizeSortition),
        ModerationCommandRouteV1::AcceptAssignment => instruction
            .as_any()
            .downcast_ref::<AcceptSorafsModerationJurorAssignment>()
            .cloned()
            .map(ModerationNativeActionV1::AcceptAssignment),
        ModerationCommandRouteV1::ActivateCase => instruction
            .as_any()
            .downcast_ref::<ActivateSorafsModerationCase>()
            .cloned()
            .map(ModerationNativeActionV1::ActivateCase),
        ModerationCommandRouteV1::SubmitCommit => instruction
            .as_any()
            .downcast_ref::<SubmitSorafsModerationCommit>()
            .cloned()
            .map(ModerationNativeActionV1::SubmitCommit),
        ModerationCommandRouteV1::RaiseChallenge => instruction
            .as_any()
            .downcast_ref::<RaiseSorafsModerationChallenge>()
            .cloned()
            .map(ModerationNativeActionV1::RaiseChallenge),
        ModerationCommandRouteV1::ResolveChallenge => instruction
            .as_any()
            .downcast_ref::<ResolveSorafsModerationChallenge>()
            .cloned()
            .map(ModerationNativeActionV1::ResolveChallenge),
        ModerationCommandRouteV1::SubmitReveal => instruction
            .as_any()
            .downcast_ref::<SubmitSorafsModerationReveal>()
            .cloned()
            .map(ModerationNativeActionV1::SubmitReveal),
        ModerationCommandRouteV1::FinalizeCase => instruction
            .as_any()
            .downcast_ref::<FinalizeSorafsModerationCase>()
            .cloned()
            .map(ModerationNativeActionV1::FinalizeCase),
    }
    .ok_or_else(|| moderation_route_instruction_mismatch_response(route))?;
    action
        .validate_for_authority(transaction.authority())
        .map_err(moderation_orchestrator_error_response)
}
fn moderation_route_instruction_mismatch_response(route: ModerationCommandRouteV1) -> Response {
    json_error(
        StatusCode::BAD_REQUEST,
        format!(
            "SoraFS moderation route requires exactly one `{}` native instruction",
            moderation_route_instruction_label(route)
        ),
    )
}
const fn moderation_route_instruction_label(route: ModerationCommandRouteV1) -> &'static str {
    match route {
        ModerationCommandRouteV1::SubmitAppeal => "SubmitSorafsModerationAppeal",
        ModerationCommandRouteV1::RegisterEligibility => "RegisterSorafsModerationJurorEligibility",
        ModerationCommandRouteV1::FinalizeSortition => "FinalizeSorafsModerationSortition",
        ModerationCommandRouteV1::AcceptAssignment => "AcceptSorafsModerationJurorAssignment",
        ModerationCommandRouteV1::ActivateCase => "ActivateSorafsModerationCase",
        ModerationCommandRouteV1::SubmitCommit => "SubmitSorafsModerationCommit",
        ModerationCommandRouteV1::RaiseChallenge => "RaiseSorafsModerationChallenge",
        ModerationCommandRouteV1::ResolveChallenge => "ResolveSorafsModerationChallenge",
        ModerationCommandRouteV1::SubmitReveal => "SubmitSorafsModerationReveal",
        ModerationCommandRouteV1::FinalizeCase => "FinalizeSorafsModerationCase",
    }
}
fn moderation_orchestrator_error_response(error: ModerationOrchestratorError) -> Response {
    let (status, public_message, class) = match error {
        ModerationOrchestratorError::InvalidAction(_) => (
            StatusCode::BAD_REQUEST,
            "invalid native moderation finalization request",
            "invalid_action",
        ),
        ModerationOrchestratorError::InvalidRequestBinding => (
            StatusCode::BAD_REQUEST,
            "invalid moderation request binding",
            "invalid_request_binding",
        ),
        ModerationOrchestratorError::InvalidPanelNotificationClaim => (
            StatusCode::BAD_REQUEST,
            "invalid moderation panel-notification claim",
            "invalid_panel_notification_claim",
        ),
        ModerationOrchestratorError::InvalidPanelNotificationReceipt => (
            StatusCode::BAD_REQUEST,
            "invalid moderation panel-notification receipt",
            "invalid_panel_notification_receipt",
        ),
        ModerationOrchestratorError::PanelNotificationClockRollback { .. } => (
            StatusCode::SERVICE_UNAVAILABLE,
            "moderation panel-notification clock is stale",
            "panel_notification_clock_rollback",
        ),
        ModerationOrchestratorError::PanelNotificationNotFound { .. } => (
            StatusCode::NOT_FOUND,
            "moderation panel notification was not found",
            "panel_notification_not_found",
        ),
        ModerationOrchestratorError::PanelNotificationClaimConflict { .. } => (
            StatusCode::CONFLICT,
            "moderation panel-notification claim conflicts with durable state",
            "panel_notification_claim_conflict",
        ),
        ModerationOrchestratorError::PanelNotificationReceiptConflict { .. } => (
            StatusCode::CONFLICT,
            "moderation panel-notification receipt conflicts with durable state",
            "panel_notification_receipt_conflict",
        ),
        ModerationOrchestratorError::AuthorityMismatch { .. } => (
            StatusCode::FORBIDDEN,
            "moderation finalization authority mismatch",
            "authority_mismatch",
        ),
        ModerationOrchestratorError::IdempotencyConflict { .. }
        | ModerationOrchestratorError::FinalizedConflict { .. } => (
            StatusCode::CONFLICT,
            "moderation finalization conflicts with an existing operation",
            "operation_conflict",
        ),
        ModerationOrchestratorError::ResourceExhausted { .. } => (
            StatusCode::TOO_MANY_REQUESTS,
            "moderation orchestration capacity is exhausted",
            "resource_exhausted",
        ),
        ModerationOrchestratorError::InvalidConfiguration(_) => (
            StatusCode::SERVICE_UNAVAILABLE,
            "moderation orchestration is unavailable",
            "invalid_configuration",
        ),
        ModerationOrchestratorError::FinalizedReaderUnavailable => (
            StatusCode::SERVICE_UNAVAILABLE,
            "finalized moderation state is unavailable",
            "finalized_reader_unavailable",
        ),
        ModerationOrchestratorError::InvalidFinalizedSnapshot(_) => (
            StatusCode::SERVICE_UNAVAILABLE,
            "finalized moderation state is invalid",
            "invalid_finalized_snapshot",
        ),
        ModerationOrchestratorError::StaleFinalizedCursor { .. } => (
            StatusCode::SERVICE_UNAVAILABLE,
            "finalized moderation state is stale",
            "stale_finalized_cursor",
        ),
        ModerationOrchestratorError::FinalizedEquivocation { .. } => (
            StatusCode::SERVICE_UNAVAILABLE,
            "finalized moderation state is inconsistent",
            "finalized_equivocation",
        ),
        ModerationOrchestratorError::CheckpointCorrupt(_)
        | ModerationOrchestratorError::CheckpointIo(_)
        | ModerationOrchestratorError::CheckpointDurabilityUncertain(_)
        | ModerationOrchestratorError::DurabilityFaulted
        | ModerationOrchestratorError::CheckpointStoreUnavailable
        | ModerationOrchestratorError::CheckpointStoreAmbiguous
        | ModerationOrchestratorError::CheckpointStoreFenced
        | ModerationOrchestratorError::CheckpointStoreEquivocation
        | ModerationOrchestratorError::PanelNotificationArchiveUnavailable
        | ModerationOrchestratorError::PanelNotificationArchiveAmbiguous
        | ModerationOrchestratorError::PanelNotificationArchiveRejected
        | ModerationOrchestratorError::PanelNotificationArchiveInvalid
        | ModerationOrchestratorError::GenerationOverflow
        | ModerationOrchestratorError::StateLockPoisoned
        | ModerationOrchestratorError::CheckpointStoreLockPoisoned => (
            StatusCode::SERVICE_UNAVAILABLE,
            "durable moderation orchestration is unavailable",
            "durability_failure",
        ),
    };
    warn!(
        error_class = class,
        "SoraFS moderation finalization failed closed"
    );
    json_error(status, public_message)
}
pub(crate) async fn handle_get_sorafs_moderation_ballots(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs moderation ballot API is not enabled on this node");
    }
    let query = match ModerationBallotListQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let snapshot = match cached_moderation_snapshot(&state) {
        Ok(snapshot) => snapshot,
        Err(response) => return response,
    };
    let total_count = snapshot.cases.len();
    let truncated = total_count > limit;
    let cases = match snapshot
        .cases
        .iter()
        .take(limit)
        .map(json::to_value)
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(cases) => cases,
        Err(_) => {
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode finalized SoraFS moderation cases",
            );
        }
    };
    JsonBody(json_object(vec![
        json_entry(
            "schema",
            Value::from("sorafs.moderation.finalized_cases.v1"),
        ),
        json_entry("source", Value::from("finalized_chain")),
        json_entry("finalized_height", Value::from(snapshot.finalized_height)),
        json_entry(
            "finalized_block_hash_hex",
            Value::from(hex::encode(snapshot.finalized_block_hash)),
        ),
        json_entry("count", total_count as u64),
        json_entry("returned_count", total_count.min(limit) as u64),
        json_entry("limit", limit as u64),
        json_entry("truncated", truncated),
        json_entry("cases", Value::Array(cases)),
    ]))
    .into_response()
}
pub(crate) async fn handle_get_sorafs_moderation_ballot(
    State(state): State<SharedAppState>,
    Path((case_id, round_id)): Path<(String, String)>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs moderation ballot API is not enabled on this node");
    }
    let query = match ModerationBallotListQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let snapshot = match cached_moderation_snapshot(&state) {
        Ok(snapshot) => snapshot,
        Err(response) => return response,
    };
    snapshot.case(&case_id, &round_id).map_or_else(
        || {
            json_error(
                StatusCode::NOT_FOUND,
                format!("SoraFS moderation ballot `{case_id}` round `{round_id}` was not found"),
            )
        },
        |record| {
            let (record, projection_arrays_truncated) =
                bounded_finalized_moderation_case_projection(record, limit);
            json::to_value(&record).map_or_else(
                |_| {
                    json_error(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "failed to encode finalized SoraFS moderation case",
                    )
                },
                |projection| {
                    JsonBody(json_object(vec![
                        json_entry("schema", Value::from("sorafs.moderation.finalized_case.v1")),
                        json_entry("source", Value::from("finalized_chain")),
                        json_entry("finalized_height", Value::from(snapshot.finalized_height)),
                        json_entry(
                            "finalized_block_hash_hex",
                            Value::from(hex::encode(snapshot.finalized_block_hash)),
                        ),
                        json_entry("limit", limit as u64),
                        json_entry(
                            "projection_arrays_truncated",
                            Value::from(projection_arrays_truncated),
                        ),
                        json_entry("case", projection),
                    ]))
                    .into_response()
                },
            )
        },
    )
}
fn bounded_finalized_moderation_case_projection(
    record: &sorafs_node::moderation_orchestrator::ModerationFinalizedCaseViewV1,
    limit: usize,
) -> (
    sorafs_node::moderation_orchestrator::ModerationFinalizedCaseViewV1,
    bool,
) {
    let mut bounded = record.clone();
    let truncated = bounded.commits.len() > limit
        || bounded.reveals.len() > limit
        || bounded.challenges.len() > limit
        || bounded.no_shows.len() > limit;
    bounded.commits.truncate(limit);
    bounded.reveals.truncate(limit);
    bounded.challenges.truncate(limit);
    bounded.no_shows.truncate(limit);
    (bounded, truncated)
}
pub(crate) async fn handle_get_sorafs_moderation_ballot_no_show_plan(
    State(state): State<SharedAppState>,
    Path((case_id, round_id)): Path<(String, String)>,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs moderation ballot API is not enabled on this node");
    }
    let snapshot = match cached_moderation_snapshot(&state) {
        Ok(snapshot) => snapshot,
        Err(response) => return response,
    };
    let Some(case) = snapshot.case(&case_id, &round_id) else {
        return json_error(
            StatusCode::NOT_FOUND,
            format!("SoraFS moderation ballot `{case_id}` round `{round_id}` was not found"),
        );
    };
    if case.outcome.is_none() {
        return json_error(
            StatusCode::CONFLICT,
            "authoritative SoraFS moderation no-shows are unavailable before finalization",
        );
    }
    let no_shows = match case
        .no_shows
        .iter()
        .map(json::to_value)
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(no_shows) => no_shows,
        Err(_) => {
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode authoritative SoraFS moderation no-shows",
            );
        }
    };
    JsonBody(json_object(vec![
        json_entry(
            "schema",
            Value::from("sorafs.moderation.finalized_no_shows.v1"),
        ),
        json_entry("source", Value::from("finalized_chain")),
        json_entry("case_id", Value::from(case_id)),
        json_entry("round_id", Value::from(round_id)),
        json_entry("finalized_height", Value::from(snapshot.finalized_height)),
        json_entry(
            "finalized_block_hash_hex",
            Value::from(hex::encode(snapshot.finalized_block_hash)),
        ),
        json_entry("count", no_shows.len() as u64),
        json_entry("no_shows", Value::Array(no_shows)),
    ]))
    .into_response()
}
fn cached_moderation_snapshot(
    state: &SharedAppState,
) -> Result<Arc<sorafs_node::moderation_orchestrator::ModerationFinalizedLedgerSnapshotV1>, Response>
{
    let Some(runtime) = state.sorafs_moderation_orchestrator.as_ref() else {
        return Err(json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "finalized-chain SoraFS moderation orchestration is unavailable",
        ));
    };
    runtime.snapshot().map_err(|error| {
        let error_class = match error {
            super::moderation_runtime::ModerationProjectionReadErrorV1::Cold => "cold",
            super::moderation_runtime::ModerationProjectionReadErrorV1::Stale => "stale",
            super::moderation_runtime::ModerationProjectionReadErrorV1::DependencyFailed => {
                "dependency_failed"
            }
            super::moderation_runtime::ModerationProjectionReadErrorV1::DeadlineExceeded => {
                "deadline_exceeded"
            }
            super::moderation_runtime::ModerationProjectionReadErrorV1::DeadLetters => {
                "dead_letters"
            }
            super::moderation_runtime::ModerationProjectionReadErrorV1::InvalidProjection => {
                "invalid_projection"
            }
            super::moderation_runtime::ModerationProjectionReadErrorV1::WorkerStopped => {
                "worker_stopped"
            }
            super::moderation_runtime::ModerationProjectionReadErrorV1::Poisoned => "poisoned",
        };
        warn!(
            error_class,
            "finalized SoraFS moderation projection is not ready"
        );
        json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "finalized SoraFS moderation projection is unavailable",
        )
    })
}
pub(crate) async fn handle_get_sorafs_moderation_ballot_events(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs moderation ballot API is not enabled on this node");
    }
    let query = match ModerationFinalizedEventsQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let since = query.since.unwrap_or(0);
    let snapshot = match cached_moderation_snapshot(&state) {
        Ok(snapshot) => snapshot,
        Err(response) => return response,
    };
    let tip_sequence = snapshot.events.last().map_or(0, |event| event.sequence);
    if since > tip_sequence {
        return json_error(
            StatusCode::BAD_REQUEST,
            "SoraFS moderation event cursor is ahead of the finalized event tip",
        );
    }
    if let Some(first) = snapshot.events.first() {
        let minimum_after_sequence = first.sequence.saturating_sub(1);
        if since < minimum_after_sequence {
            return json_error(
                StatusCode::CONFLICT,
                "SoraFS moderation event cursor is older than the retained finalized event suffix",
            );
        }
    }
    let events = snapshot
        .events
        .iter()
        .filter(|event| event.sequence > since)
        .take(limit)
        .cloned()
        .collect::<Vec<_>>();
    let etag = moderation_finalized_events_etag(
        snapshot.finalized_height,
        snapshot.finalized_block_hash,
        since,
        limit,
        tip_sequence,
    );
    if let Some(response) = reputation_not_modified_response(&headers, &etag) {
        return response;
    }
    let encoded_events = match events
        .iter()
        .map(json::to_value)
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(events) => events,
        Err(_) => {
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode finalized SoraFS moderation events",
            );
        }
    };
    let next_after = events
        .last()
        .map(sorafs_node::moderation_orchestrator::ModerationFinalizedEventV1::cursor);
    let next_after = match next_after.as_ref().map(json::to_value).transpose() {
        Ok(Some(cursor)) => cursor,
        Ok(None) => Value::Null,
        Err(_) => {
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode finalized SoraFS moderation event cursor",
            );
        }
    };
    reputation_json_response(
        json_object(vec![
            json_entry(
                "schema",
                Value::from("sorafs.moderation.finalized_events.v1"),
            ),
            json_entry("source", Value::from("finalized_chain")),
            json_entry("finalized_height", Value::from(snapshot.finalized_height)),
            json_entry(
                "finalized_block_hash_hex",
                Value::from(hex::encode(snapshot.finalized_block_hash)),
            ),
            json_entry("after_sequence", Value::from(since)),
            json_entry("limit", limit as u64),
            json_entry("tip_sequence", Value::from(tip_sequence)),
            json_entry(
                "has_more",
                Value::from(
                    events
                        .last()
                        .is_some_and(|event| event.sequence < tip_sequence),
                ),
            ),
            json_entry("next_after", next_after),
            json_entry("events", Value::Array(encoded_events)),
        ]),
        &etag,
    )
}
fn moderation_finalized_events_etag(
    finalized_height: u64,
    finalized_block_hash: [u8; 32],
    after_sequence: u64,
    limit: usize,
    tip_sequence: u64,
) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"sorafs.moderation.finalized-events-etag.v1");
    hasher.update(&finalized_height.to_le_bytes());
    hasher.update(&finalized_block_hash);
    hasher.update(&after_sequence.to_le_bytes());
    hasher.update(&u64::try_from(limit).unwrap_or(u64::MAX).to_le_bytes());
    hasher.update(&tip_sequence.to_le_bytes());
    format!("\"{}\"", hasher.finalize().to_hex())
}
pub(crate) async fn handle_get_sorafs_moderation_model_registry(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled(
            "sorafs moderation model registry API is not enabled on this node",
        );
    }
    let query = match ModerationModelRegistryReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_moderation_read_limit(query.limit);
    let read_view = match state.sorafs_node.moderation_model_registry_read_view(limit) {
        Ok(read_view) => read_view,
        Err(err) => return moderation_model_registry_error_response(err),
    };
    JsonBody(moderation_model_registry_snapshot_json(&read_view, limit)).into_response()
}
pub(crate) async fn handle_post_sorafs_moderation_model_registry_repro_manifest(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    body: Bytes,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled(
            "sorafs moderation model registry API is not enabled on this node",
        );
    }
    if let Err(response) =
        require_moderation_request_auth(&state, &headers, &method, &uri, body.as_ref(), None)
    {
        return response;
    }
    let request = match json::from_slice::<ModerationModelRegistryManifestRequestDto>(body.as_ref())
    {
        Ok(request) => request,
        Err(err) => {
            return json_error(
                StatusCode::BAD_REQUEST,
                format!("failed to decode SoraFS moderation model registry JSON: {err}"),
            );
        }
    };
    let manifest = match decode_moderation_model_registry_manifest::<ModerationReproManifestV1>(
        &request.manifest_b64,
        "reproducibility manifest",
    ) {
        Ok(manifest) => manifest,
        Err(response) => return response,
    };
    match state.sorafs_node.admit_moderation_repro_manifest(manifest) {
        Ok(record) => (
            StatusCode::ACCEPTED,
            JsonBody(moderation_repro_registry_admission_json(&record)),
        )
            .into_response(),
        Err(err) => moderation_model_registry_error_response(err),
    }
}
pub(crate) async fn handle_post_sorafs_moderation_model_registry_corpus_manifest(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    body: Bytes,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled(
            "sorafs moderation model registry API is not enabled on this node",
        );
    }
    if let Err(response) =
        require_moderation_request_auth(&state, &headers, &method, &uri, body.as_ref(), None)
    {
        return response;
    }
    let request = match json::from_slice::<ModerationModelRegistryManifestRequestDto>(body.as_ref())
    {
        Ok(request) => request,
        Err(err) => {
            return json_error(
                StatusCode::BAD_REQUEST,
                format!("failed to decode SoraFS moderation model registry JSON: {err}"),
            );
        }
    };
    let manifest = match decode_moderation_model_registry_manifest::<AdversarialCorpusManifestV1>(
        &request.manifest_b64,
        "adversarial corpus manifest",
    ) {
        Ok(manifest) => manifest,
        Err(response) => return response,
    };
    match state.sorafs_node.admit_moderation_corpus_manifest(manifest) {
        Ok(record) => (
            StatusCode::ACCEPTED,
            JsonBody(moderation_corpus_registry_admission_json(&record)),
        )
            .into_response(),
        Err(err) => moderation_model_registry_error_response(err),
    }
}
