pub(crate) async fn handle_post_sorafs_moderation_quarantine_appeal_handoff(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    Path(quarantine_id_hex): Path<String>,
    body: Bytes,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled(
            "sorafs moderation quarantine appeal handoff API is not enabled on this node",
        );
    }
    let verified =
        match require_appeal_finance_request_auth(&state, &headers, &method, &uri, body.as_ref()) {
            Ok(verified) => verified,
            Err(response) => return response,
        };
    let request =
        match json::from_slice::<ModerationQuarantineAppealHandoffRequestDto>(body.as_ref()) {
            Ok(request) => request,
            Err(err) => {
                return json_error(
                    StatusCode::BAD_REQUEST,
                    format!(
                        "failed to decode SoraFS moderation quarantine appeal handoff JSON: {err}"
                    ),
                );
            }
        };
    let quarantine_id = match parse_hex_fixed::<16>(&quarantine_id_hex, "quarantine_id_hex") {
        Ok(quarantine_id) => quarantine_id,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err),
    };
    let quarantine_id_hex = hex::encode(quarantine_id);
    let record = match state
        .sorafs_node
        .moderation_quarantine_record(&quarantine_id)
    {
        Ok(record) => record,
        Err(err) => return moderation_screening_error_response(err),
    };
    let Some(record) = record else {
        return json_error(
            StatusCode::NOT_FOUND,
            format!("SoraFS moderation quarantine record `{quarantine_id_hex}` was not found"),
        );
    };
    if record.state != ModerationQuarantineState::Reviewed {
        return json_error(
            StatusCode::CONFLICT,
            "SoraFS moderation quarantine appeal handoff requires a reviewed quarantine record",
        );
    }
    if record.reviewed_at_unix.is_none() {
        return json_error(
            StatusCode::CONFLICT,
            "SoraFS moderation quarantine appeal handoff requires reviewed_at_unix metadata",
        );
    }
    for (field, value) in [
        ("case_id", request.case_id.as_str()),
        ("round_id", request.round_id.as_str()),
    ] {
        if !iroha_data_model::sorafs::moderation_ledger::is_canonical_moderation_identifier_v1(
            value,
        ) {
            return json_error(
                StatusCode::BAD_REQUEST,
                format!("{field} must be a canonical native moderation identifier"),
            );
        }
    }
    if request.panel_size == 0
        || request.panel_size
            > u32::from(
                iroha_data_model::sorafs::moderation_ledger::MODERATION_LEDGER_MAX_PANEL_SIZE_V1,
            )
    {
        return json_error(
            StatusCode::BAD_REQUEST,
            "panel_size exceeds the native moderation ledger bound",
        );
    }
    let evidence_bundle_digest = match decode_hex_32_field(
        &request.evidence_bundle_digest_hex,
        "evidence_bundle_digest_hex",
    ) {
        Ok(digest)
            if digest != [0; 32] && request.evidence_bundle_digest_hex == hex::encode(digest) =>
        {
            digest
        }
        Ok(_) => {
            return json_error(
                StatusCode::BAD_REQUEST,
                "evidence_bundle_digest_hex must be non-zero canonical lowercase hexadecimal",
            );
        }
        Err(response) => return response,
    };
    let policy = &state.sorafs_appeal_finance_policy;
    if let Err(response) = require_appeal_finance_asset_ready(&state, policy) {
        return response;
    }
    if request.asset_definition_id != policy.asset_definition_id.to_string() {
        return json_error(
            StatusCode::BAD_REQUEST,
            format!(
                "appeal handoff asset_definition_id must equal governed asset `{}`",
                policy.asset_definition_id
            ),
        );
    }
    let config = policy.pricing();
    let quote_input = match appeal_quote_input(
        AppealPricingQuoteRequestDto {
            class: request.class.clone(),
            backlog: request.backlog,
            evidence_size_mb: request.evidence_size_mb,
            urgency: Some(request.urgency.clone()),
            panel_size: Some(request.panel_size),
        },
        config,
    ) {
        Ok(input) => input,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err),
    };
    let quote = match config.quote(quote_input) {
        Ok(quote) => quote,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err.to_string()),
    };
    let deposit_request = match moderation_quarantine_appeal_handoff_deposit_request(
        request,
        &quote,
        evidence_bundle_digest,
        policy,
    ) {
        Ok(request) => request,
        Err(err) => return json_error(StatusCode::INTERNAL_SERVER_ERROR, err),
    };
    let deposit_instruction = match appeal_finance_deposit_instruction(
        deposit_request.clone(),
        &verified.account,
        policy,
    ) {
        Ok(instruction) => instruction,
        Err(DepositInstructionError::Forbidden(reason)) => {
            return json_error(StatusCode::FORBIDDEN, reason);
        }
        Err(DepositInstructionError::Invalid(reason)) => {
            return json_error(StatusCode::BAD_REQUEST, reason);
        }
    };
    (
        StatusCode::OK,
        JsonBody(moderation_quarantine_appeal_handoff_json(
            &record,
            policy,
            quote_input,
            &quote,
            &deposit_request,
            &deposit_instruction,
        )),
    )
        .into_response()
}
