pub(crate) async fn handle_get_sorafs_orderbook_book(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let response = (|| {
        if !state.sorafs_node.is_enabled() {
            return feature_disabled("sorafs orderbook API is not enabled on this node");
        }
        let (expected, after, limit) = match orderbook_finalized_read_args(raw_query.as_deref()) {
            Ok(args) => args,
            Err(response) => return response,
        };
        let state_view = state.state.query_view();
        let status = match FindSorafsOrderbookStatus.execute(&state_view) {
            Ok(status) => status,
            Err(error) => return orderbook_finalized_query_error_response(error),
        };
        let page = match FindSorafsOrderbookOrders::new(expected, None, after, limit)
            .execute(&state_view)
        {
            Ok(page) => page,
            Err(error) => return orderbook_finalized_query_error_response(error),
        };
        orderbook_finalized_book_json(&status, &page)
            .map(JsonBody)
            .map(IntoResponse::into_response)
            .unwrap_or_else(orderbook_json_error)
    })();
    orderbook_api_response(&state.telemetry, ORDERBOOK_ROUTE_BOOK, response)
}
macro_rules! orderbook_page_handler {
    ($name:ident, $query:expr, $key:literal, $endpoint:expr) => {
        pub(crate) async fn $name(
            State(state): State<SharedAppState>,
            axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
        ) -> Response {
            let response = (|| {
                if !state.sorafs_node.is_enabled() {
                    return Err(feature_disabled(
                        "sorafs orderbook API is not enabled on this node",
                    ));
                }
                let (expected, after, limit) = orderbook_finalized_read_args(raw_query.as_deref())?;
                let page = ($query)(expected, after, limit)
                    .execute(&state.state.query_view())
                    .map_err(orderbook_finalized_query_error_response)?;
                Ok::<_, Response>(orderbook_finalized_page_response($key, &page))
            })()
            .unwrap_or_else(|response| response);
            orderbook_api_response(&state.telemetry, $endpoint, response)
        }
    };
}
orderbook_page_handler!(
    handle_get_sorafs_orderbook_trades,
    FindSorafsOrderbookTrades::new,
    "trades",
    ORDERBOOK_ROUTE_TRADES
);
orderbook_page_handler!(
    handle_get_sorafs_orderbook_channels,
    |expected, after, limit| FindSorafsOrderbookChannels::new(expected, None, after, limit),
    "channels",
    ORDERBOOK_ROUTE_CHANNELS
);
orderbook_page_handler!(
    handle_get_sorafs_orderbook_receipts,
    |expected, after, limit| FindSorafsOrderbookReceipts::new(expected, None, after, limit),
    "receipts",
    ORDERBOOK_ROUTE_RECEIPTS
);
fn orderbook_finalized_read_args(
    raw_query: Option<&str>,
) -> Result<(Option<OrderbookFinalizedCursorV1>, Option<[u8; 32]>, u32), Response> {
    let query =
        FinalizedOrderbookReadQuery::parse(raw_query).map_err(IntoResponse::into_response)?;
    Ok((
        query.expected_finalized_cursor()?,
        query.after_id()?,
        query.limit(),
    ))
}
fn orderbook_finalized_book_json(
    status: &OrderbookLedgerStatusV1,
    page: &OrderbookOrderPageV1,
) -> Result<Value, String> {
    Ok(json_object(vec![
        json_entry("source", "finalized_chain"),
        json_entry(
            "status",
            json::to_value(status)
                .map_err(|error| format!("failed to encode orderbook status: {error}"))?,
        ),
        json_entry(
            "orders",
            json::to_value(page)
                .map_err(|error| format!("failed to encode orderbook order page: {error}"))?,
        ),
    ]))
}
fn orderbook_finalized_page_response<T: norito::json::JsonSerialize>(
    key: &str,
    page: &T,
) -> Response {
    let page = json::to_value(page)
        .map_err(|error| format!("failed to encode orderbook {key} page: {error}"));
    page.map(|page| {
        JsonBody(json_object(vec![
            json_entry("source", "finalized_chain"),
            json_entry(key, page),
        ]))
        .into_response()
    })
    .unwrap_or_else(orderbook_json_error)
}
fn orderbook_json_error(error: String) -> Response {
    json_error(StatusCode::INTERNAL_SERVER_ERROR, error)
}
pub(crate) async fn handle_get_sorafs_orderbook_events(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let response = (|| {
        if !state.sorafs_node.is_enabled() {
            return feature_disabled("sorafs orderbook API is not enabled on this node");
        }
        let query = match FinalizedOrderbookEventQuery::parse(raw_query.as_deref()) {
            Ok(query) => query,
            Err(err) => return err.into_response(),
        };
        let expected = match query.expected_finalized_cursor() {
            Ok(expected) => expected,
            Err(response) => return response,
        };
        let after = match query.after() {
            Ok(after) => after,
            Err(response) => return response,
        };
        let state_view = state.state.query_view();
        let page = match FindSorafsOrderbookEvents::new(expected, after, query.limit())
            .execute(&state_view)
        {
            Ok(page) => page,
            Err(error) => return orderbook_finalized_query_error_response(error),
        };
        let etag = match orderbook_finalized_events_etag(&page) {
            Ok(etag) => etag,
            Err(error) => return json_error(StatusCode::INTERNAL_SERVER_ERROR, error),
        };
        if let Some(response) = reputation_not_modified_response(&headers, &etag) {
            return response;
        }
        match orderbook_finalized_event_page_json(&page) {
            Ok(value) => reputation_json_response(value, &etag),
            Err(error) => json_error(StatusCode::INTERNAL_SERVER_ERROR, error),
        }
    })();
    orderbook_api_response(&state.telemetry, ORDERBOOK_ROUTE_EVENTS, response)
}
pub(crate) async fn handle_get_sorafs_orderbook_events_stream(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let response = (|| {
        if !state.sorafs_node.is_enabled() {
            return feature_disabled("sorafs orderbook API is not enabled on this node");
        }
        let query = match FinalizedOrderbookEventQuery::parse(raw_query.as_deref()) {
            Ok(query) => query,
            Err(err) => return err.into_response(),
        };
        let expected = match query.expected_finalized_cursor() {
            Ok(expected) => expected,
            Err(response) => return response,
        };
        let after = match query.after() {
            Ok(after) => after,
            Err(response) => return response,
        };
        let state_view = state.state.query_view();
        let initial_page = match FindSorafsOrderbookEvents::new(expected, after, query.limit())
            .execute(&state_view)
        {
            Ok(page) => page,
            Err(error) => return orderbook_finalized_query_error_response(error),
        };
        let event_stream = orderbook_finalized_event_stream(
            state.clone(),
            initial_page.events,
            after,
            query.limit(),
        )
        .map(|event| Ok::<_, Infallible>(orderbook_finalized_sse_event(&event)));
        Sse::new(event_stream).into_response()
    })();
    orderbook_api_response(&state.telemetry, ORDERBOOK_ROUTE_EVENTS_STREAM, response)
}
pub(crate) async fn handle_get_sorafs_orderbook_events_ws(
    State(state): State<SharedAppState>,
    preauth_guard: Option<Extension<crate::PreAuthGuardHandoff>>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    ws: WebSocketUpgrade,
) -> Response {
    let response = (|| {
        if !state.sorafs_node.is_enabled() {
            return feature_disabled("sorafs orderbook API is not enabled on this node");
        }
        let query = match FinalizedOrderbookEventQuery::parse(raw_query.as_deref()) {
            Ok(query) => query,
            Err(err) => return err.into_response(),
        };
        let expected = match query.expected_finalized_cursor() {
            Ok(expected) => expected,
            Err(response) => return response,
        };
        let after = match query.after() {
            Ok(after) => after,
            Err(response) => return response,
        };
        let state_view = state.state.query_view();
        let initial_page = match FindSorafsOrderbookEvents::new(expected, after, query.limit())
            .execute(&state_view)
        {
            Ok(page) => page,
            Err(error) => return orderbook_finalized_query_error_response(error),
        };
        let stream_state = state.clone();
        let limit = query.limit();
        let preauth_guard = crate::take_preauth_upgrade_guard(preauth_guard);
        let shutdown = state.shutdown_signal.clone();
        ws.on_upgrade(move |socket| async move {
            let _ = crate::panic_recovery::catch_async_recoverable(async move {
                let _preauth_guard = preauth_guard;
                let stream = orderbook_finalized_event_websocket_stream(
                    socket,
                    stream_state,
                    initial_page.events,
                    after,
                    limit,
                );
                let result = tokio::select! {
                    () = shutdown.receive() => return,
                    result = stream => result,
                };
                if let Err(err) = result {
                    debug!(%err, "SoraFS orderbook WebSocket stream closed with error");
                }
            })
            .await;
        })
        .into_response()
    })();
    orderbook_api_response(&state.telemetry, ORDERBOOK_ROUTE_EVENTS_WS, response)
}
