pub(crate) async fn handle_post_sorafs_appeal_finance_deposit_settle(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    body: Bytes,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled(
            "sorafs appeal finance deposit settlement API is not enabled on this node",
        );
    }
    let verified =
        match require_appeal_finance_request_auth(&state, &headers, &method, &uri, body.as_ref()) {
            Ok(verified) => verified,
            Err(response) => return response,
        };
    let req = match json::from_slice::<AppealFinanceDepositSettleRequestDto>(body.as_ref()) {
        Ok(req) => req,
        Err(err) => {
            return json_error(
                StatusCode::BAD_REQUEST,
                format!("failed to decode SoraFS appeal finance deposit settlement JSON: {err}"),
            );
        }
    };
    let (expected, record) = match confirm_appeal_finance_deposit_record(
        &state,
        &req.deposit_confirmation,
        &verified.account,
    ) {
        Ok(confirmation) => confirmation,
        Err(response) => return response,
    };
    let policy = &state.sorafs_appeal_finance_policy;
    let config = policy.settlement();
    let deposit_xor =
        match parse_appeal_quantity_literal("deposit_xor", &expected.deposit_xor.to_string()) {
            Ok(value) => value,
            Err(err) => return json_error(StatusCode::BAD_REQUEST, err.to_string()),
        };
    let verdict = match appeal_verdict_from_request(&req.outcome) {
        Ok(value) => value,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err),
    };
    let panel_size = req
        .panel_size
        .unwrap_or_else(|| config.default_panel_size());
    let breakdown = match config.settle(deposit_xor, panel_size, verdict) {
        Ok(value) => value,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err.to_string()),
    };
    let execution =
        match appeal_finance_deposit_settlement_execution(&expected, &record, &breakdown) {
            Ok(execution) => execution,
            Err(err) => return json_error(StatusCode::BAD_REQUEST, err),
        };
    (
        StatusCode::OK,
        JsonBody(appeal_finance_deposit_settlement_execution_json(
            policy, &expected, &record, verdict, panel_size, &breakdown, &execution,
        )),
    )
        .into_response()
}
pub(crate) async fn handle_post_sorafs_appeal_finance_deposit_submit_settlement(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    body: Bytes,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled(
            "sorafs appeal finance deposit settlement submitter API is not enabled on this node",
        );
    }
    let verified =
        match require_appeal_finance_request_auth(&state, &headers, &method, &uri, body.as_ref()) {
            Ok(verified) => verified,
            Err(response) => return response,
        };
    let req = match json::from_slice::<AppealFinanceDepositSettleRequestDto>(body.as_ref()) {
        Ok(req) => req,
        Err(err) => {
            return json_error(
                StatusCode::BAD_REQUEST,
                format!(
                    "failed to decode SoraFS appeal finance deposit settlement submission JSON: {err}"
                ),
            );
        }
    };
    let (expected, record, finalized_cursor) =
        match load_appeal_finance_deposit_record_for_reconciliation(
            &state,
            &req.deposit_confirmation,
            &verified.account,
        ) {
            Ok(value) => value,
            Err(response) => return response,
        };
    match submit_appeal_finance_deposit_settlement_step(
        &state,
        expected,
        record,
        finalized_cursor,
        &req.outcome,
        req.panel_size,
    )
    .await
    {
        Ok((status, body)) => (status, JsonBody(body)).into_response(),
        Err(response) => response,
    }
}
async fn submit_appeal_finance_deposit_settlement_step(
    state: &SharedAppState,
    expected: AppealFinanceDepositExpectation,
    record: AssetEscrowRecord,
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
    outcome: &str,
    panel_size: Option<u32>,
) -> Result<(StatusCode, Value), Response> {
    let policy = &state.sorafs_appeal_finance_policy;
    let config = policy.settlement();
    let deposit_xor =
        match parse_appeal_quantity_literal("deposit_xor", &expected.deposit_xor.to_string()) {
            Ok(value) => value,
            Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err.to_string())),
        };
    let verdict = match appeal_verdict_from_request(outcome) {
        Ok(value) => value,
        Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err)),
    };
    let panel_size = panel_size.unwrap_or_else(|| config.default_panel_size());
    let breakdown = match config.settle(deposit_xor, panel_size, verdict) {
        Ok(value) => value,
        Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err.to_string())),
    };
    let reconciliation = match appeal_finance_deposit_settlement_reconciliation(
        &expected, &record, policy, verdict, panel_size, &breakdown,
    ) {
        Ok(value) => value,
        Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err)),
    };
    let execution =
        match appeal_finance_deposit_settlement_execution(&expected, &record, &breakdown) {
            Ok(value) => value,
            Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err)),
        };
    if reconciliation.status == "settled" {
        return Ok((
            StatusCode::OK,
            appeal_finance_deposit_settlement_submission_json(
                policy,
                &expected,
                &record,
                verdict,
                panel_size,
                &breakdown,
                &reconciliation,
                None,
                None,
                0,
                "already_reconciled",
                None,
                "not_applicable",
                None,
            ),
        ));
    }
    if reconciliation.status == "mismatch" {
        return Ok((
            StatusCode::CONFLICT,
            appeal_finance_deposit_settlement_submission_json(
                policy,
                &expected,
                &record,
                verdict,
                panel_size,
                &breakdown,
                &reconciliation,
                None,
                None,
                0,
                "mismatch",
                None,
                "not_applicable",
                None,
            ),
        ));
    }
    let Some(step) =
        appeal_finance_deposit_next_settlement_submission_step(&reconciliation, &execution)
    else {
        return Err(json_error(
            StatusCode::CONFLICT,
            "SoraFS appeal finance settlement state has no submitter action",
        ));
    };
    let Some(submitter) = state.sorafs_appeal_settlement_submitter.as_ref() else {
        return Ok((
            StatusCode::SERVICE_UNAVAILABLE,
            appeal_finance_deposit_settlement_submission_json(
                policy,
                &expected,
                &record,
                verdict,
                panel_size,
                &breakdown,
                &reconciliation,
                Some(step),
                None,
                0,
                "submitter_not_configured",
                None,
                "not_applicable",
                None,
            ),
        ));
    };
    if execution.steps.iter().any(|planned_step| {
        submitter
            .signer_for(&planned_step.required_authority, finalized_cursor.height)
            .is_err()
    }) {
        return Ok((
            StatusCode::SERVICE_UNAVAILABLE,
            appeal_finance_deposit_settlement_submission_json(
                policy,
                &expected,
                &record,
                verdict,
                panel_size,
                &breakdown,
                &reconciliation,
                Some(step),
                None,
                submitter.signer_count(finalized_cursor.height),
                "missing_required_signer",
                None,
                "not_applicable",
                None,
            ),
        ));
    }
    use sorafs_node::appeal_finance_transaction_forwarder::{
        AppealFinanceOperationV1, AppealFinanceTransactionContextV1,
        AppealFinanceTransactionEnqueueResultV1,
    };
    let operation = match step.action {
        "drawdown_non_refund" => AppealFinanceOperationV1::Drawdown(DrawdownAssetLock::new(
            expected.escrow_id,
            step.amount_xor.clone(),
            record.remaining_amount.clone(),
        )),
        "cancel_refund" => AppealFinanceOperationV1::Cancel(CancelAssetLock::new(
            expected.escrow_id,
            record.remaining_amount.clone(),
        )),
        other => {
            return Err(json_error(
                StatusCode::BAD_REQUEST,
                format!("unsupported SoraFS appeal finance settlement step `{other}`"),
            ));
        }
    };
    let reconciliation_context = norito::to_bytes(&AppealFinanceSettlementOutboxContextV1 {
        version: APPEAL_FINANCE_SETTLEMENT_OUTBOX_CONTEXT_VERSION_V1,
        policy_digest: policy.policy_digest,
        settlement: AppealFinanceSettlementSnapshotV1::from_policy_and_breakdown(
            policy, &breakdown,
        ),
        expected: expected.clone(),
        outcome: verdict.to_string(),
        panel_size,
    })
    .map_err(|error| {
        json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            format!("failed to encode SoraFS appeal finance settlement outbox context: {error}"),
        )
    })?;
    let context = AppealFinanceTransactionContextV1 {
        network_id: *state.state.network_id_ref(),
        chain_id: (*state.chain_id).clone(),
        finalized_cursor,
        expected_record: Some(record.clone()),
        reconciliation_context,
    };
    let enqueue = match submitter.forwarder.enqueue_unsigned_operation(
        step.required_authority.clone(),
        operation,
        &context,
    ) {
        Ok(enqueue) => enqueue,
        Err(
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionForwarderError::IdentityConflict
            | sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionForwarderError::DeadLetterConflict,
        ) => {
            return Ok((
                StatusCode::CONFLICT,
                appeal_finance_deposit_settlement_submission_json(
                    policy,
                    &expected,
                    &record,
                    verdict,
                    panel_size,
                    &breakdown,
                    &reconciliation,
                    Some(step),
                    None,
                    submitter.signer_count(finalized_cursor.height),
                    "durable_identity_conflict",
                    None,
                    "not_applicable",
                    None,
                ),
            ));
        }
        Err(error) => {
            return Err(json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                format!("failed to durably enqueue SoraFS appeal finance settlement: {error}"),
            ));
        }
    };
    let operation_id_hex = hex::encode(enqueue.operation_id());
    let status = match enqueue {
        AppealFinanceTransactionEnqueueResultV1::Inserted { .. } => "durably_enqueued",
        AppealFinanceTransactionEnqueueResultV1::Existing { .. } => "already_durably_enqueued",
    };
    Ok((
        StatusCode::ACCEPTED,
        appeal_finance_deposit_settlement_submission_json(
            policy,
            &expected,
            &record,
            verdict,
            panel_size,
            &breakdown,
            &reconciliation,
            Some(step),
            Some(&operation_id_hex),
            submitter.signer_count(finalized_cursor.height),
            status,
            None,
            "awaiting_finalized_commit",
            None,
        ),
    ))
}
const SORAFS_APPEAL_FINANCE_FORWARDER_SCAN_LIMIT_V1: usize = 256;
fn appeal_finance_finalized_cursor_from_view(
    view: &impl StateReadOnly,
) -> Option<sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1> {
    u64::try_from(view.block_hashes().len())
        .ok()
        .zip(view.block_hashes().last())
        .map(|(height, hash)| {
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1 {
                height,
                block_hash: *hash.as_ref(),
            }
        })
        .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
}
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsAppealFinanceForwarderScanV1 {
    scanned: usize,
    finalized: usize,
    signed: usize,
    submitted: usize,
    deferred: usize,
    dead_lettered: usize,
    followups_enqueued: usize,
}
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsAppealFinanceForwarderCursorV1 {
    after_sequence: Option<u64>,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AppealFinanceSubmissionDispositionV1 {
    Submitted,
    DefinitelyNotSubmitted,
    Rejected,
    Ambiguous,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AppealFinanceDeliverySubmitOutcomeV1 {
    Submitted,
    Deferred,
    DeadLettered,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AppealFinanceCommittedExternalOutcomeV1 {
    Applied,
    Rejected,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AppealFinanceAuthoritativeTransactionOutcomeV1 {
    Absent,
    Applied {
        block_height: u64,
        block_hash: [u8; 32],
        block_timestamp_ms: u64,
    },
    Rejected,
    Unavailable,
}
fn classify_local_appeal_finance_submission(
    error: &iroha_core::queue::Error,
) -> AppealFinanceSubmissionDispositionV1 {
    match error {
        iroha_core::queue::Error::InBlockchain | iroha_core::queue::Error::IsInQueue => {
            AppealFinanceSubmissionDispositionV1::Submitted
        }
        iroha_core::queue::Error::Expired
        | iroha_core::queue::Error::TransactionDomainMismatch(_) => {
            AppealFinanceSubmissionDispositionV1::Rejected
        }
        _ => AppealFinanceSubmissionDispositionV1::DefinitelyNotSubmitted,
    }
}
fn classify_exact_appeal_finance_entrypoint_outcome(
    expected_hash: &HashOf<SignedTransaction>,
    block_available: bool,
    applied_block: Option<(u64, [u8; 32], u64)>,
    results: impl IntoIterator<
        Item = (
            HashOf<SignedTransaction>,
            AppealFinanceCommittedExternalOutcomeV1,
        ),
    >,
) -> AppealFinanceAuthoritativeTransactionOutcomeV1 {
    if !block_available {
        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    let mut exact = results
        .into_iter()
        .filter_map(|(hash, outcome)| (&hash == expected_hash).then_some(outcome));
    let Some(outcome) = exact.next() else {
        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
    };
    if exact.next().is_some() {
        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    match outcome {
        AppealFinanceCommittedExternalOutcomeV1::Applied => applied_block.map_or(
            AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable,
            |(block_height, block_hash, block_timestamp_ms)| {
                AppealFinanceAuthoritativeTransactionOutcomeV1::Applied {
                    block_height,
                    block_hash,
                    block_timestamp_ms,
                }
            },
        ),
        AppealFinanceCommittedExternalOutcomeV1::Rejected => {
            AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected
        }
    }
}
fn inspect_indexed_appeal_finance_transaction(
    state: &iroha_core::state::State,
    transaction_hash: &HashOf<SignedTransaction>,
    block_height: NonZeroUsize,
    expected_block_hash: HashOf<BlockHeader>,
) -> AppealFinanceAuthoritativeTransactionOutcomeV1 {
    let Ok((header, outcome)) = crate::canonical_history::exact_external_outcome(
        state,
        block_height,
        expected_block_hash,
        transaction_hash,
    ) else {
        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
    };
    let applied_block = Some((
        header.height().get(),
        *expected_block_hash.as_ref(),
        u64::try_from(header.creation_time().as_millis()).unwrap_or(u64::MAX),
    ));
    classify_exact_appeal_finance_entrypoint_outcome(
        transaction_hash,
        true,
        applied_block,
        outcome.map(|applied| {
            (
                *transaction_hash,
                if applied {
                    AppealFinanceCommittedExternalOutcomeV1::Applied
                } else {
                    AppealFinanceCommittedExternalOutcomeV1::Rejected
                },
            )
        }),
    )
}
fn observe_appeal_finance_finalized_state(
    state: &SharedAppState,
    escrow_id: &EscrowId,
    transaction_hash: Option<&HashOf<SignedTransaction>>,
) -> Option<(
    sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
    Option<AssetEscrowRecord>,
    Option<AppealFinanceAuthoritativeTransactionOutcomeV1>,
)> {
    let view = state.state.view();
    let finalized_cursor = appeal_finance_finalized_cursor_from_view(&view)?;
    let record = view.world().asset_escrows().get(escrow_id).cloned();
    // Capture all economic state and the exact indexed carrier in one view.
    // Historical authentication owns no World read lock.
    let indexed = transaction_hash.map(|hash| {
        let input = iroha_core::tx::external_entrypoint_hash_from_signed_hash(*hash);
        let height = view.transactions().get(&input);
        let carrier = height.and_then(|height| {
            view.block_hashes()
                .get(height.get() - 1)
                .copied()
                .map(|hash| (height, hash))
        });
        (input, height, carrier)
    });
    drop(view);
    let transaction_outcome = transaction_hash
        .zip(indexed)
        .map(|(hash, (_, height, carrier))| match (height, carrier) {
            (None, _) => AppealFinanceAuthoritativeTransactionOutcomeV1::Absent,
            (Some(_), None) => AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable,
            (Some(_), Some((height, expected))) => {
                inspect_indexed_appeal_finance_transaction(&state.state, hash, height, expected)
            }
        });
    let current = state.state.view();
    let cursor_height = usize::try_from(finalized_cursor.height).ok()?;
    if current
        .block_hashes()
        .get(cursor_height.checked_sub(1)?)
        .map(|hash| *hash.as_ref())
        != Some(finalized_cursor.block_hash)
        || indexed.is_some_and(|(input, height, _)| current.transactions().get(&input) != height)
    {
        return None;
    }
    Some((finalized_cursor, record, transaction_outcome))
}
#[cfg(test)]
mod appeal_finance_authoritative_outcome_tests {
    use super::*;
    fn transaction_hash(byte: u8) -> HashOf<SignedTransaction> {
        HashOf::from_untyped_unchecked(Hash::prehashed([byte; 32]))
    }
    #[test]
    fn exact_finalized_transaction_outcome_rejects_missing_and_duplicate_index_entries() {
        let expected = transaction_hash(1);
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &expected,
                false,
                None,
                Vec::<(
                    HashOf<SignedTransaction>,
                    AppealFinanceCommittedExternalOutcomeV1,
                )>::new(),
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable
        );
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &expected,
                true,
                Some((1, [2; 32], 3)),
                [(
                    transaction_hash(2),
                    AppealFinanceCommittedExternalOutcomeV1::Applied,
                )],
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable
        );
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &expected,
                true,
                Some((1, [2; 32], 3)),
                [
                    (
                        expected.clone(),
                        AppealFinanceCommittedExternalOutcomeV1::Applied,
                    ),
                    (expected, AppealFinanceCommittedExternalOutcomeV1::Applied,),
                ],
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable
        );
    }
    #[test]
    fn exact_finalized_transaction_outcome_distinguishes_apply_and_reject() {
        let applied = transaction_hash(3);
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &applied,
                true,
                Some((7, [9; 32], 11)),
                [(
                    applied.clone(),
                    AppealFinanceCommittedExternalOutcomeV1::Applied,
                )],
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Applied {
                block_height: 7,
                block_hash: [9; 32],
                block_timestamp_ms: 11,
            }
        );
        let rejected = transaction_hash(4);
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &rejected,
                true,
                Some((8, [10; 32], 12)),
                [(
                    rejected.clone(),
                    AppealFinanceCommittedExternalOutcomeV1::Rejected,
                )],
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected
        );
    }
}
pub(crate) fn spawn_sorafs_appeal_finance_forwarder_worker(
    state: SharedAppState,
    shutdown_signal: ShutdownSignal,
) -> Option<tokio::task::JoinHandle<crate::ToriiCriticalWorkerExit>> {
    let Some(submitter) = state.sorafs_appeal_settlement_submitter.as_ref() else {
        debug!("SoraFS appeal-finance forwarder disabled: storage is disabled");
        return None;
    };
    let worker_interval = submitter.worker_scan_interval();
    Some(tokio::spawn(async move {
        let mut interval = tokio::time::interval(worker_interval);
        let mut cursor = SorafsAppealFinanceForwarderCursorV1::default();
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
        loop {
            tokio::select! {
                biased;
                () = shutdown_signal.receive() => {
                    return crate::ToriiCriticalWorkerExit::StoppedByShutdown;
                }
                _ = interval.tick() => {
                    if shutdown_signal.is_sent() {
                        return crate::ToriiCriticalWorkerExit::StoppedByShutdown;
                    }
                    let scan = run_sorafs_appeal_finance_forwarder_scan(&state, &mut cursor).await;
                    if scan.scanned != 0 {
                        debug!(
                            scanned = scan.scanned,
                            finalized = scan.finalized,
                            signed = scan.signed,
                            submitted = scan.submitted,
                            deferred = scan.deferred,
                            dead_lettered = scan.dead_lettered,
                            followups_enqueued = scan.followups_enqueued,
                            "processed durable SoraFS appeal-finance deliveries"
                        );
                    }
                }
            }
        }
    }))
}
pub(crate) async fn run_sorafs_appeal_finance_forwarder_scan(
    state: &SharedAppState,
    cursor: &mut SorafsAppealFinanceForwarderCursorV1,
) -> SorafsAppealFinanceForwarderScanV1 {
    use sorafs_node::appeal_finance_transaction_forwarder::{
        AppealFinanceOperationReconciliationV1, AppealFinanceTransactionDeliveryStateV1,
        AppealFinanceTransactionForwarderError, reconcile_appeal_finance_operation_v1,
    };
    let mut scan = SorafsAppealFinanceForwarderScanV1::default();
    let Some(submitter) = state.sorafs_appeal_settlement_submitter.as_ref() else {
        return scan;
    };
    let pending = match submitter.forwarder.pending_after(
        cursor.after_sequence,
        SORAFS_APPEAL_FINANCE_FORWARDER_SCAN_LIMIT_V1,
    ) {
        Ok(pending) => pending,
        Err(error) => {
            warn!(%error, "failed to load durable SoraFS appeal-finance deliveries");
            return scan;
        }
    };
    for delivery in pending {
        cursor.after_sequence = Some(delivery.sequence);
        scan.scanned = scan.scanned.saturating_add(1);
        let request = match submitter
            .forwarder
            .operation_for_reconciliation(delivery.operation_id)
        {
            Ok(request) => request,
            Err(_) => {
                scan.deferred = scan.deferred.saturating_add(1);
                continue;
            }
        };
        if request.network_id != *state.state.network_id_ref()
            || request.chain_id != *state.chain_id
        {
            scan.deferred = scan.deferred.saturating_add(1);
            warn!(
                "durable SoraFS appeal-finance delivery belongs to another network or business chain"
            );
            continue;
        }
        let signed_transaction = delivery
            .signed_transaction_bytes
            .as_deref()
            .and_then(|bytes| decode_appeal_finance_signed_transaction(bytes, &request.network_id));
        let transaction_hash = signed_transaction.as_ref().map(SignedTransaction::hash);
        let Some((finalized_cursor, record, transaction_outcome)) =
            observe_appeal_finance_finalized_state(
                state,
                request.operation.escrow_id(),
                transaction_hash.as_ref(),
            )
        else {
            scan.deferred = scan.deferred.saturating_add(1);
            continue;
        };
        let policy_status =
            appeal_finance_outbox_policy_status(&request, &state.sorafs_appeal_finance_policy);
        if policy_status == AppealFinanceOutboxPolicyStatusV1::InvalidContext {
            if submitter
                .forwarder
                .mark_invalid_context(delivery.operation_id, finalized_cursor)
                .is_ok()
            {
                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
            } else {
                scan.deferred = scan.deferred.saturating_add(1);
            }
            continue;
        }
        let reconciliation = match reconcile_appeal_finance_operation_v1(
            &request,
            finalized_cursor,
            record.as_ref(),
        ) {
            Ok(reconciliation) => reconciliation,
            Err(AppealFinanceTransactionForwarderError::StaleFinalizedCursor) => {
                if submitter
                    .forwarder
                    .mark_stale_finalized_cursor(delivery.operation_id, finalized_cursor)
                    .is_ok()
                {
                    scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                } else {
                    scan.deferred = scan.deferred.saturating_add(1);
                }
                continue;
            }
            Err(_) => {
                scan.deferred = scan.deferred.saturating_add(1);
                continue;
            }
        };
        let exact_transaction_applied = signed_transaction.as_ref().and({
            if let Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Applied {
                block_height,
                block_hash,
                block_timestamp_ms,
            }) = transaction_outcome
            {
                Some((block_height, block_hash, block_timestamp_ms))
            } else {
                None
            }
        });
        if let Some((applied_block_height, applied_block_hash, applied_block_timestamp_ms)) =
            exact_transaction_applied
        {
            let receipt_ready = match &request.operation {
                sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Open(
                    _,
                ) => true,
                _ => {
                    let Some(post_record) = appeal_finance_exact_applied_post_record(
                        &request,
                        applied_block_timestamp_ms,
                    ) else {
                        if submitter
                            .forwarder
                            .mark_invalid_context(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                        continue;
                    };
                    publish_finalized_appeal_finance_receipt(
                        state,
                        submitter,
                        &request,
                        &delivery,
                        applied_block_height,
                        applied_block_hash,
                        &post_record,
                    )
                }
            };
            if !receipt_ready {
                scan.deferred = scan.deferred.saturating_add(1);
                continue;
            }
            let followup_enqueued = if matches!(
                &request.operation,
                sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Drawdown(
                    _
                )
            ) {
                let Some(record) = record.as_ref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                let Some(enqueued) =
                    enqueue_appeal_finance_followup(submitter, &request, finalized_cursor, record)
                else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                enqueued
            } else {
                false
            };
            match submitter
                .forwarder
                .mark_semantic_finalized(delivery.operation_id, finalized_cursor)
            {
                Ok(()) => {
                    scan.finalized = scan.finalized.saturating_add(1);
                    if followup_enqueued {
                        scan.followups_enqueued = scan.followups_enqueued.saturating_add(1);
                    }
                }
                Err(_) => scan.deferred = scan.deferred.saturating_add(1),
            }
            continue;
        }
        match reconciliation {
            AppealFinanceOperationReconciliationV1::Finalized => {
                let Some(record) = record.as_ref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                let Some(followup_enqueued) =
                    enqueue_appeal_finance_followup(submitter, &request, finalized_cursor, record)
                else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                match submitter
                    .forwarder
                    .mark_semantic_finalized(delivery.operation_id, finalized_cursor)
                {
                    Ok(()) => {
                        scan.finalized = scan.finalized.saturating_add(1);
                        if followup_enqueued {
                            scan.followups_enqueued = scan.followups_enqueued.saturating_add(1);
                        }
                    }
                    Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                }
                continue;
            }
            AppealFinanceOperationReconciliationV1::Conflict => {
                match transaction_outcome {
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected) => {
                        match mark_appeal_finance_transaction_rejected(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Some(
                        AppealFinanceAuthoritativeTransactionOutcomeV1::Absent
                        | AppealFinanceAuthoritativeTransactionOutcomeV1::Applied { .. },
                    )
                    | None => {
                        if submitter
                            .forwarder
                            .mark_finalized_conflict(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                    }
                }
                continue;
            }
            AppealFinanceOperationReconciliationV1::Ready => {}
        }
        if matches!(
            transaction_outcome,
            Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected)
        ) {
            match mark_appeal_finance_transaction_rejected(
                submitter,
                delivery.operation_id,
                finalized_cursor,
            ) {
                Some(true) => scan.dead_lettered = scan.dead_lettered.saturating_add(1),
                Some(false) | None => scan.deferred = scan.deferred.saturating_add(1),
            }
            continue;
        }
        if policy_status == AppealFinanceOutboxPolicyStatusV1::Superseded
            && matches!(
                delivery.state,
                AppealFinanceTransactionDeliveryStateV1::Ready
                    | AppealFinanceTransactionDeliveryStateV1::Signing
                    | AppealFinanceTransactionDeliveryStateV1::Signed
            )
        {
            if submitter
                .forwarder
                .mark_policy_superseded(delivery.operation_id, finalized_cursor)
                .is_ok()
            {
                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
            } else {
                scan.deferred = scan.deferred.saturating_add(1);
            }
            continue;
        }
        match delivery.state {
            AppealFinanceTransactionDeliveryStateV1::Ready => {
                let signer = match submitter.signer_for(&request.authority, finalized_cursor.height)
                {
                    Ok(signer) => signer,
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NotYetActive) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NoActiveBinding) => {
                        if submitter
                            .forwarder
                            .mark_signer_binding_inactive(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                        continue;
                    }
                    Err(
                        crate::SoraFsAppealFinanceSignerSelectionError::ProviderMissing
                        | crate::SoraFsAppealFinanceSignerSelectionError::ProviderUnavailable
                        | crate::SoraFsAppealFinanceSignerSelectionError::IdentityMismatch,
                    ) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                };
                let claimed = match submitter
                    .forwarder
                    .claim_for_signing(delivery.operation_id, finalized_cursor)
                {
                    Ok(claimed) => claimed,
                    Err(_) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                };
                let signed_payload =
                    sign_sorafs_appeal_finance_delivery(state, &signer, &claimed).await;
                let Some(bytes) = signed_payload else {
                    match mark_appeal_finance_signing_failed(
                        submitter,
                        delivery.operation_id,
                        finalized_cursor,
                    ) {
                        Some(true) => {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        }
                        Some(false) | None => {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                    }
                    continue;
                };
                if signer.revalidate().is_err()
                    || submitter
                        .forwarder
                        .store_signed_transaction(delivery.operation_id, &bytes)
                        .is_err()
                {
                    match mark_appeal_finance_signing_failed(
                        submitter,
                        delivery.operation_id,
                        finalized_cursor,
                    ) {
                        Some(true) => {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        }
                        Some(false) | None => {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                    }
                    continue;
                }
                scan.signed = scan.signed.saturating_add(1);
                match submit_sorafs_appeal_finance_delivery(
                    state,
                    submitter,
                    delivery.operation_id,
                    &bytes,
                    &request.network_id,
                    finalized_cursor,
                )
                .await
                {
                    AppealFinanceDeliverySubmitOutcomeV1::Submitted => {
                        scan.submitted = scan.submitted.saturating_add(1);
                    }
                    AppealFinanceDeliverySubmitOutcomeV1::Deferred => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    AppealFinanceDeliverySubmitOutcomeV1::DeadLettered => {
                        scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                    }
                }
            }
            AppealFinanceTransactionDeliveryStateV1::Signed => {
                let Some(bytes) = delivery.signed_transaction_bytes.as_deref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                match submitter.active_binding_for(&request.authority, finalized_cursor.height) {
                    Ok(_) => {}
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NotYetActive) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NoActiveBinding) => {
                        if submitter
                            .forwarder
                            .mark_signer_binding_inactive(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                        continue;
                    }
                    Err(
                        crate::SoraFsAppealFinanceSignerSelectionError::ProviderMissing
                        | crate::SoraFsAppealFinanceSignerSelectionError::ProviderUnavailable
                        | crate::SoraFsAppealFinanceSignerSelectionError::IdentityMismatch,
                    ) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                }
                match submit_sorafs_appeal_finance_delivery(
                    state,
                    submitter,
                    delivery.operation_id,
                    bytes,
                    &request.network_id,
                    finalized_cursor,
                )
                .await
                {
                    AppealFinanceDeliverySubmitOutcomeV1::Submitted => {
                        scan.submitted = scan.submitted.saturating_add(1);
                    }
                    AppealFinanceDeliverySubmitOutcomeV1::Deferred => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    AppealFinanceDeliverySubmitOutcomeV1::DeadLettered => {
                        scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                    }
                }
            }
            AppealFinanceTransactionDeliveryStateV1::Ambiguous
            | AppealFinanceTransactionDeliveryStateV1::Submitted => {
                let Some(transaction) = signed_transaction.as_ref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                let hash = transaction.hash();
                let queue_hash = external_hash(hash.clone());
                let local_pending = state.queue.contains_pending_hash(queue_hash, &state.state);
                let cache_kind =
                    crate::pipeline_status_local_entry(state, &hash).map(|(entry, _)| entry.kind);
                match transaction_outcome {
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected) => {
                        match mark_appeal_finance_transaction_rejected(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Some(
                        AppealFinanceAuthoritativeTransactionOutcomeV1::Applied { .. }
                        | AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable,
                    )
                    | None => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Absent)
                        if matches!(
                            cache_kind,
                            Some(
                                crate::PipelineStatusKind::Rejected
                                    | crate::PipelineStatusKind::Expired
                            )
                        ) =>
                    {
                        match mark_appeal_finance_transaction_rejected(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Absent)
                        if local_pending
                            || matches!(
                                cache_kind,
                                Some(
                                    crate::PipelineStatusKind::Queued
                                        | crate::PipelineStatusKind::Approved
                                        | crate::PipelineStatusKind::Committed
                                        | crate::PipelineStatusKind::Applied
                                )
                            ) =>
                    {
                        if delivery.state == AppealFinanceTransactionDeliveryStateV1::Ambiguous {
                            let _ = submitter.forwarder.mark_submitted(delivery.operation_id);
                        }
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Absent)
                        if finalized_cursor.height > delivery.baseline_finalized_height =>
                    {
                        match mark_appeal_finance_finalized_absent(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Absent) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                }
            }
            AppealFinanceTransactionDeliveryStateV1::Signing => {
                match submitter.active_binding_for(&request.authority, finalized_cursor.height) {
                    Ok(_) => {
                        match mark_appeal_finance_signing_failed(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NotYetActive) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NoActiveBinding) => {
                        if submitter
                            .forwarder
                            .mark_signer_binding_inactive(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                    }
                    Err(
                        crate::SoraFsAppealFinanceSignerSelectionError::ProviderMissing
                        | crate::SoraFsAppealFinanceSignerSelectionError::ProviderUnavailable
                        | crate::SoraFsAppealFinanceSignerSelectionError::IdentityMismatch,
                    ) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                }
            }
        }
    }
    scan
}
fn appeal_finance_operation_is_terminal(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
) -> Option<bool> {
    use sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionForwarderError;
    match submitter
        .forwarder
        .operation_for_reconciliation(operation_id)
    {
        Ok(_) => Some(false),
        Err(AppealFinanceTransactionForwarderError::UnknownOperation) => Some(true),
        Err(_) => None,
    }
}
fn mark_appeal_finance_transaction_rejected(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> Option<bool> {
    submitter
        .forwarder
        .mark_transaction_rejected(operation_id, finalized_cursor)
        .ok()?;
    appeal_finance_operation_is_terminal(submitter, operation_id)
}
fn mark_appeal_finance_signing_failed(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> Option<bool> {
    submitter
        .forwarder
        .mark_signing_failed(operation_id, finalized_cursor)
        .ok()?;
    appeal_finance_operation_is_terminal(submitter, operation_id)
}
fn mark_appeal_finance_finalized_absent(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> Option<bool> {
    submitter
        .forwarder
        .mark_finalized_absent(operation_id, finalized_cursor)
        .ok()?;
    appeal_finance_operation_is_terminal(submitter, operation_id)
}
fn mark_appeal_finance_retryable_submission_failed(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> AppealFinanceDeliverySubmitOutcomeV1 {
    if submitter
        .forwarder
        .mark_retryable_submission_failed(operation_id, finalized_cursor)
        .is_err()
    {
        return AppealFinanceDeliverySubmitOutcomeV1::Deferred;
    }
    if appeal_finance_operation_is_terminal(submitter, operation_id) == Some(true) {
        AppealFinanceDeliverySubmitOutcomeV1::DeadLettered
    } else {
        AppealFinanceDeliverySubmitOutcomeV1::Deferred
    }
}
fn appeal_finance_exact_applied_post_record(
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
    applied_block_timestamp_ms: u64,
) -> Option<AssetEscrowRecord> {
    use sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1;
    let mut record = request.expected_record.clone()?;
    match &request.operation {
        AppealFinanceOperationV1::Open(_) => return None,
        AppealFinanceOperationV1::Drawdown(instruction) => {
            if record.id != *instruction.escrow_id()
                || record.remaining_amount != *instruction.expected_remaining_amount()
            {
                return None;
            }
            record.remaining_amount = record
                .remaining_amount
                .checked_sub(instruction.amount())
                .ok()?;
            if record.remaining_amount.is_zero() {
                record.status = AssetEscrowStatus::DrawnDown;
                record.closed_at_ms = Some(applied_block_timestamp_ms);
            }
        }
        AppealFinanceOperationV1::Cancel(instruction) => {
            if record.id != *instruction.escrow_id() {
                return None;
            }
            if record.remaining_amount != *instruction.expected_remaining_amount() {
                return None;
            }
            record.status = AssetEscrowStatus::Cancelled;
            record.remaining_amount = Quantity::zero();
            record.closed_at_ms = Some(applied_block_timestamp_ms);
        }
    }
    Some(record)
}
async fn sign_sorafs_appeal_finance_delivery(
    state: &SharedAppState,
    signer: &crate::SoraFsAppealFinanceQualifiedSignerV1,
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
) -> Option<Vec<u8>> {
    if AccountId::new(signer.public_key().clone()) != request.authority
        || request.network_id != *state.state.network_id_ref()
        || request.chain_id != *state.chain_id
    {
        return None;
    }
    let mut builder = TransactionBuilder::new(
        request.network_id,
        request.authority.clone(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    )
    .with_instructions([InstructionBox::from(request.operation.clone())]);
    builder.set_ttl(Duration::from_secs(300));
    let mut payload = builder.into_payload().ok()?;
    payload.fee_payment = crate::quote_internal_fee_payment(state, &payload).ok()?;
    let expected_payload = payload.clone();
    let signer = signer.clone();
    let transaction = crate::panic_recovery::join_recoverable(
        crate::panic_recovery::spawn_blocking_recoverable(move || signer.sign(payload)),
    )
    .await
    .ok()?
    .ok()?;
    if transaction.payload() != &expected_payload
        || transaction.authority() != &request.authority
        || transaction.verify_signature().is_err()
    {
        return None;
    }
    norito::to_bytes(&transaction).ok()
}
fn decode_appeal_finance_signed_transaction(
    bytes: &[u8],
    expected_network_id: &NetworkId,
) -> Option<SignedTransaction> {
    let max_bytes = sorafs_node::appeal_finance_transaction_forwarder::
        APPEAL_FINANCE_TRANSACTION_MAX_CANONICAL_BYTES_V1;
    if bytes.is_empty() || bytes.len() > max_bytes {
        return None;
    }
    norito::core::from_bytes_view(bytes).ok()?;
    let limits = norito::DecodeLimits::new(
        max_bytes,
        max_bytes,
        bytes.len().checked_mul(8)?,
        bytes.len().checked_mul(20)?.checked_add(512 * 1024)?,
        128,
    );
    let transaction =
        norito::decode_from_bytes_with_limits::<SignedTransaction>(bytes, limits).ok()?;
    (transaction.network_id() == Some(expected_network_id)
        && transaction.verify_signature().is_ok()
        && norito::to_bytes(&transaction).ok().as_deref() == Some(bytes))
    .then_some(transaction)
}
async fn submit_sorafs_appeal_finance_delivery(
    state: &SharedAppState,
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    transaction_bytes: &[u8],
    expected_network_id: &NetworkId,
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> AppealFinanceDeliverySubmitOutcomeV1 {
    if expected_network_id != state.state.network_id_ref() {
        return AppealFinanceDeliverySubmitOutcomeV1::Deferred;
    }
    let Some(transaction) =
        decode_appeal_finance_signed_transaction(transaction_bytes, expected_network_id)
    else {
        return AppealFinanceDeliverySubmitOutcomeV1::Deferred;
    };
    let accepted = match crate::routing::accept_transaction_for_ingress(
        state.state.clone(),
        transaction.clone(),
        &state.telemetry,
    ) {
        Ok(accepted) => accepted,
        Err(_) => {
            return match mark_appeal_finance_transaction_rejected(
                submitter,
                operation_id,
                finalized_cursor,
            ) {
                Some(true) => AppealFinanceDeliverySubmitOutcomeV1::DeadLettered,
                Some(false) | None => AppealFinanceDeliverySubmitOutcomeV1::Deferred,
            };
        }
    };
    let routing_plan = match state
        .queue
        .route_plan_with_state(&accepted, state.state.as_ref())
    {
        Ok(plan) => plan,
        Err(_) => {
            return mark_appeal_finance_retryable_submission_failed(
                submitter,
                operation_id,
                finalized_cursor,
            );
        }
    };
    let routing_decision = routing_plan.coordinator_route();
    let exact_bytes = match submitter.forwarder.begin_submission(operation_id) {
        Ok(bytes) => bytes,
        Err(_) => return AppealFinanceDeliverySubmitOutcomeV1::Deferred,
    };
    if exact_bytes != transaction_bytes {
        let _ = submitter.forwarder.mark_not_submitted(operation_id);
        return AppealFinanceDeliverySubmitOutcomeV1::Deferred;
    }
    let disposition = if crate::should_execute_route_locally(state.as_ref(), routing_decision) {
        match crate::routing::push_accepted_transaction_for_ingress_with_routing_plan(
            state.queue.clone(),
            state.state.clone(),
            accepted,
            Some(routing_plan),
        ) {
            Ok(_) => AppealFinanceSubmissionDispositionV1::Submitted,
            Err(crate::Error::PushIntoQueue { source, .. }) => {
                classify_local_appeal_finance_submission(source.as_ref())
            }
            Err(_) => AppealFinanceSubmissionDispositionV1::Ambiguous,
        }
    } else {
        let response = crate::execute_torii_transaction_via_proxy(
            state,
            accepted,
            routing_plan,
            true,
            crate::utils::ResponseFormat::Norito,
        )
        .await;
        if response.status() == StatusCode::ACCEPTED {
            AppealFinanceSubmissionDispositionV1::Submitted
        } else {
            AppealFinanceSubmissionDispositionV1::Ambiguous
        }
    };
    match disposition {
        AppealFinanceSubmissionDispositionV1::Submitted => {
            if submitter.forwarder.mark_submitted(operation_id).is_ok() {
                AppealFinanceDeliverySubmitOutcomeV1::Submitted
            } else {
                AppealFinanceDeliverySubmitOutcomeV1::Deferred
            }
        }
        AppealFinanceSubmissionDispositionV1::DefinitelyNotSubmitted => {
            mark_appeal_finance_retryable_submission_failed(
                submitter,
                operation_id,
                finalized_cursor,
            )
        }
        AppealFinanceSubmissionDispositionV1::Rejected => {
            match mark_appeal_finance_transaction_rejected(
                submitter,
                operation_id,
                finalized_cursor,
            ) {
                Some(true) => AppealFinanceDeliverySubmitOutcomeV1::DeadLettered,
                Some(false) | None => AppealFinanceDeliverySubmitOutcomeV1::Deferred,
            }
        }
        AppealFinanceSubmissionDispositionV1::Ambiguous => {
            AppealFinanceDeliverySubmitOutcomeV1::Deferred
        }
    }
}
fn decode_appeal_finance_outbox_context(
    bytes: &[u8],
) -> Option<AppealFinanceSettlementOutboxContextV1> {
    let max_bytes = sorafs_node::appeal_finance_transaction_forwarder::
        APPEAL_FINANCE_RECONCILIATION_CONTEXT_MAX_BYTES_V1;
    if bytes.is_empty() || bytes.len() > max_bytes {
        return None;
    }
    norito::core::from_bytes_view(bytes).ok()?;
    let limits = norito::DecodeLimits::new(
        max_bytes,
        max_bytes,
        bytes.len().checked_mul(8)?,
        bytes.len().checked_mul(20)?.checked_add(256 * 1024)?,
        64,
    );
    let context = norito::decode_from_bytes_with_limits::<AppealFinanceSettlementOutboxContextV1>(
        bytes, limits,
    )
    .ok()?;
    if context.version != APPEAL_FINANCE_SETTLEMENT_OUTBOX_CONTEXT_VERSION_V1
        || context.policy_digest == [0; 32]
        || context.panel_size == 0
        || !appeal_finance_deposit_expectation_is_canonical(&context.expected)
        || context.settlement.asset_scale
            != iroha_config::parameters::defaults::torii::sorafs_appeal_finance::ASSET_SCALE
        || !is_canonical_appeal_finance_policy_version(&context.settlement.config_version)
        || appeal_verdict_from_request(&context.outcome)
            .ok()
            .map(|verdict| verdict.to_string())
            .as_deref()
            != Some(context.outcome.as_str())
        || norito::to_bytes(&context).ok().as_deref() != Some(bytes)
    {
        return None;
    }
    let deposit = XorQuantity::try_from_quantity(context.expected.deposit_xor.clone()).ok()?;
    let refund = XorQuantity::try_from_quantity(context.settlement.refund_xor.clone()).ok()?;
    let treasury = XorQuantity::try_from_quantity(context.settlement.treasury_xor.clone()).ok()?;
    let held = XorQuantity::try_from_quantity(context.settlement.held_xor.clone()).ok()?;
    let panel_reward_per_juror =
        XorQuantity::try_from_quantity(context.settlement.panel_reward_per_juror_xor.clone())
            .ok()?;
    let panel_reward_total =
        XorQuantity::try_from_quantity(context.settlement.panel_reward_total_xor.clone()).ok()?;
    let accounted = refund
        .checked_add(&treasury)
        .ok()?
        .checked_add(&held)
        .ok()?;
    let minimum_panel_reward = panel_reward_per_juror
        .checked_mul_u64(u64::from(context.panel_size))
        .ok()?;
    (!deposit.is_zero() && accounted == deposit && panel_reward_total >= minimum_panel_reward)
        .then_some(context)
}
fn decode_appeal_finance_deposit_outbox_context(
    bytes: &[u8],
) -> Option<AppealFinanceDepositOutboxContextV1> {
    let max_bytes = sorafs_node::appeal_finance_transaction_forwarder::
        APPEAL_FINANCE_RECONCILIATION_CONTEXT_MAX_BYTES_V1;
    if bytes.is_empty() || bytes.len() > max_bytes {
        return None;
    }
    norito::core::from_bytes_view(bytes).ok()?;
    let limits = norito::DecodeLimits::new(
        max_bytes,
        max_bytes,
        bytes.len().checked_mul(8)?,
        bytes.len().checked_mul(20)?.checked_add(256 * 1024)?,
        64,
    );
    let context =
        norito::decode_from_bytes_with_limits::<AppealFinanceDepositOutboxContextV1>(bytes, limits)
            .ok()?;
    (context.version == APPEAL_FINANCE_DEPOSIT_OUTBOX_CONTEXT_VERSION_V1
        && context.policy_digest != [0; 32]
        && appeal_finance_deposit_expectation_is_canonical(&context.expected)
        && norito::to_bytes(&context).ok().as_deref() == Some(bytes))
    .then_some(context)
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AppealFinanceOutboxPolicyStatusV1 {
    Active,
    Grandfathered,
    Superseded,
    InvalidContext,
}
fn appeal_finance_outbox_policy_status(
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
    policy: &AppealFinanceRuntimePolicy,
) -> AppealFinanceOutboxPolicyStatusV1 {
    use sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1;
    let (policy_digest, expected, grandfathered_continuation) = match &request.operation {
        AppealFinanceOperationV1::Open(instruction) => {
            let Some(context) =
                decode_appeal_finance_deposit_outbox_context(&request.reconciliation_context)
            else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            if request.authority != context.expected.payer_account
                || instruction.asset_definition() != &context.expected.asset_definition_id
                || instruction.destination() != &context.expected.destination_account
                || instruction.amount() != &context.expected.deposit_xor
                || instruction.release_authority().as_ref()
                    != context.expected.release_authority_account.as_ref()
                || *instruction.expires_at_ms() != context.expected.expires_at_ms
                || instruction.evidence_hashes().as_slice()
                    != context.expected.evidence_hashes.as_slice()
            {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            }
            (context.policy_digest, context.expected, false)
        }
        AppealFinanceOperationV1::Drawdown(instruction) => {
            let Some(context) =
                decode_appeal_finance_outbox_context(&request.reconciliation_context)
            else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            let Some(record) = request.expected_record.as_ref() else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            let Ok(drawdown_xor) = context
                .settlement
                .treasury_xor
                .checked_add(&context.settlement.held_xor)
            else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            let required_authority = context
                .expected
                .release_authority_account
                .as_ref()
                .unwrap_or(&context.expected.destination_account);
            if drawdown_xor.is_zero()
                || instruction.amount() != &drawdown_xor
                || instruction.expected_remaining_amount() != &record.remaining_amount
                || record.remaining_amount != context.expected.deposit_xor
                || &request.authority != required_authority
                || !appeal_finance_locked_record_matches_expectation(&context.expected, record)
            {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            }
            (context.policy_digest, context.expected, false)
        }
        AppealFinanceOperationV1::Cancel(instruction) => {
            let Some(context) =
                decode_appeal_finance_outbox_context(&request.reconciliation_context)
            else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            let Some(record) = request.expected_record.as_ref() else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            if context.settlement.refund_xor.is_zero()
                || request.authority != context.expected.payer_account
                || record.remaining_amount != context.settlement.refund_xor
                || record.id != *instruction.escrow_id()
                || record.remaining_amount != *instruction.expected_remaining_amount()
                || !appeal_finance_locked_record_matches_expectation(&context.expected, record)
            {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            }
            (context.policy_digest, context.expected, true)
        }
    };
    if expected.escrow_id != *request.operation.escrow_id()
        || XorQuantity::try_from_quantity(expected.deposit_xor).is_err()
    {
        return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
    }
    if policy_digest == policy.policy_digest {
        if expected.asset_definition_id == policy.asset_definition_id {
            AppealFinanceOutboxPolicyStatusV1::Active
        } else {
            AppealFinanceOutboxPolicyStatusV1::InvalidContext
        }
    } else if grandfathered_continuation {
        AppealFinanceOutboxPolicyStatusV1::Grandfathered
    } else {
        AppealFinanceOutboxPolicyStatusV1::Superseded
    }
}
fn appeal_finance_locked_record_matches_expectation(
    expected: &AppealFinanceDepositExpectation,
    record: &AssetEscrowRecord,
) -> bool {
    record.kind == AssetEscrowKind::Lock
        && record.status == AssetEscrowStatus::Locked
        && !record.remaining_amount.is_zero()
        && record.accepted_at_ms.is_none()
        && record.payment_sent_at_ms.is_none()
        && record.disputed_at_ms.is_none()
        && record.closed_at_ms.is_none()
        && record.resolution.is_none()
        && appeal_finance_deposit_static_mismatches(expected, record).is_empty()
}
fn appeal_finance_step_for_operation<'a>(
    operation: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1,
    execution: &'a AppealFinanceDepositSettlementExecution,
) -> Option<&'a AppealFinanceSettlementStep> {
    match operation {
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Open(_) => {
            None
        }
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Drawdown(
            _,
        ) => execution
            .steps
            .iter()
            .find(|step| step.action == "drawdown_non_refund"),
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Cancel(_) => {
            execution
                .steps
                .iter()
                .find(|step| step.action == "cancel_refund")
        }
    }
}
fn publish_finalized_appeal_finance_receipt(
    state: &SharedAppState,
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
    delivery: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionPendingV1,
    finalized_block_height: u64,
    finalized_block_hash: [u8; 32],
    record: &AssetEscrowRecord,
) -> bool {
    if !state.sorafs_node.has_governance_publisher() {
        return false;
    }
    let Some(context) = decode_appeal_finance_outbox_context(&request.reconciliation_context)
    else {
        return false;
    };
    if context.expected.escrow_id != *request.operation.escrow_id() {
        return false;
    }
    let Ok(verdict) = appeal_verdict_from_request(&context.outcome) else {
        return false;
    };
    let breakdown = context.settlement.breakdown();
    let Ok(reconciliation) = appeal_finance_deposit_settlement_reconciliation_with_policy_binding(
        &context.expected,
        record,
        context.policy_digest,
        &context.settlement.config_version,
        context.settlement.asset_scale,
        verdict,
        context.panel_size,
        &breakdown,
    ) else {
        return false;
    };
    let Ok(execution) =
        appeal_finance_deposit_settlement_execution(&context.expected, record, &breakdown)
    else {
        return false;
    };
    let Some(step) = appeal_finance_step_for_operation(&request.operation, &execution) else {
        return false;
    };
    let Some(transaction) = delivery
        .signed_transaction_bytes
        .as_deref()
        .and_then(|bytes| decode_appeal_finance_signed_transaction(bytes, &request.network_id))
    else {
        return false;
    };
    let tx_hash_hex = hex::encode(transaction.hash().as_ref());
    let generated_at_unix_ms =
        u64::try_from(transaction.creation_time().as_millis()).unwrap_or(u64::MAX);
    if generated_at_unix_ms == 0 {
        return false;
    }
    let Ok(receipt) = appeal_finance_deposit_settlement_receipt(
        context.policy_digest,
        &context.settlement.config_version,
        &context.expected,
        record,
        verdict,
        context.panel_size,
        &breakdown,
        &reconciliation,
        step,
        &tx_hash_hex,
        finalized_block_height,
        finalized_block_hash,
        submitter.signer_count(request.baseline_finalized_cursor.height),
        generated_at_unix_ms,
    ) else {
        return false;
    };
    state
        .sorafs_node
        .publish_appeal_finance_settlement_receipt(receipt)
        .is_ok()
}
fn enqueue_appeal_finance_followup(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
    record: &AssetEscrowRecord,
) -> Option<bool> {
    use sorafs_node::appeal_finance_transaction_forwarder::{
        AppealFinanceOperationV1, AppealFinanceTransactionContextV1,
    };
    if !matches!(request.operation, AppealFinanceOperationV1::Drawdown(_)) {
        return Some(false);
    }
    let context = decode_appeal_finance_outbox_context(&request.reconciliation_context)?;
    let Ok(verdict) = appeal_verdict_from_request(&context.outcome) else {
        return None;
    };
    let breakdown = context.settlement.breakdown();
    let Ok(reconciliation) = appeal_finance_deposit_settlement_reconciliation_with_policy_binding(
        &context.expected,
        record,
        context.policy_digest,
        &context.settlement.config_version,
        context.settlement.asset_scale,
        verdict,
        context.panel_size,
        &breakdown,
    ) else {
        return None;
    };
    let Ok(execution) =
        appeal_finance_deposit_settlement_execution(&context.expected, record, &breakdown)
    else {
        return None;
    };
    let Some(step) =
        appeal_finance_deposit_next_settlement_submission_step(&reconciliation, &execution)
    else {
        return Some(false);
    };
    if step.action != "cancel_refund" {
        return None;
    }
    submitter
        .forwarder
        .enqueue_unsigned_operation(
            step.required_authority.clone(),
            AppealFinanceOperationV1::Cancel(CancelAssetLock::new(
                context.expected.escrow_id,
                record.remaining_amount.clone(),
            )),
            &AppealFinanceTransactionContextV1 {
                network_id: request.network_id,
                chain_id: request.chain_id.clone(),
                finalized_cursor,
                expected_record: Some(record.clone()),
                reconciliation_context: request.reconciliation_context.clone(),
            },
        )
        .ok()
        .map(|_| true)
}
const SORAFS_PROOF_OUTCOME_FORWARDER_SCAN_LIMIT_V1: usize = 256;
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsProofOutcomeForwarderScanV1 {
    scanned: usize,
    finalized: usize,
    signed: usize,
    submitted: usize,
    deferred: usize,
    unauthorized_signer: usize,
    dead_lettered: usize,
}
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsProofOutcomeForwarderCursorV1 {
    after_sequence: Option<u64>,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ProofOutcomeSubmissionDispositionV1 {
    Submitted,
    DefinitelyNotSubmitted,
    Rejected,
    Ambiguous,
}
fn classify_local_proof_outcome_submission(
    error: &iroha_core::queue::Error,
) -> ProofOutcomeSubmissionDispositionV1 {
    match error {
        iroha_core::queue::Error::InBlockchain | iroha_core::queue::Error::IsInQueue => {
            ProofOutcomeSubmissionDispositionV1::Submitted
        }
        iroha_core::queue::Error::Expired
        | iroha_core::queue::Error::TransactionDomainMismatch(_) => {
            ProofOutcomeSubmissionDispositionV1::Rejected
        }
        _ => ProofOutcomeSubmissionDispositionV1::DefinitelyNotSubmitted,
    }
}
#[cfg(test)]
mod proof_outcome_submission_disposition_tests {
    use super::*;
    #[test]
    fn local_queue_dispositions_preserve_admission_boundaries() {
        assert_eq!(
            classify_local_proof_outcome_submission(&iroha_core::queue::Error::Full),
            ProofOutcomeSubmissionDispositionV1::DefinitelyNotSubmitted
        );
        assert_eq!(
            classify_local_proof_outcome_submission(
                &iroha_core::queue::Error::AdmissionInvariant {
                    reason: "unavailable".to_owned(),
                }
            ),
            ProofOutcomeSubmissionDispositionV1::DefinitelyNotSubmitted
        );
        assert_eq!(
            classify_local_proof_outcome_submission(
                &iroha_core::queue::Error::AdmissionInvariant {
                    reason: "admission index unavailable".to_owned()
                }
            ),
            ProofOutcomeSubmissionDispositionV1::DefinitelyNotSubmitted
        );
        assert_eq!(
            classify_local_proof_outcome_submission(&iroha_core::queue::Error::IsInQueue),
            ProofOutcomeSubmissionDispositionV1::Submitted
        );
        assert_eq!(
            classify_local_proof_outcome_submission(&iroha_core::queue::Error::Expired),
            ProofOutcomeSubmissionDispositionV1::Rejected
        );
    }
}
fn proof_outcome_authority_has_provider_permission(
    world: &impl WorldReadOnly,
    authority: &AccountId,
    provider_id: ProviderId,
) -> bool {
    let required = Permission::from(CanRecordSorafsProofOutcome { provider_id });
    crate::torii_account_has_permission(world, authority, &required)
}
pub(crate) fn spawn_sorafs_proof_outcome_forwarder_worker(
    state: SharedAppState,
    shutdown_signal: ShutdownSignal,
) -> Option<tokio::task::JoinHandle<crate::ToriiCriticalWorkerExit>> {
    if !state.sorafs_node.is_enabled() {
        debug!("SoraFS proof-outcome forwarder disabled: SoraFS storage is disabled");
        return None;
    }
    if state.sorafs_proof_outcome_signer.is_none() {
        warn!(
            "SoraFS proof-outcome forwarder has no runtime signer; finalized reconciliation remains active"
        );
    }
    let worker_interval = state
        .sorafs_node
        .config()
        .runtime_retention()
        .proof_outcome_forwarder_interval();
    Some(tokio::spawn(async move {
        let mut interval = tokio::time::interval(worker_interval);
        let mut cursor = SorafsProofOutcomeForwarderCursorV1::default();
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
        loop {
            tokio::select! {
                biased;
                () = shutdown_signal.receive() => {
                    return crate::ToriiCriticalWorkerExit::StoppedByShutdown;
                }
                _ = interval.tick() => {
                    if shutdown_signal.is_sent() {
                        return crate::ToriiCriticalWorkerExit::StoppedByShutdown;
                    }
                    let scan = run_sorafs_proof_outcome_forwarder_scan(&state, &mut cursor).await;
                    if scan.scanned != 0 {
                        debug!(
                            scanned = scan.scanned,
                            finalized = scan.finalized,
                            signed = scan.signed,
                            submitted = scan.submitted,
                            deferred = scan.deferred,
                            unauthorized_signer = scan.unauthorized_signer,
                            dead_lettered = scan.dead_lettered,
                            "processed durable SoraFS proof-outcome deliveries"
                        );
                    }
                }
            }
        }
    }))
}
pub(crate) async fn run_sorafs_proof_outcome_forwarder_scan(
    state: &SharedAppState,
    cursor: &mut SorafsProofOutcomeForwarderCursorV1,
) -> SorafsProofOutcomeForwarderScanV1 {
    let mut scan = SorafsProofOutcomeForwarderScanV1::default();
    let pending = match state.sorafs_node.pending_proof_outcome_deliveries_after(
        cursor.after_sequence,
        SORAFS_PROOF_OUTCOME_FORWARDER_SCAN_LIMIT_V1,
    ) {
        Ok(pending) => pending,
        Err(_) => {
            warn!("failed to load durable SoraFS proof-outcome deliveries");
            return scan;
        }
    };
    for delivery in pending {
        cursor.after_sequence = Some(delivery.sequence);
        scan.scanned = scan.scanned.saturating_add(1);
        let reconciliation = {
            let view = state.state.query_view();
            u64::try_from(view.block_hashes.len())
                .ok()
                .zip(view.block_hashes.last())
                .map(|(height, hash)| ProofOutcomeFinalizedCursorV1 {
                    height,
                    block_hash: *hash.as_ref(),
                })
                .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
                .map(|cursor| {
                    let finalized =
                        FindSorafsProofOutcome::new(delivery.kind, delivery.identity_digest, None)
                            .execute(&view);
                    (cursor, finalized)
                })
        };
        let Some((finalized_cursor, finalized)) = reconciliation else {
            scan.deferred = scan.deferred.saturating_add(1);
            continue;
        };
        match finalized {
            Ok(finalized) => {
                match state
                    .sorafs_node
                    .mark_proof_outcome_finalized(delivery.operation_id, &finalized)
                {
                    Ok(()) => scan.finalized = scan.finalized.saturating_add(1),
                    Err(sorafs_node::ProofOutcomeOutboxError::FinalizedConflict) => {
                        scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        warn!(
                            proof_kind = ?delivery.kind,
                            "finalized SoraFS proof outcome conflicts with the durable delivery"
                        );
                    }
                    Err(_) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        warn!("failed to checkpoint finalized SoraFS proof outcome");
                    }
                }
                continue;
            }
            Err(QueryExecutionFail::Find(FindError::SorafsProofOutcome(_))) => {}
            Err(_) => {
                scan.deferred = scan.deferred.saturating_add(1);
                warn!("authoritative SoraFS proof-outcome reconciliation query failed");
                continue;
            }
        }
        match delivery.state {
            sorafs_node::ProofOutcomeDeliveryStateV1::Ready => {
                let Some(signer) = state.sorafs_proof_outcome_signer.clone() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                let signer_is_authorized = {
                    let view = state.state.query_view();
                    proof_outcome_authority_has_provider_permission(
                        view.world(),
                        &signer.authority(),
                        delivery.provider_id,
                    )
                };
                if !signer_is_authorized {
                    scan.deferred = scan.deferred.saturating_add(1);
                    scan.unauthorized_signer = scan.unauthorized_signer.saturating_add(1);
                    warn!(
                        proof_kind = ?delivery.kind,
                        "SoraFS proof-outcome runtime signer lacks the finalized provider-scoped permission"
                    );
                    continue;
                }
                let claimed = match state
                    .sorafs_node
                    .claim_proof_outcome_for_signing(delivery.operation_id, finalized_cursor)
                {
                    Ok(claimed) => claimed,
                    Err(_) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                };
                let Some(transaction) =
                    sign_sorafs_proof_outcome_delivery(state, signer, &claimed).await
                else {
                    let _ = state
                        .sorafs_node
                        .release_proof_outcome_signing_claim(delivery.operation_id);
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                match state.sorafs_node.store_signed_proof_outcome_transaction(
                    delivery.operation_id,
                    transaction.clone(),
                ) {
                    Ok(_) => scan.signed = scan.signed.saturating_add(1),
                    Err(_) => {
                        let _ = state
                            .sorafs_node
                            .release_proof_outcome_signing_claim(delivery.operation_id);
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                }
                if submit_sorafs_proof_outcome_delivery(state, delivery.operation_id, transaction)
                    .await
                {
                    scan.submitted = scan.submitted.saturating_add(1);
                } else {
                    scan.deferred = scan.deferred.saturating_add(1);
                }
            }
            sorafs_node::ProofOutcomeDeliveryStateV1::Signed => {
                let Some(transaction) = delivery.signed_transaction else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                if submit_sorafs_proof_outcome_delivery(state, delivery.operation_id, transaction)
                    .await
                {
                    scan.submitted = scan.submitted.saturating_add(1);
                } else {
                    scan.deferred = scan.deferred.saturating_add(1);
                }
            }
            sorafs_node::ProofOutcomeDeliveryStateV1::Ambiguous
            | sorafs_node::ProofOutcomeDeliveryStateV1::Submitted => {
                let Some(transaction) = delivery.signed_transaction.as_ref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                match crate::pipeline_status_local_entry(state, &transaction.hash()) {
                    Some((entry, _))
                        if matches!(
                            entry.kind,
                            crate::PipelineStatusKind::Rejected
                                | crate::PipelineStatusKind::Expired
                        ) =>
                    {
                        match state.sorafs_node.mark_proof_outcome_transaction_rejected(
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Ok(()) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                        }
                    }
                    Some((_entry, _)) => {
                        if delivery.state == sorafs_node::ProofOutcomeDeliveryStateV1::Ambiguous {
                            let _ = state
                                .sorafs_node
                                .mark_proof_outcome_submitted(delivery.operation_id);
                        }
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    None if finalized_cursor.height > delivery.baseline_finalized_height => {
                        match state.sorafs_node.mark_proof_outcome_finalized_absent(
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Ok(()) => scan.deferred = scan.deferred.saturating_add(1),
                            Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                        }
                    }
                    None => scan.deferred = scan.deferred.saturating_add(1),
                }
            }
            sorafs_node::ProofOutcomeDeliveryStateV1::Signing => {
                scan.deferred = scan.deferred.saturating_add(1);
            }
        }
    }
    scan
}
async fn sign_sorafs_proof_outcome_delivery(
    state: &SharedAppState,
    signer: Arc<dyn crate::SoraFsProofOutcomeTransactionSigner>,
    delivery: &sorafs_node::ProofOutcomePendingDeliveryV1,
) -> Option<SignedTransaction> {
    let expected_authority = signer.authority();
    let mut builder = TransactionBuilder::new(
        *state.state.network_id_ref(),
        expected_authority.clone(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    )
    .with_instructions([InstructionBox::from(SubmitSorafsProofOutcome::new(
        delivery.submission.clone(),
    ))]);
    builder.set_ttl(Duration::from_secs(300));
    let mut payload = builder.into_payload().ok()?;
    payload.fee_payment = crate::quote_internal_fee_payment(state, &payload).ok()?;
    let expected_payload = payload.clone();
    let transaction = crate::panic_recovery::join_recoverable(
        crate::panic_recovery::spawn_blocking_recoverable(move || signer.sign(payload)),
    )
    .await
    .ok()?
    .ok()?;
    native_signer_returned_exact_transaction(&transaction, &expected_payload, &expected_authority)
        .then_some(transaction)
}
fn native_signer_returned_exact_transaction(
    transaction: &SignedTransaction,
    expected_payload: &TransactionPayload,
    expected_authority: &AccountId,
) -> bool {
    transaction.payload() == expected_payload
        && transaction.authority() == expected_authority
        && transaction.verify_signature().is_ok()
}
#[cfg(test)]
mod native_signer_returned_transaction_tests {
    use super::*;
    use iroha_crypto::{Algorithm, KeyPair, Signature};
    fn fixture_payload(authority: AccountId) -> TransactionPayload {
        TransactionBuilder::new(
            crate::signed_query_test_network_id(),
            authority,
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .into_payload()
        .expect("build native signer validation payload")
    }
    #[test]
    fn exact_native_signer_output_requires_payload_authority_and_valid_signature() {
        let signer = KeyPair::try_from_seed(vec![0x91; 32], Algorithm::Ed25519)
            .expect("derive native signer validation key");
        let authority = AccountId::new(signer.public_key().clone());
        let payload = fixture_payload(authority.clone());
        let valid = TransactionBuilder::from_payload(payload.clone())
            .and_then(|builder| builder.try_sign(signer.private_key()))
            .expect("sign exact native transaction");
        assert!(native_signer_returned_exact_transaction(
            &valid, &payload, &authority
        ));
        let other = KeyPair::try_from_seed(vec![0x92; 32], Algorithm::Ed25519)
            .expect("derive substituted native signer key");
        let forged_builder =
            TransactionBuilder::from_payload(payload.clone()).expect("rebuild payload");
        let forged_signature =
            Signature::try_new(other.private_key(), &forged_builder.payload_hash_bytes())
                .expect("sign payload hash with substituted key");
        let forged = forged_builder.build_with_signature(forged_signature);
        assert!(forged.verify_signature().is_err());
        assert!(!native_signer_returned_exact_transaction(
            &forged, &payload, &authority
        ));
        assert!(!native_signer_returned_exact_transaction(
            &valid,
            &payload,
            &AccountId::new(other.public_key().clone())
        ));
        let mut substituted_payload = payload.clone();
        substituted_payload.creation_time_ms = substituted_payload
            .creation_time_ms
            .checked_add(1)
            .expect("fixture timestamp has headroom");
        assert!(!native_signer_returned_exact_transaction(
            &valid,
            &substituted_payload,
            &authority
        ));
    }
}
async fn submit_sorafs_proof_outcome_delivery(
    state: &SharedAppState,
    operation_id: [u8; 32],
    transaction: SignedTransaction,
) -> bool {
    let accepted = match crate::routing::accept_transaction_for_ingress(
        state.state.clone(),
        transaction.clone(),
        &state.telemetry,
    ) {
        Ok(accepted) => accepted,
        Err(_) => {
            let finalized_cursor = {
                let view = state.state.query_view();
                u64::try_from(view.block_hashes.len())
                    .ok()
                    .zip(view.block_hashes.last())
                    .map(|(height, hash)| ProofOutcomeFinalizedCursorV1 {
                        height,
                        block_hash: *hash.as_ref(),
                    })
                    .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
            };
            if let Some(finalized_cursor) = finalized_cursor {
                let _ = state
                    .sorafs_node
                    .mark_proof_outcome_transaction_rejected(operation_id, finalized_cursor);
            }
            return false;
        }
    };
    let routing_plan = match state
        .queue
        .route_plan_with_state(&accepted, state.state.as_ref())
    {
        Ok(plan) => plan,
        Err(_) => return false,
    };
    let routing_decision = routing_plan.coordinator_route();
    let exact_transaction = match state
        .sorafs_node
        .begin_proof_outcome_submission(operation_id)
    {
        Ok(transaction) => transaction,
        Err(_) => return false,
    };
    if exact_transaction.hash() != transaction.hash() {
        let _ = state
            .sorafs_node
            .mark_proof_outcome_not_submitted(operation_id);
        return false;
    }
    let disposition = if crate::should_execute_route_locally(state.as_ref(), routing_decision) {
        match crate::routing::push_accepted_transaction_for_ingress_with_routing_plan(
            state.queue.clone(),
            state.state.clone(),
            accepted,
            Some(routing_plan),
        ) {
            Ok(_) => ProofOutcomeSubmissionDispositionV1::Submitted,
            Err(crate::Error::PushIntoQueue { source, .. }) => {
                classify_local_proof_outcome_submission(source.as_ref())
            }
            Err(_) => ProofOutcomeSubmissionDispositionV1::Ambiguous,
        }
    } else {
        let response = crate::execute_torii_transaction_via_proxy(
            state,
            accepted,
            routing_plan,
            true,
            crate::utils::ResponseFormat::Norito,
        )
        .await;
        if response.status() == StatusCode::ACCEPTED {
            ProofOutcomeSubmissionDispositionV1::Submitted
        } else {
            ProofOutcomeSubmissionDispositionV1::Ambiguous
        }
    };
    match disposition {
        ProofOutcomeSubmissionDispositionV1::Submitted => state
            .sorafs_node
            .mark_proof_outcome_submitted(operation_id)
            .is_ok(),
        ProofOutcomeSubmissionDispositionV1::DefinitelyNotSubmitted => {
            let _ = state
                .sorafs_node
                .mark_proof_outcome_not_submitted(operation_id);
            false
        }
        ProofOutcomeSubmissionDispositionV1::Rejected => {
            let finalized_cursor = {
                let view = state.state.query_view();
                u64::try_from(view.block_hashes.len())
                    .ok()
                    .zip(view.block_hashes.last())
                    .map(|(height, hash)| ProofOutcomeFinalizedCursorV1 {
                        height,
                        block_hash: *hash.as_ref(),
                    })
                    .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
            };
            if let Some(finalized_cursor) = finalized_cursor {
                let _ = state
                    .sorafs_node
                    .mark_proof_outcome_transaction_rejected(operation_id, finalized_cursor);
            }
            false
        }
        ProofOutcomeSubmissionDispositionV1::Ambiguous => false,
    }
}
const SORAFS_REPAIR_TRANSACTION_FORWARDER_SCAN_LIMIT_V1: usize = 256;
const SORAFS_NATIVE_REPAIR_TASK_SCAN_LIMIT_V1: u32 = 32;
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsRepairTransactionForwarderScanV1 {
    pdp_handoffs_resumed: usize,
    por_handoffs_resumed: usize,
    potr_handoffs_resumed: usize,
    task_scanned: usize,
    lease_enqueued: usize,
    terminal_enqueued: usize,
    scanned: usize,
    finalized: usize,
    signed: usize,
    submitted: usize,
    deferred: usize,
    unauthorized_signer: usize,
    conflicted: usize,
    rejected: usize,
}
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsRepairTransactionForwarderCursorV1 {
    after_sequence: Option<u64>,
    after_task_id: Option<[u8; 32]>,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeRepairTaskDispositionV1 {
    Claim,
    Renew { lease_generation: u64 },
    Execute,
    Defer,
}
fn classify_native_repair_task(
    task: &RepairLedgerTaskV1,
    authority: &AccountId,
    now_unix_ms: u64,
    renew_before_ms: u64,
) -> NativeRepairTaskDispositionV1 {
    if now_unix_ms == 0 || task.revision == 0 || task.terminal_outcome.is_some() {
        return NativeRepairTaskDispositionV1::Defer;
    }
    let Some(lease) = task.lease.as_ref() else {
        return NativeRepairTaskDispositionV1::Claim;
    };
    if lease.expires_at_unix_ms <= now_unix_ms {
        return NativeRepairTaskDispositionV1::Claim;
    }
    if lease.generation == 0
        || &lease.owner != authority
        || lease.acquired_at_unix_ms == 0
        || lease.renewed_at_unix_ms < lease.acquired_at_unix_ms
        || lease.expires_at_unix_ms <= lease.renewed_at_unix_ms
    {
        return NativeRepairTaskDispositionV1::Defer;
    }
    if lease.expires_at_unix_ms.saturating_sub(now_unix_ms) <= renew_before_ms {
        NativeRepairTaskDispositionV1::Renew {
            lease_generation: lease.generation,
        }
    } else {
        NativeRepairTaskDispositionV1::Execute
    }
}
fn gate_native_repair_task_generation(
    enabled: bool,
    disposition: NativeRepairTaskDispositionV1,
) -> NativeRepairTaskDispositionV1 {
    if enabled {
        disposition
    } else {
        NativeRepairTaskDispositionV1::Defer
    }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairTransactionSubmissionDispositionV1 {
    Submitted,
    DefinitelyNotSubmitted,
    Rejected,
    Ambiguous,
}
fn classify_local_repair_transaction_submission(
    error: &iroha_core::queue::Error,
) -> RepairTransactionSubmissionDispositionV1 {
    match error {
        iroha_core::queue::Error::InBlockchain | iroha_core::queue::Error::IsInQueue => {
            RepairTransactionSubmissionDispositionV1::Submitted
        }
        iroha_core::queue::Error::Expired
        | iroha_core::queue::Error::TransactionDomainMismatch(_) => {
            RepairTransactionSubmissionDispositionV1::Rejected
        }
        _ => RepairTransactionSubmissionDispositionV1::DefinitelyNotSubmitted,
    }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairAuthorizationScopeV1 {
    Provider([u8; 32]),
    ProviderOwner([u8; 32]),
}
impl RepairAuthorizationScopeV1 {
    fn is_authorized(self, world: &impl WorldReadOnly, authority: &AccountId) -> bool {
        let provider_id = ProviderId::new(match self {
            Self::Provider(provider_id) | Self::ProviderOwner(provider_id) => provider_id,
        });
        match self {
            Self::Provider(_) => {
                let required = Permission::from(CanOperateSorafsRepair { provider_id });
                crate::torii_account_has_permission(world, authority, &required)
            }
            Self::ProviderOwner(_) => world
                .provider_owners()
                .get(&provider_id)
                .is_some_and(|owner| owner == authority),
        }
    }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairSemanticReconciliationV1 {
    Finalized(RepairFinalizedCursorV1),
    Ready(RepairAuthorizationScopeV1),
    Deferred,
    Conflict(RepairFinalizedCursorV1),
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairTransactionReconciliationV1 {
    Finalized(RepairFinalizedCursorV1),
    Ready {
        finalized_cursor: RepairFinalizedCursorV1,
        authority_is_authorized: bool,
    },
    Deferred,
    Conflict(RepairFinalizedCursorV1),
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairCommittedExternalOutcomeV1 {
    Applied,
    Rejected,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairAuthoritativeTransactionOutcomeV1 {
    Absent,
    Applied,
    Rejected,
    Unavailable,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairExactDeliveryDispositionV1 {
    Applied,
    Rejected,
    FinalizedAbsent,
    Pending,
    Unavailable,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RepairExactTransactionObservationV1 {
    reconciliation: RepairTransactionReconciliationV1,
    finalized_cursor: RepairFinalizedCursorV1,
    transaction_outcome: RepairAuthoritativeTransactionOutcomeV1,
}
fn classify_exact_repair_entrypoint_outcome(
    expected_hash: &HashOf<SignedTransaction>,
    block_available: bool,
    results: impl IntoIterator<Item = (HashOf<SignedTransaction>, RepairCommittedExternalOutcomeV1)>,
) -> RepairAuthoritativeTransactionOutcomeV1 {
    if !block_available {
        return RepairAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    let mut exact = results
        .into_iter()
        .filter_map(|(hash, outcome)| (&hash == expected_hash).then_some(outcome));
    let Some(outcome) = exact.next() else {
        return RepairAuthoritativeTransactionOutcomeV1::Unavailable;
    };
    if exact.next().is_some() {
        return RepairAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    match outcome {
        RepairCommittedExternalOutcomeV1::Applied => {
            RepairAuthoritativeTransactionOutcomeV1::Applied
        }
        RepairCommittedExternalOutcomeV1::Rejected => {
            RepairAuthoritativeTransactionOutcomeV1::Rejected
        }
    }
}
fn classify_exact_repair_delivery(
    transaction_outcome: RepairAuthoritativeTransactionOutcomeV1,
    finalized_cursor: RepairFinalizedCursorV1,
    baseline_finalized_height: u64,
    local_evidence_blocks_absence_retry: bool,
) -> RepairExactDeliveryDispositionV1 {
    match transaction_outcome {
        RepairAuthoritativeTransactionOutcomeV1::Applied => {
            RepairExactDeliveryDispositionV1::Applied
        }
        RepairAuthoritativeTransactionOutcomeV1::Rejected => {
            RepairExactDeliveryDispositionV1::Rejected
        }
        RepairAuthoritativeTransactionOutcomeV1::Unavailable => {
            RepairExactDeliveryDispositionV1::Unavailable
        }
        RepairAuthoritativeTransactionOutcomeV1::Absent if local_evidence_blocks_absence_retry => {
            RepairExactDeliveryDispositionV1::Pending
        }
        RepairAuthoritativeTransactionOutcomeV1::Absent
            if finalized_cursor.height > baseline_finalized_height =>
        {
            RepairExactDeliveryDispositionV1::FinalizedAbsent
        }
        RepairAuthoritativeTransactionOutcomeV1::Absent => {
            RepairExactDeliveryDispositionV1::Unavailable
        }
    }
}
fn retained_repair_transaction_digest_for_finalization(
    retained_digest: Option<[u8; 32]>,
    signed_transaction_bytes: Option<&[u8]>,
) -> Option<[u8; 32]> {
    let retained_digest = retained_digest.filter(|digest| *digest != [0; 32])?;
    let signed_transaction_bytes = signed_transaction_bytes?;
    (*blake3_hash(signed_transaction_bytes).as_bytes() == retained_digest)
        .then_some(retained_digest)
}
fn decode_canonical_repair_report(bytes: &[u8]) -> Option<RepairReportV1> {
    if bytes.is_empty() {
        return None;
    }
    norito::core::from_bytes_view(bytes).ok()?;
    let report: RepairReportV1 = norito::decode_from_bytes(bytes).ok()?;
    if report.validate().is_err() || norito::to_bytes(&report).ok()?.as_slice() != bytes {
        return None;
    }
    Some(report)
}
fn repair_operation_ticket_id(
    operation: &sorafs_node::repair_transaction_forwarder::RepairOperationV1,
) -> Option<String> {
    match operation {
        sorafs_node::repair_transaction_forwarder::RepairOperationV1::Submit(instruction) => {
            decode_canonical_repair_report(instruction.report_payload())
                .map(|report| report.ticket_id.0)
        }
        sorafs_node::repair_transaction_forwarder::RepairOperationV1::Action(instruction) => {
            Some(instruction.ticket_id().clone())
        }
        sorafs_node::repair_transaction_forwarder::RepairOperationV1::Appeal(instruction) => {
            Some(instruction.ticket_id().clone())
        }
    }
}
fn classify_repair_semantic_reconciliation(
    request: &sorafs_node::repair_transaction_forwarder::RepairTransactionSigningRequestV1,
    finalized: Option<&RepairFinalizedTaskV1>,
) -> Option<RepairSemanticReconciliationV1> {
    use sorafs_node::repair_transaction_forwarder::RepairOperationV1;
    match &request.operation {
        RepairOperationV1::Submit(instruction) => {
            let report = decode_canonical_repair_report(instruction.report_payload())?;
            let Some(finalized) = finalized else {
                return Some(RepairSemanticReconciliationV1::Ready(
                    RepairAuthorizationScopeV1::Provider(report.evidence.provider_id),
                ));
            };
            if finalized.task.source_identity == *instruction.source_identity()
                && finalized.task.canonical_report.as_slice()
                    == instruction.report_payload().as_slice()
                && finalized.task.submitted_by == request.authority
            {
                Some(RepairSemanticReconciliationV1::Finalized(
                    finalized.finalized_cursor,
                ))
            } else {
                Some(RepairSemanticReconciliationV1::Conflict(
                    finalized.finalized_cursor,
                ))
            }
        }
        RepairOperationV1::Action(instruction) => {
            let Some(finalized) = finalized else {
                return Some(RepairSemanticReconciliationV1::Deferred);
            };
            let idempotency_digest = sorafs_repair_idempotency_digest_v1(
                instruction.ticket_id(),
                instruction.action().idempotency_key(),
            );
            let action_digest =
                sorafs_repair_action_digest_v1(&request.authority, instruction).ok()?;
            if let Some(receipt) = finalized
                .task
                .action_receipts
                .iter()
                .find(|receipt| receipt.idempotency_digest == idempotency_digest)
            {
                return Some(if receipt.action_digest == action_digest {
                    RepairSemanticReconciliationV1::Finalized(finalized.finalized_cursor)
                } else {
                    RepairSemanticReconciliationV1::Conflict(finalized.finalized_cursor)
                });
            }
            if finalized.task.revision < *instruction.expected_revision() {
                return Some(RepairSemanticReconciliationV1::Deferred);
            }
            if finalized.task.revision > *instruction.expected_revision()
                || finalized.task.terminal_outcome.is_some()
            {
                return Some(RepairSemanticReconciliationV1::Conflict(
                    finalized.finalized_cursor,
                ));
            }
            Some(RepairSemanticReconciliationV1::Ready(
                RepairAuthorizationScopeV1::Provider(finalized.task.provider_id),
            ))
        }
        RepairOperationV1::Appeal(instruction) => {
            let Some(finalized) = finalized else {
                return Some(RepairSemanticReconciliationV1::Deferred);
            };
            let idempotency_digest = sorafs_repair_idempotency_digest_v1(
                instruction.ticket_id(),
                instruction.idempotency_key(),
            );
            let action_digest =
                sorafs_repair_action_digest_v1(&request.authority, instruction).ok()?;
            if let Some(receipt) = finalized
                .task
                .action_receipts
                .iter()
                .find(|receipt| receipt.idempotency_digest == idempotency_digest)
            {
                return Some(if receipt.action_digest == action_digest {
                    RepairSemanticReconciliationV1::Finalized(finalized.finalized_cursor)
                } else {
                    RepairSemanticReconciliationV1::Conflict(finalized.finalized_cursor)
                });
            }
            if finalized.task.revision < *instruction.expected_revision() {
                return Some(RepairSemanticReconciliationV1::Deferred);
            }
            let appeal_is_admissible = finalized.task.revision == *instruction.expected_revision()
                && finalized.task.appeal.is_none()
                && finalized.task.slash.is_some()
                && matches!(
                    finalized
                        .task
                        .terminal_outcome
                        .as_ref()
                        .map(|outcome| &outcome.kind),
                    Some(RepairLedgerTerminalKindV1::Escalated(_))
                );
            if !appeal_is_admissible {
                return Some(RepairSemanticReconciliationV1::Conflict(
                    finalized.finalized_cursor,
                ));
            }
            Some(RepairSemanticReconciliationV1::Ready(
                RepairAuthorizationScopeV1::ProviderOwner(finalized.task.provider_id),
            ))
        }
    }
}
fn reconcile_sorafs_repair_transaction_in_view(
    view: &impl StateReadOnly,
    request: &sorafs_node::repair_transaction_forwarder::RepairTransactionSigningRequestV1,
    finalized_cursor: RepairFinalizedCursorV1,
) -> Option<RepairTransactionReconciliationV1> {
    let ticket_id = repair_operation_ticket_id(&request.operation)?;
    let finalized = match FindSorafsRepairTask::new(ticket_id, Some(finalized_cursor)).execute(view)
    {
        Ok(finalized) => Some(finalized),
        Err(QueryExecutionFail::Find(FindError::SorafsRepairTask(_))) => None,
        Err(_) => return None,
    };
    let semantic = classify_repair_semantic_reconciliation(request, finalized.as_ref())?;
    Some(match semantic {
        RepairSemanticReconciliationV1::Finalized(cursor) => {
            RepairTransactionReconciliationV1::Finalized(cursor)
        }
        RepairSemanticReconciliationV1::Ready(scope) => RepairTransactionReconciliationV1::Ready {
            finalized_cursor,
            authority_is_authorized: scope.is_authorized(view.world(), &request.authority),
        },
        RepairSemanticReconciliationV1::Deferred => RepairTransactionReconciliationV1::Deferred,
        RepairSemanticReconciliationV1::Conflict(cursor) => {
            RepairTransactionReconciliationV1::Conflict(cursor)
        }
    })
}
fn reconcile_sorafs_repair_transaction(
    state: &SharedAppState,
    request: &sorafs_node::repair_transaction_forwarder::RepairTransactionSigningRequestV1,
) -> Option<RepairTransactionReconciliationV1> {
    let view = state.state.query_view();
    let finalized_cursor = sorafs_repair_finalized_cursor_from_view(&view)?;
    reconcile_sorafs_repair_transaction_in_view(&view, request, finalized_cursor)
}
fn inspect_indexed_repair_transaction(
    state: &iroha_core::state::State,
    transaction_hash: &HashOf<SignedTransaction>,
    block_height: NonZeroUsize,
    expected_block_hash: HashOf<BlockHeader>,
) -> RepairAuthoritativeTransactionOutcomeV1 {
    let Ok((_header, outcome)) = crate::canonical_history::exact_external_outcome(
        state,
        block_height,
        expected_block_hash,
        transaction_hash,
    ) else {
        return RepairAuthoritativeTransactionOutcomeV1::Unavailable;
    };
    classify_exact_repair_entrypoint_outcome(
        transaction_hash,
        true,
        outcome.map(|applied| {
            (
                *transaction_hash,
                if applied {
                    RepairCommittedExternalOutcomeV1::Applied
                } else {
                    RepairCommittedExternalOutcomeV1::Rejected
                },
            )
        }),
    )
}
fn observe_exact_sorafs_repair_transaction(
    state: &SharedAppState,
    request: &sorafs_node::repair_transaction_forwarder::RepairTransactionSigningRequestV1,
    transaction_hash: &HashOf<SignedTransaction>,
) -> Option<RepairExactTransactionObservationV1> {
    let view = state.state.view();
    let finalized_cursor = sorafs_repair_finalized_cursor_from_view(&view)?;
    let reconciliation =
        reconcile_sorafs_repair_transaction_in_view(&view, request, finalized_cursor)?;
    let input = iroha_core::tx::external_entrypoint_hash_from_signed_hash(*transaction_hash);
    let indexed_height = view.transactions().get(&input);
    let carrier = indexed_height.and_then(|height| {
        view.block_hashes()
            .get(height.get() - 1)
            .copied()
            .map(|hash| (height, hash))
    });
    drop(view);
    let transaction_outcome = match (indexed_height, carrier) {
        (None, _) => RepairAuthoritativeTransactionOutcomeV1::Absent,
        (Some(_), None) => RepairAuthoritativeTransactionOutcomeV1::Unavailable,
        (Some(_), Some((height, expected))) => {
            inspect_indexed_repair_transaction(&state.state, transaction_hash, height, expected)
        }
    };
    let current = state.state.view();
    let cursor_height = usize::try_from(finalized_cursor.height).ok()?;
    if current
        .block_hashes()
        .get(cursor_height.checked_sub(1)?)
        .map(|hash| *hash.as_ref())
        != Some(finalized_cursor.block_hash)
        || current.transactions().get(&input) != indexed_height
    {
        return None;
    }
    Some(RepairExactTransactionObservationV1 {
        reconciliation,
        finalized_cursor,
        transaction_outcome,
    })
}
#[cfg(test)]
