fn moderation_quarantine_appeal_handoff_deposit_request(
    req: ModerationQuarantineAppealHandoffRequestDto,
    quote: &AppealQuote,
    evidence_bundle_digest: [u8; 32],
    policy: &AppealFinanceRuntimePolicy,
) -> Result<AppealFinanceDepositRequestDto, String> {
    if req.asset_definition_id != policy.asset_definition_id.to_string() {
        return Err(format!(
            "appeal handoff asset_definition_id must equal governed asset `{}`",
            policy.asset_definition_id
        ));
    }
    let deposit_xor = XorQuantity::try_from_quantity(quote.deposit_xor.clone())
        .map_err(|err| format!("appeal quote produced an invalid XOR deposit: {err}"))?;
    Ok(AppealFinanceDepositRequestDto {
        case_id: req.case_id,
        round_id: Some(req.round_id),
        payer_account: req.payer_account,
        destination_account: req.destination_account,
        release_authority_account: req.release_authority_account,
        asset_definition_id: req.asset_definition_id,
        deposit_xor,
        expires_at_ms: req.expires_at_ms,
        idempotency_key: req.idempotency_key,
        evidence_hashes_hex: Some(vec![Hash::prehashed(evidence_bundle_digest).to_string()]),
    })
}
fn moderation_quarantine_appeal_handoff_evidence_hash(
    record: &ModerationQuarantineRecord,
    quarantine_id_hex: &str,
    reviewed_at_unix: u64,
) -> Hash {
    Hash::new(format!(
        "sorafs.moderation.quarantine.appeal_handoff.v1\nquarantine_id={quarantine_id_hex}\nscreening_record_id={}\nsubject_digest={}\nreviewed_at_unix={reviewed_at_unix}\n",
        hex::encode(record.screening_record_id),
        hex::encode(record.subject_digest),
    ))
}
fn appeal_finance_deposit_expectation_with_policy(
    req: AppealFinanceDepositRequestDto,
    policy: &AppealFinanceRuntimePolicy,
) -> Result<AppealFinanceDepositExpectation, String> {
    let case_id = required_appeal_finance_label("case_id", &req.case_id)?;
    let round_id = req
        .round_id
        .as_deref()
        .map(|round_id| required_appeal_finance_label("round_id", round_id))
        .transpose()?;
    let idempotency_key = required_appeal_finance_label("idempotency_key", &req.idempotency_key)?;
    let payer_account = appeal_finance_account_id("payer_account", &req.payer_account)?;
    let destination_account =
        appeal_finance_account_id("destination_account", &req.destination_account)?;
    let release_authority_account = req
        .release_authority_account
        .as_deref()
        .map(|raw| appeal_finance_account_id("release_authority_account", raw))
        .transpose()?;
    let asset_definition_id = appeal_finance_asset_definition_id(&req.asset_definition_id)?;
    if asset_definition_id != policy.asset_definition_id {
        return Err(format!(
            "SoraFS appeal finance `asset_definition_id` must equal governed asset `{}`",
            policy.asset_definition_id
        ));
    }
    let deposit_xor = appeal_finance_deposit_amount(req.deposit_xor)?;
    if req.expires_at_ms == Some(0) {
        return Err(
            "SoraFS appeal finance `expires_at_ms` must be nonzero when supplied".to_owned(),
        );
    }
    let evidence_hashes = appeal_finance_evidence_hashes(req.evidence_hashes_hex.as_deref())?;
    let escrow_id = appeal_finance_deposit_escrow_id(
        (&case_id, round_id.as_deref()),
        (
            &payer_account,
            &destination_account,
            release_authority_account.as_ref(),
        ),
        &asset_definition_id,
        &deposit_xor,
        req.expires_at_ms,
        &idempotency_key,
        &evidence_hashes,
    );
    Ok(AppealFinanceDepositExpectation {
        case_id,
        round_id,
        payer_account,
        destination_account,
        release_authority_account,
        asset_definition_id,
        deposit_xor,
        expires_at_ms: req.expires_at_ms,
        idempotency_key,
        evidence_hashes,
        escrow_id,
    })
}
#[cfg(test)]
fn appeal_finance_deposit_expectation(
    req: AppealFinanceDepositRequestDto,
) -> Result<AppealFinanceDepositExpectation, String> {
    appeal_finance_deposit_expectation_with_policy(req, &baseline_appeal_finance_runtime_policy())
}
fn appeal_finance_deposit_instruction(
    req: AppealFinanceDepositRequestDto,
    authenticated_account: &AccountId,
    policy: &AppealFinanceRuntimePolicy,
) -> Result<AppealFinanceDepositInstruction, DepositInstructionError> {
    let expected = appeal_finance_deposit_expectation_with_policy(req, policy)
        .map_err(DepositInstructionError::Invalid)?;
    if &expected.payer_account != authenticated_account {
        return Err(DepositInstructionError::Forbidden(
            "SoraFS appeal finance deposit payer_account must match the authenticated account"
                .to_owned(),
        ));
    }
    Ok(AppealFinanceDepositInstruction { expected })
}
fn appeal_finance_open_asset_lock(expected: &AppealFinanceDepositExpectation) -> OpenAssetLock {
    OpenAssetLock::with_options(
        expected.escrow_id,
        expected.asset_definition_id.clone(),
        expected.destination_account.clone(),
        expected.deposit_xor.clone(),
        expected.release_authority_account.clone(),
        expected.expires_at_ms,
        expected.evidence_hashes.clone(),
    )
}
fn appeal_finance_deposit_settlement_execution(
    expected: &AppealFinanceDepositExpectation,
    record: &AssetEscrowRecord,
    breakdown: &AppealSettlementBreakdown,
) -> Result<AppealFinanceDepositSettlementExecution, String> {
    let drawdown_xor = breakdown
        .treasury_xor
        .try_add(&breakdown.held_xor)
        .map_err(|error| format!("invalid SoraFS appeal finance `drawdown_xor`: {error}"))?;
    let refund_xor = breakdown.refund_xor.clone();
    let zero = iroha_primitives::numeric::Quantity::zero();
    let mut steps = Vec::new();
    if drawdown_xor > zero {
        let required_authority = record
            .release_authority
            .clone()
            .or_else(|| record.buyer.clone())
            .ok_or_else(|| {
                "SoraFS appeal finance asset lock settlement requires a lock destination".to_owned()
            })?;
        steps.push(AppealFinanceSettlementStep {
            action: "drawdown_non_refund",
            required_authority,
            amount_xor: drawdown_xor.clone(),
        });
    }
    if refund_xor > zero {
        steps.push(AppealFinanceSettlementStep {
            action: "cancel_refund",
            required_authority: expected.payer_account.clone(),
            amount_xor: refund_xor.clone(),
        });
    }
    Ok(AppealFinanceDepositSettlementExecution {
        drawdown_xor,
        refund_xor,
        steps,
    })
}
fn appeal_finance_deposit_next_settlement_submission_step<'a>(
    reconciliation: &AppealFinanceDepositSettlementReconciliation,
    execution: &'a AppealFinanceDepositSettlementExecution,
) -> Option<&'a AppealFinanceSettlementStep> {
    match reconciliation.status {
        "pending_forwarder_submission" => execution.steps.first(),
        "awaiting_refund_cancel" => execution
            .steps
            .iter()
            .find(|step| step.action == "cancel_refund"),
        _ => None,
    }
}
#[allow(clippy::too_many_arguments)]
fn appeal_finance_deposit_settlement_receipt(
    appeal_finance_policy_digest: [u8; 32],
    appeal_finance_config_version: &str,
    expected: &AppealFinanceDepositExpectation,
    record: &AssetEscrowRecord,
    verdict: AppealVerdict,
    panel_size: u32,
    breakdown: &AppealSettlementBreakdown,
    reconciliation: &AppealFinanceDepositSettlementReconciliation,
    step: &AppealFinanceSettlementStep,
    tx_hash_hex: &str,
    finalized_block_height: u64,
    finalized_block_hash: [u8; 32],
    configured_signer_count: usize,
    generated_at_unix_ms: u64,
) -> Result<SoraFsAppealFinanceSettlementReceiptV1, String> {
    if appeal_finance_policy_digest == [0; 32]
        || !is_canonical_appeal_finance_policy_version(appeal_finance_config_version)
        || finalized_block_height == 0
        || finalized_block_hash == [0; 32]
    {
        return Err("invalid SoraFS appeal finance receipt policy binding".to_owned());
    }
    let configured_signer_count = u32::try_from(configured_signer_count).unwrap_or(u32::MAX);
    let receipt_id = appeal_finance_settlement_receipt_id(
        expected,
        appeal_finance_policy_digest,
        (verdict, panel_size),
        step,
        tx_hash_hex,
        &reconciliation.reconciliation_digest_hex,
        (
            finalized_block_height,
            finalized_block_hash,
            generated_at_unix_ms,
        ),
    );
    let xor_quantity = |field: &str, value: &Quantity| {
        XorQuantity::try_from_quantity(value.clone())
            .map_err(|err| format!("invalid `{field}` XOR quantity: {err}"))
    };
    Ok(SoraFsAppealFinanceSettlementReceiptV1 {
        version: SORAFS_APPEAL_FINANCE_SETTLEMENT_RECEIPT_VERSION_V1,
        receipt_id,
        case_id: expected.case_id.clone(),
        round_id: expected.round_id.clone(),
        generated_at_unix_ms,
        finalized_block_height,
        finalized_block_hash,
        appeal_finance_config_version: appeal_finance_config_version.to_owned(),
        appeal_finance_policy_digest,
        outcome: appeal_finance_manifest_outcome_from_verdict(verdict),
        escrow_id_hex: expected.escrow_id.as_hash().to_string(),
        payer_account: expected.payer_account.to_string(),
        destination_account: expected.destination_account.to_string(),
        release_authority_account: expected
            .release_authority_account
            .as_ref()
            .map(ToString::to_string),
        submitted_step: step.action.to_owned(),
        required_authority: step.required_authority.to_string(),
        amount_xor: xor_quantity("amount_xor", &step.amount_xor)?,
        tx_hash_hex: tx_hash_hex.to_owned(),
        reconciliation_digest_hex: reconciliation.reconciliation_digest_hex.clone(),
        reconciliation_status: reconciliation.status.to_owned(),
        observed_lifecycle_status: asset_escrow_status_label(record.status).to_owned(),
        observed_remaining_xor: xor_quantity("observed_remaining_xor", &record.remaining_amount)?,
        deposit_xor: xor_quantity("deposit_xor", &expected.deposit_xor)?,
        refund_xor: xor_quantity("refund_xor", &breakdown.refund_xor)?,
        treasury_xor: xor_quantity("treasury_xor", &breakdown.treasury_xor)?,
        held_xor: xor_quantity("held_xor", &breakdown.held_xor)?,
        panel_size,
        configured_signer_count,
    })
}
fn appeal_finance_manifest_outcome_from_verdict(
    verdict: AppealVerdict,
) -> SoraFsAppealFinanceOutcomeV1 {
    match verdict {
        AppealVerdict::Decision(AppealDecision::Uphold) => SoraFsAppealFinanceOutcomeV1::Uphold,
        AppealVerdict::Decision(AppealDecision::Overturn) => SoraFsAppealFinanceOutcomeV1::Overturn,
        AppealVerdict::Decision(AppealDecision::Modify) => SoraFsAppealFinanceOutcomeV1::Modify,
        AppealVerdict::WithdrawnBeforePanel => SoraFsAppealFinanceOutcomeV1::WithdrawnBeforePanel,
        AppealVerdict::WithdrawnAfterPanel => SoraFsAppealFinanceOutcomeV1::WithdrawnAfterPanel,
        AppealVerdict::Frivolous => SoraFsAppealFinanceOutcomeV1::Frivolous,
        AppealVerdict::Escalated => SoraFsAppealFinanceOutcomeV1::Escalated,
    }
}
fn appeal_finance_settlement_receipt_id(
    expected: &AppealFinanceDepositExpectation,
    appeal_finance_policy_digest: [u8; 32],
    (verdict, panel_size): (AppealVerdict, u32),
    step: &AppealFinanceSettlementStep,
    tx_hash_hex: &str,
    reconciliation_digest_hex: &str,
    (finalized_block_height, finalized_block_hash, generated_at_unix_ms): (u64, [u8; 32], u64),
) -> [u8; 16] {
    let mut material = String::from("sorafs.appeal_finance.settlement_receipt.id.v1\n");
    push_digest_field(&mut material, "case_id", &expected.case_id);
    push_digest_optional_field(&mut material, "round_id", expected.round_id.as_deref());
    push_digest_field(&mut material, "escrow_id_hex", expected.escrow_id.as_hash());
    push_digest_field(
        &mut material,
        "appeal_finance_policy_digest_hex",
        hex::encode(appeal_finance_policy_digest),
    );
    push_digest_field(&mut material, "outcome", verdict);
    push_digest_field(&mut material, "panel_size", panel_size);
    push_digest_field(&mut material, "submitted_step", step.action);
    push_digest_field(
        &mut material,
        "required_authority",
        &step.required_authority,
    );
    push_digest_field(&mut material, "amount_xor", &step.amount_xor);
    push_digest_field(&mut material, "tx_hash_hex", tx_hash_hex);
    push_digest_field(
        &mut material,
        "reconciliation_digest_hex",
        reconciliation_digest_hex,
    );
    push_digest_field(
        &mut material,
        "finalized_block_height",
        finalized_block_height,
    );
    push_digest_field(
        &mut material,
        "finalized_block_hash_hex",
        hex::encode(finalized_block_hash),
    );
    push_digest_field(&mut material, "generated_at_unix_ms", generated_at_unix_ms);
    let digest = blake3_hash(material.as_bytes());
    let mut receipt_id = [0_u8; 16];
    receipt_id.copy_from_slice(&digest.as_bytes()[..16]);
    receipt_id
}
fn appeal_finance_deposit_settlement_reconciliation(
    expected: &AppealFinanceDepositExpectation,
    record: &AssetEscrowRecord,
    policy: &AppealFinanceRuntimePolicy,
    verdict: AppealVerdict,
    panel_size: u32,
    breakdown: &AppealSettlementBreakdown,
) -> Result<AppealFinanceDepositSettlementReconciliation, String> {
    appeal_finance_deposit_settlement_reconciliation_with_policy_binding(
        expected,
        record,
        policy.policy_digest,
        policy.settlement().version(),
        policy.asset_scale,
        verdict,
        panel_size,
        breakdown,
    )
}
#[allow(clippy::too_many_arguments)]
fn appeal_finance_deposit_settlement_reconciliation_with_policy_binding(
    expected: &AppealFinanceDepositExpectation,
    record: &AssetEscrowRecord,
    appeal_finance_policy_digest: [u8; 32],
    settlement_config_version: &str,
    asset_scale: u32,
    verdict: AppealVerdict,
    panel_size: u32,
    breakdown: &AppealSettlementBreakdown,
) -> Result<AppealFinanceDepositSettlementReconciliation, String> {
    if appeal_finance_policy_digest == [0; 32]
        || !is_canonical_appeal_finance_policy_version(settlement_config_version)
        || asset_scale
            != iroha_config::parameters::defaults::torii::sorafs_appeal_finance::ASSET_SCALE
    {
        return Err("invalid SoraFS appeal finance reconciliation policy binding".to_owned());
    }
    let execution = appeal_finance_deposit_settlement_execution(expected, record, breakdown)?;
    let zero = Quantity::zero();
    let mut mismatches = appeal_finance_deposit_static_mismatches(expected, record);
    let expected_remaining_xor = if execution.refund_xor > zero {
        zero.clone()
    } else {
        expected
            .deposit_xor
            .checked_sub(&execution.drawdown_xor)
            .map_err(|_| {
                "SoraFS appeal finance settlement drawdown exceeds deposit amount".to_owned()
            })?
    };
    let expected_final_status = if execution.refund_xor > zero {
        AssetEscrowStatus::Cancelled
    } else if expected_remaining_xor.is_zero() {
        AssetEscrowStatus::DrawnDown
    } else {
        AssetEscrowStatus::Locked
    };
    let status = if mismatches.is_empty()
        && record.status == expected_final_status
        && record.remaining_amount == expected_remaining_xor
    {
        "settled"
    } else if mismatches.is_empty()
        && record.status == AssetEscrowStatus::Locked
        && record.remaining_amount == expected.deposit_xor
    {
        "pending_forwarder_submission"
    } else if mismatches.is_empty()
        && record.status == AssetEscrowStatus::Locked
        && execution.refund_xor > zero
        && execution.drawdown_xor > zero
        && record.remaining_amount == execution.refund_xor
    {
        "awaiting_refund_cancel"
    } else {
        if record.status != expected_final_status {
            mismatches.push(format!(
                "lifecycle_status expected `{}` after settlement but ledger has `{}`",
                asset_escrow_status_label(expected_final_status),
                asset_escrow_status_label(record.status)
            ));
        }
        if record.remaining_amount != expected_remaining_xor {
            mismatches.push(format!(
                "remaining_amount expected `{}` after settlement but ledger has `{}`",
                expected_remaining_xor, record.remaining_amount
            ));
        }
        "mismatch"
    };
    let reconciliation_digest_hex = appeal_finance_deposit_settlement_reconciliation_digest_hex(
        expected,
        record,
        appeal_finance_policy_digest,
        settlement_config_version,
        asset_scale,
        verdict,
        panel_size,
        breakdown,
        status,
        expected_final_status,
        &expected_remaining_xor,
        &execution.drawdown_xor,
        &execution.refund_xor,
        &mismatches,
    );
    Ok(AppealFinanceDepositSettlementReconciliation {
        status,
        reconciled: status == "settled",
        reconciliation_digest_hex,
        expected_final_status,
        expected_remaining_xor,
        drawdown_xor: execution.drawdown_xor,
        refund_xor: execution.refund_xor,
        mismatches,
    })
}
#[allow(clippy::too_many_arguments)]
fn appeal_finance_deposit_settlement_reconciliation_digest_hex(
    expected: &AppealFinanceDepositExpectation,
    record: &AssetEscrowRecord,
    appeal_finance_policy_digest: [u8; 32],
    settlement_config_version: &str,
    asset_scale: u32,
    verdict: AppealVerdict,
    panel_size: u32,
    breakdown: &AppealSettlementBreakdown,
    status: &str,
    expected_final_status: AssetEscrowStatus,
    expected_remaining_xor: &Quantity,
    drawdown_xor: &Quantity,
    refund_xor: &Quantity,
    mismatches: &[String],
) -> String {
    let mut material = String::from("sorafs.appeal_finance.deposit_settlement_reconciliation.v1\n");
    push_digest_field(&mut material, "source", APPEAL_FINANCE_CONFIG_SOURCE_V1);
    push_digest_field(
        &mut material,
        "appeal_finance_policy_digest_hex",
        hex::encode(appeal_finance_policy_digest),
    );
    push_digest_field(
        &mut material,
        "settlement_config_version",
        settlement_config_version,
    );
    push_digest_field(&mut material, "asset_scale", asset_scale);
    push_digest_field(&mut material, "status", status);
    push_digest_field(&mut material, "outcome", verdict);
    push_digest_field(&mut material, "panel_size", panel_size);
    push_digest_field(&mut material, "case_id", &expected.case_id);
    push_digest_optional_field(&mut material, "round_id", expected.round_id.as_deref());
    push_digest_field(&mut material, "escrow_id_hex", expected.escrow_id.as_hash());
    push_digest_field(&mut material, "payer_account", &expected.payer_account);
    push_digest_field(
        &mut material,
        "destination_account",
        &expected.destination_account,
    );
    push_digest_optional_field(
        &mut material,
        "release_authority_account",
        expected.release_authority_account.as_ref(),
    );
    push_digest_field(
        &mut material,
        "asset_definition_id",
        &expected.asset_definition_id,
    );
    push_digest_field(&mut material, "deposit_xor", &expected.deposit_xor);
    push_digest_optional_field(&mut material, "expires_at_ms", expected.expires_at_ms);
    push_digest_field(&mut material, "idempotency_key", &expected.idempotency_key);
    push_digest_field(
        &mut material,
        "expected_evidence_hash_count",
        expected.evidence_hashes.len(),
    );
    for (index, hash) in expected.evidence_hashes.iter().enumerate() {
        push_digest_field(
            &mut material,
            &format!("expected_evidence_hash_{index}_hex"),
            hash,
        );
    }
    push_digest_field(&mut material, "refund_xor", &breakdown.refund_xor);
    push_digest_field(&mut material, "treasury_xor", &breakdown.treasury_xor);
    push_digest_field(&mut material, "held_xor", &breakdown.held_xor);
    push_digest_field(&mut material, "expected_drawdown_xor", drawdown_xor);
    push_digest_field(&mut material, "expected_cancel_refund_xor", refund_xor);
    push_digest_field(
        &mut material,
        "expected_final_lifecycle_status",
        asset_escrow_status_label(expected_final_status),
    );
    push_digest_field(
        &mut material,
        "expected_remaining_amount",
        expected_remaining_xor,
    );
    push_digest_field(&mut material, "observed_escrow_id_hex", record.id.as_hash());
    push_digest_field(&mut material, "observed_seller_account", &record.seller);
    push_digest_optional_field(
        &mut material,
        "observed_buyer_account",
        record.buyer.as_ref(),
    );
    push_digest_field(
        &mut material,
        "observed_asset_definition_id",
        &record.asset_definition,
    );
    push_digest_field(&mut material, "observed_amount", &record.amount);
    push_digest_field(&mut material, "observed_custody_account", &record.custody);
    push_digest_field(
        &mut material,
        "observed_lifecycle_status",
        asset_escrow_status_label(record.status),
    );
    push_digest_field(
        &mut material,
        "observed_remaining_amount",
        &record.remaining_amount,
    );
    push_digest_field(
        &mut material,
        "observed_kind",
        asset_escrow_kind_label(record.kind),
    );
    push_digest_optional_field(
        &mut material,
        "observed_release_authority",
        record.release_authority.as_ref(),
    );
    push_digest_optional_field(
        &mut material,
        "observed_expires_at_ms",
        record.expires_at_ms,
    );
    push_digest_field(
        &mut material,
        "observed_evidence_hash_count",
        record.evidence_hashes.len(),
    );
    for (index, hash) in record.evidence_hashes.iter().enumerate() {
        push_digest_field(
            &mut material,
            &format!("observed_evidence_hash_{index}_hex"),
            hash,
        );
    }
    push_digest_field(
        &mut material,
        "observed_created_at_ms",
        record.created_at_ms,
    );
    push_digest_optional_field(
        &mut material,
        "observed_accepted_at_ms",
        record.accepted_at_ms,
    );
    push_digest_optional_field(
        &mut material,
        "observed_payment_sent_at_ms",
        record.payment_sent_at_ms,
    );
    push_digest_optional_field(
        &mut material,
        "observed_disputed_at_ms",
        record.disputed_at_ms,
    );
    push_digest_optional_field(&mut material, "observed_closed_at_ms", record.closed_at_ms);
    match &record.resolution {
        Some(resolution) => {
            push_digest_field(&mut material, "observed_resolution_present", true);
            push_digest_field(
                &mut material,
                "observed_resolution_resolver_account",
                &resolution.resolver,
            );
            push_digest_field(
                &mut material,
                "observed_resolution_buyer_amount",
                &resolution.buyer_amount,
            );
            push_digest_field(
                &mut material,
                "observed_resolution_seller_amount",
                &resolution.seller_amount,
            );
            push_digest_field(
                &mut material,
                "observed_resolution_evidence_hash_count",
                resolution.evidence_hashes.len(),
            );
            for (index, hash) in resolution.evidence_hashes.iter().enumerate() {
                push_digest_field(
                    &mut material,
                    &format!("observed_resolution_evidence_hash_{index}_hex"),
                    hash,
                );
            }
            push_digest_field(
                &mut material,
                "observed_resolution_resolved_at_ms",
                resolution.resolved_at_ms,
            );
        }
        None => {
            push_digest_field(&mut material, "observed_resolution_present", false);
        }
    }
    push_digest_field(&mut material, "mismatch_count", mismatches.len());
    for (index, mismatch) in mismatches.iter().enumerate() {
        push_digest_field(&mut material, &format!("mismatch_{index}"), mismatch);
    }
    hex::encode(blake3_hash(material.as_bytes()).as_bytes())
}
fn push_digest_field(material: &mut String, key: &str, value: impl std::fmt::Display) {
    material.push_str(key);
    material.push('=');
    material.push_str(&value.to_string());
    material.push('\n');
}
fn push_digest_optional_field<T: std::fmt::Display>(
    material: &mut String,
    key: &str,
    value: Option<T>,
) {
    match value {
        Some(value) => push_digest_field(material, key, value),
        None => push_digest_field(material, key, "null"),
    }
}
fn appeal_finance_deposit_confirm_base_request(
    req: &AppealFinanceDepositConfirmRequestDto,
) -> AppealFinanceDepositRequestDto {
    AppealFinanceDepositRequestDto {
        case_id: req.case_id.clone(),
        round_id: req.round_id.clone(),
        payer_account: req.payer_account.clone(),
        destination_account: req.destination_account.clone(),
        release_authority_account: req.release_authority_account.clone(),
        asset_definition_id: req.asset_definition_id.clone(),
        deposit_xor: req.deposit_xor.clone(),
        expires_at_ms: req.expires_at_ms,
        idempotency_key: req.idempotency_key.clone(),
        evidence_hashes_hex: req.evidence_hashes_hex.clone(),
    }
}
fn confirm_appeal_finance_deposit_record(
    state: &SharedAppState,
    req: &AppealFinanceDepositConfirmRequestDto,
    authenticated_account: &AccountId,
) -> Result<(AppealFinanceDepositExpectation, AssetEscrowRecord), Response> {
    require_appeal_finance_asset_ready(state, &state.sorafs_appeal_finance_policy)?;
    let escrow_id = appeal_finance_escrow_id_from_hex(&req.escrow_id_hex)
        .map_err(|err| json_error(StatusCode::BAD_REQUEST, err))?;
    let expected = appeal_finance_deposit_expectation_with_policy(
        appeal_finance_deposit_confirm_base_request(req),
        &state.sorafs_appeal_finance_policy,
    )
    .map_err(|err| json_error(StatusCode::BAD_REQUEST, err))?;
    if escrow_id != expected.escrow_id {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "SoraFS appeal finance `escrow_id_hex` does not match the expected deposit parameters",
        ));
    }
    let world = state.state.world_view();
    let record = world
        .asset_escrows()
        .get(&escrow_id)
        .cloned()
        .ok_or_else(|| {
            json_error(
                StatusCode::NOT_FOUND,
                "SoraFS appeal finance deposit asset lock was not found in the runtime ledger",
            )
        })?;
    if !appeal_finance_deposit_record_visible_to(&record, authenticated_account) {
        return Err(json_error(
            StatusCode::FORBIDDEN,
            "SoraFS appeal finance deposit asset lock confirmation is visible only to the opener, destination, or release authority",
        ));
    }
    let mismatches = appeal_finance_deposit_confirmation_mismatches(&expected, &record);
    if !mismatches.is_empty() {
        return Err((
            StatusCode::CONFLICT,
            JsonBody(appeal_finance_deposit_confirmation_mismatch_json(
                &state.sorafs_appeal_finance_policy,
                &expected,
                &record,
                mismatches,
            )),
        )
            .into_response());
    }
    Ok((expected, record))
}
fn load_appeal_finance_deposit_record_for_reconciliation(
    state: &SharedAppState,
    req: &AppealFinanceDepositConfirmRequestDto,
    authenticated_account: &AccountId,
) -> Result<
    (
        AppealFinanceDepositExpectation,
        AssetEscrowRecord,
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
    ),
    Response,
> {
    require_appeal_finance_asset_ready(state, &state.sorafs_appeal_finance_policy)?;
    let escrow_id = appeal_finance_escrow_id_from_hex(&req.escrow_id_hex)
        .map_err(|err| json_error(StatusCode::BAD_REQUEST, err))?;
    let expected = appeal_finance_deposit_expectation_with_policy(
        appeal_finance_deposit_confirm_base_request(req),
        &state.sorafs_appeal_finance_policy,
    )
    .map_err(|err| json_error(StatusCode::BAD_REQUEST, err))?;
    if escrow_id != expected.escrow_id {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "SoraFS appeal finance `escrow_id_hex` does not match the expected deposit parameters",
        ));
    }
    let view = state.state.query_view();
    let finalized_cursor = u64::try_from(view.block_hashes.len())
        .ok()
        .zip(view.block_hashes.last())
        .map(|(height, hash)| {
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1 {
                height,
                block_hash: *hash.as_ref(),
            }
        })
        .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
        .ok_or_else(|| {
            json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "SoraFS appeal finance settlement requires a nonzero finalized ledger cursor",
            )
        })?;
    let record = view
        .world()
        .asset_escrows()
        .get(&escrow_id)
        .cloned()
        .ok_or_else(|| {
            json_error(
                StatusCode::NOT_FOUND,
                "SoraFS appeal finance deposit asset lock was not found in the runtime ledger",
            )
        })?;
    if !appeal_finance_deposit_record_visible_to(&record, authenticated_account) {
        return Err(json_error(
            StatusCode::FORBIDDEN,
            "SoraFS appeal finance deposit settlement reconciliation is visible only to the opener, destination, or release authority",
        ));
    }
    Ok((expected, record, finalized_cursor))
}
fn appeal_finance_deposit_static_mismatches(
    expected: &AppealFinanceDepositExpectation,
    record: &AssetEscrowRecord,
) -> Vec<String> {
    let mut mismatches = Vec::new();
    if record.id != expected.escrow_id {
        mismatches.push("escrow_id_hex does not match the expected derived escrow id".to_owned());
    }
    if record.kind != AssetEscrowKind::Lock {
        mismatches.push(format!(
            "kind expected lock but found {}",
            asset_escrow_kind_label(record.kind)
        ));
    }
    if record.seller != expected.payer_account {
        mismatches.push("payer_account does not match the lock opener".to_owned());
    }
    if record.buyer.as_ref() != Some(&expected.destination_account) {
        mismatches.push("destination_account does not match the lock destination".to_owned());
    }
    if record.release_authority != expected.release_authority_account {
        mismatches.push("release_authority_account does not match the runtime lock".to_owned());
    }
    if record.asset_definition != expected.asset_definition_id {
        mismatches.push("asset_definition_id does not match the runtime lock".to_owned());
    }
    if record.amount != expected.deposit_xor {
        mismatches.push("deposit_xor does not match the runtime lock amount".to_owned());
    }
    if record.expires_at_ms != expected.expires_at_ms {
        mismatches.push("expires_at_ms does not match the runtime lock".to_owned());
    }
    if record.evidence_hashes != expected.evidence_hashes {
        mismatches.push("evidence_hashes_hex do not match the runtime lock".to_owned());
    }
    mismatches
}
fn appeal_finance_deposit_confirmation_mismatches(
    expected: &AppealFinanceDepositExpectation,
    record: &AssetEscrowRecord,
) -> Vec<String> {
    let mut mismatches = appeal_finance_deposit_static_mismatches(expected, record);
    if record.status != AssetEscrowStatus::Locked {
        mismatches.push(format!(
            "lifecycle_status expected locked but found {}",
            asset_escrow_status_label(record.status)
        ));
    }
    if record.remaining_amount != expected.deposit_xor {
        mismatches.push("remaining_amount is not the full expected deposit amount".to_owned());
    }
    mismatches
}
fn required_appeal_finance_label(field: &'static str, raw: &str) -> Result<String, String> {
    const MAX_LABEL_BYTES: usize = 256;
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        Err(format!("SoraFS appeal finance `{field}` must not be empty"))
    } else if trimmed.len() > MAX_LABEL_BYTES || trimmed.chars().any(char::is_control) {
        Err(format!(
            "SoraFS appeal finance `{field}` must be at most {MAX_LABEL_BYTES} bytes without control characters"
        ))
    } else {
        Ok(trimmed.to_owned())
    }
}
fn is_canonical_appeal_finance_policy_version(value: &str) -> bool {
    const MAX_VERSION_BYTES: usize = 128;
    if value.is_empty() || value.len() > MAX_VERSION_BYTES {
        return false;
    }
    let Some((name, revision)) = value.rsplit_once("-v") else {
        return false;
    };
    !name.is_empty()
        && name.split('-').all(|segment| {
            !segment.is_empty()
                && segment
                    .bytes()
                    .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit())
        })
        && revision
            .as_bytes()
            .first()
            .is_some_and(|byte| matches!(byte, b'1'..=b'9'))
        && revision.bytes().all(|byte| byte.is_ascii_digit())
}
fn appeal_finance_deposit_expectation_is_canonical(
    expected: &AppealFinanceDepositExpectation,
) -> bool {
    let label_is_canonical = |field, value: &str| {
        required_appeal_finance_label(field, value).ok().as_deref() == Some(value)
    };
    if !label_is_canonical("case_id", &expected.case_id)
        || !label_is_canonical("idempotency_key", &expected.idempotency_key)
        || expected
            .round_id
            .as_deref()
            .is_some_and(|round_id| !label_is_canonical("round_id", round_id))
        || expected.asset_definition_id
            != iroha_config::parameters::defaults::torii::sorafs_appeal_finance::asset_definition_id(
            )
        || expected.expires_at_ms == Some(0)
        || expected.evidence_hashes.len() > 128
    {
        return false;
    }
    let Ok(deposit_xor) = XorQuantity::try_from_quantity(expected.deposit_xor.clone()) else {
        return false;
    };
    if deposit_xor.is_zero() {
        return false;
    }
    expected.escrow_id
        == appeal_finance_deposit_escrow_id(
            (&expected.case_id, expected.round_id.as_deref()),
            (
                &expected.payer_account,
                &expected.destination_account,
                expected.release_authority_account.as_ref(),
            ),
            &expected.asset_definition_id,
            &expected.deposit_xor,
            expected.expires_at_ms,
            &expected.idempotency_key,
            &expected.evidence_hashes,
        )
}
fn appeal_finance_asset_definition_id(raw: &str) -> Result<AssetDefinitionId, String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err("SoraFS appeal finance `asset_definition_id` must not be empty".to_owned());
    }
    let asset_definition_id = AssetDefinitionId::parse_address_literal(trimmed)
        .map_err(|err| format!("invalid SoraFS appeal finance `asset_definition_id`: {err}"))?;
    if trimmed != asset_definition_id.to_string() {
        return Err(
            "SoraFS appeal finance `asset_definition_id` must be a canonical AssetDefinitionId"
                .to_owned(),
        );
    }
    Ok(asset_definition_id)
}
fn appeal_finance_deposit_amount(
    amount: XorQuantity,
) -> Result<iroha_primitives::numeric::Quantity, String> {
    if amount.as_quantity().is_zero() {
        return Err("SoraFS appeal finance `deposit_xor` must be positive".to_owned());
    }
    Ok(amount.into_quantity())
}
fn appeal_finance_evidence_hashes(
    raw_hashes: Option<&[String]>,
) -> Result<Vec<iroha_crypto::Hash>, String> {
    const MAX_EVIDENCE_HASHES: usize = 128;
    let Some(raw_hashes) = raw_hashes else {
        return Ok(Vec::new());
    };
    if raw_hashes.len() > MAX_EVIDENCE_HASHES {
        return Err(format!(
            "SoraFS appeal finance `evidence_hashes_hex` must contain at most {MAX_EVIDENCE_HASHES} entries"
        ));
    }
    raw_hashes
        .iter()
        .enumerate()
        .map(|(index, raw)| {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                return Err(format!(
                    "SoraFS appeal finance `evidence_hashes_hex[{index}]` must not be empty"
                ));
            }
            let hash = iroha_crypto::Hash::from_str(trimmed).map_err(|err| {
                format!("invalid SoraFS appeal finance `evidence_hashes_hex[{index}]`: {err}")
            })?;
            if trimmed != hash.to_string() {
                return Err(format!(
                    "SoraFS appeal finance `evidence_hashes_hex[{index}]` must be canonical lowercase hex"
                ));
            }
            Ok(hash)
        })
        .collect()
}
fn appeal_finance_escrow_id_from_hex(raw: &str) -> Result<EscrowId, String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err("SoraFS appeal finance `escrow_id_hex` must not be empty".to_owned());
    }
    let hash = iroha_crypto::Hash::from_str(trimmed)
        .map_err(|err| format!("invalid SoraFS appeal finance `escrow_id_hex`: {err}"))?;
    if trimmed != hash.to_string() {
        return Err(
            "SoraFS appeal finance `escrow_id_hex` must be canonical lowercase hex".to_owned(),
        );
    }
    Ok(EscrowId::new(hash))
}
fn appeal_finance_deposit_record_visible_to(
    record: &AssetEscrowRecord,
    account: &AccountId,
) -> bool {
    record.seller == *account
        || record.buyer.as_ref() == Some(account)
        || record.release_authority.as_ref() == Some(account)
}
fn appeal_finance_deposit_escrow_id(
    (case_id, round_id): (&str, Option<&str>),
    (payer_account, destination_account, release_authority_account): (
        &AccountId,
        &AccountId,
        Option<&AccountId>,
    ),
    asset_definition_id: &AssetDefinitionId,
    deposit_xor: &Quantity,
    expires_at_ms: Option<u64>,
    idempotency_key: &str,
    evidence_hashes: &[iroha_crypto::Hash],
) -> EscrowId {
    let mut material = String::new();
    material.push_str("sorafs-appeal-finance-deposit-v1\n");
    material.push_str("case_id=");
    material.push_str(case_id);
    material.push('\n');
    material.push_str("round_id=");
    material.push_str(round_id.unwrap_or_default());
    material.push('\n');
    material.push_str("payer_account=");
    material.push_str(&payer_account.to_string());
    material.push('\n');
    material.push_str("destination_account=");
    material.push_str(&destination_account.to_string());
    material.push('\n');
    material.push_str("release_authority_account=");
    if let Some(release_authority_account) = release_authority_account {
        material.push_str(&release_authority_account.to_string());
    }
    material.push('\n');
    material.push_str("asset_definition_id=");
    material.push_str(&asset_definition_id.to_string());
    material.push('\n');
    material.push_str("deposit_xor=");
    material.push_str(&deposit_xor.to_string());
    material.push('\n');
    material.push_str("expires_at_ms=");
    if let Some(expires_at_ms) = expires_at_ms {
        material.push_str(&expires_at_ms.to_string());
    }
    material.push('\n');
    material.push_str("idempotency_key=");
    material.push_str(idempotency_key);
    material.push('\n');
    material.push_str("evidence_hashes=");
    for hash in evidence_hashes {
        material.push_str(&hash.to_string());
        material.push('\n');
    }
    EscrowId::new(iroha_crypto::Hash::new(material))
}
