fn repair_finalized_query_error_response(error: QueryExecutionFail) -> Response {
    if matches!(error, QueryExecutionFail::Expired) {
        return json_error(
            StatusCode::CONFLICT,
            "SoraFS repair finalized cursor is stale; restart from the latest committed anchor",
        );
    }
    if matches!(
        &error,
        QueryExecutionFail::Find(FindError::SorafsRepairTask(_))
    ) {
        return json_error(StatusCode::NOT_FOUND, "SoraFS repair task was not found");
    }
    warn!(?error, "authoritative finalized SoraFS repair query failed");
    json_error(
        StatusCode::SERVICE_UNAVAILABLE,
        "authoritative finalized SoraFS repair state is unavailable",
    )
}
fn reputation_json_response(value: Value, etag: &str) -> Response {
    let mut response = JsonBody(value).into_response();
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static(SORAFS_PUBLIC_CACHE_CONTROL),
    );
    if let Ok(value) = HeaderValue::from_str(etag) {
        response.headers_mut().insert(ETAG, value);
    }
    response
}
fn reputation_not_modified_response(headers: &HeaderMap, etag: &str) -> Option<Response> {
    if !if_none_match_matches(headers, etag) {
        return None;
    }
    let mut response = Response::new(Body::empty());
    *response.status_mut() = StatusCode::NOT_MODIFIED;
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static(SORAFS_PUBLIC_CACHE_CONTROL),
    );
    if let Ok(value) = HeaderValue::from_str(etag) {
        response.headers_mut().insert(ETAG, value);
    }
    Some(response)
}

#[cfg(test)]
#[test]
fn public_conditional_etag_accepts_quoted_comma_validator() {
    let etag = "\"proof,abc\"";
    let mut headers = HeaderMap::new();
    headers.insert(
        IF_NONE_MATCH,
        HeaderValue::from_static("\"stale\", W/\"proof,abc\""),
    );

    let response = reputation_not_modified_response(&headers, etag)
        .expect("quoted comma validator must match");

    assert_eq!(response.status(), StatusCode::NOT_MODIFIED);
}

#[cfg(test)]
#[test]
fn public_conditional_etag_checks_validator_after_quoted_comma() {
    let etag = "\"proof:abc\"";
    let mut headers = HeaderMap::new();
    headers.insert(
        IF_NONE_MATCH,
        HeaderValue::from_static("\"stale,opaque\", \"proof:abc\""),
    );

    let response = reputation_not_modified_response(&headers, etag)
        .expect("later matching validator must be checked");

    assert_eq!(response.status(), StatusCode::NOT_MODIFIED);
}

#[cfg(test)]
#[test]
fn public_conditional_etag_accepts_obs_text_before_matching_validator() {
    let etag = "\"proof:abc\"";
    let mut headers = HeaderMap::new();
    headers.insert(
        IF_NONE_MATCH,
        HeaderValue::from_bytes(b"\"\x80\", \"proof:abc\"")
            .expect("obs-text is valid in an entity-tag"),
    );

    let response = reputation_not_modified_response(&headers, etag)
        .expect("obs-text validator must not hide a later match");

    assert_eq!(response.status(), StatusCode::NOT_MODIFIED);
}
fn authenticated_reputation_json_response(value: Value, etag: &str) -> Response {
    let mut response = JsonBody(value).into_response();
    match insert_authenticated_reputation_cache_headers(&mut response, etag) {
        Ok(()) => response,
        Err(response) => response,
    }
}
fn authenticated_reputation_not_modified_response(
    headers: &HeaderMap,
    etag: &str,
) -> Result<Option<Response>, Response> {
    let mut values = headers.get_all(IF_NONE_MATCH).iter();
    let Some(value) = values.next() else {
        return Ok(None);
    };
    if values.next().is_some() {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "If-None-Match must contain exactly one strong reputation ETag",
        ));
    }
    let raw = value.to_str().map_err(|_| {
        json_error(
            StatusCode::BAD_REQUEST,
            "If-None-Match must be visible ASCII",
        )
    })?;
    let bytes = raw.as_bytes();
    if bytes.len() != 66
        || bytes.first() != Some(&b'"')
        || bytes.last() != Some(&b'"')
        || !bytes[1..65]
            .iter()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(byte))
    {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "If-None-Match must be one quoted 64-character lowercase hexadecimal strong ETag",
        ));
    }
    if raw != etag {
        return Ok(None);
    }
    let mut response = Response::new(Body::empty());
    *response.status_mut() = StatusCode::NOT_MODIFIED;
    insert_authenticated_reputation_cache_headers(&mut response, etag)?;
    Ok(Some(response))
}
fn insert_authenticated_reputation_cache_headers(
    response: &mut Response,
    etag: &str,
) -> Result<(), Response> {
    let value = HeaderValue::from_str(etag).map_err(|_| {
        json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "failed to construct canonical reputation ETag",
        )
    })?;
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static(REPUTATION_CACHE_CONTROL),
    );
    response
        .headers_mut()
        .insert(VARY, HeaderValue::from_static(REPUTATION_CACHE_VARY));
    response.headers_mut().insert(ETAG, value);
    Ok(())
}
fn insert_reputation_stream_cache_headers(response: &mut Response) {
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static(REPUTATION_STREAM_CACHE_CONTROL),
    );
    response
        .headers_mut()
        .insert(VARY, HeaderValue::from_static(REPUTATION_CACHE_VARY));
}
