fn reputation_events_etag(
    since: Option<u64>,
    limit: usize,
    tip_sequence: u64,
    events: &[ReputationSnapshotEventV1],
) -> String {
    let since = since.unwrap_or(0).to_le_bytes();
    let limit = (limit as u64).to_le_bytes();
    let tip = tip_sequence.to_le_bytes();
    let count = (events.len() as u64).to_le_bytes();
    let last_sequence = events
        .last()
        .map_or(0, |event| event.sequence)
        .to_le_bytes();
    reputation_cache_etag(
        "events",
        &[
            since.as_ref(),
            limit.as_ref(),
            tip.as_ref(),
            count.as_ref(),
            last_sequence.as_ref(),
        ],
    )
}
fn reputation_cache_etag(kind: &str, parts: &[&[u8]]) -> String {
    let mut material = Vec::new();
    material.extend_from_slice(b"sorafs-reputation:");
    material.extend_from_slice(kind.as_bytes());
    for part in parts {
        material.extend_from_slice(&(part.len() as u64).to_le_bytes());
        material.extend_from_slice(part);
    }
    format!("\"{}\"", hex::encode(blake3_hash(&material).as_bytes()))
}
fn reputation_snapshot_summary_json(
    snapshot: &ReputationSnapshotV1,
    limit: usize,
) -> Result<Value, String> {
    let provider_count = snapshot.providers.len();
    let returned_provider_count = provider_count.min(limit);
    let providers = snapshot
        .providers
        .iter()
        .take(limit)
        .map(reputation_provider_json)
        .collect::<Result<Vec<_>, _>>()?;
    let mut root = Map::new();
    root.insert(
        "snapshot_id_hex".into(),
        Value::from(hex::encode(snapshot.snapshot_id)),
    );
    root.insert(
        "generated_at_unix".into(),
        Value::from(snapshot.generated_at_unix),
    );
    root.insert(
        "previous_snapshot_id_hex".into(),
        snapshot
            .previous_snapshot_id
            .map_or(Value::Null, |snapshot_id| {
                Value::from(hex::encode(snapshot_id))
            }),
    );
    root.insert(
        "merkle_root_hex".into(),
        Value::from(hex::encode(snapshot.merkle_root)),
    );
    root.insert("provider_count".into(), Value::from(provider_count as u64));
    root.insert(
        "returned_provider_count".into(),
        Value::from(returned_provider_count as u64),
    );
    root.insert("limit".into(), Value::from(limit as u64));
    root.insert(
        "truncated_providers".into(),
        Value::from(provider_count > limit),
    );
    root.insert(
        "alpha_bps".into(),
        Value::from(u64::from(snapshot.alpha_bps)),
    );
    root.insert(
        "current_score_weight_bps".into(),
        Value::from(u64::from(snapshot.current_score_weight_bps)),
    );
    root.insert(
        "weights".into(),
        json::to_value(&snapshot.weights)
            .map_err(|err| format!("failed to serialize reputation weights: {err}"))?,
    );
    root.insert("providers".into(), Value::Array(providers));
    Ok(Value::Object(root))
}
fn reputation_events_json(
    since: Option<u64>,
    limit: usize,
    events: &[ReputationSnapshotEventV1],
) -> Result<Value, String> {
    let mut root = Map::new();
    root.insert("since".into(), since.map_or(Value::Null, Value::from));
    root.insert("limit".into(), Value::from(limit as u64));
    root.insert("count".into(), Value::from(events.len() as u64));
    root.insert(
        "next_since".into(),
        events
            .last()
            .map_or(Value::Null, |event| Value::from(event.sequence)),
    );
    root.insert(
        "events".into(),
        Value::Array(
            events
                .iter()
                .map(reputation_event_json)
                .collect::<Result<Vec<_>, _>>()?,
        ),
    );
    Ok(Value::Object(root))
}
fn reputation_event_sse_stream(
    initial_frames: Vec<SseEvent>,
    reader: Arc<dyn ReputationCommittedReadApiV1>,
    cursor: u64,
) -> impl futures::Stream<Item = Result<SseEvent, io::Error>> {
    let source = Box::pin(reputation_committed_event_stream(reader, cursor));
    stream::unfold(
        (
            initial_frames.into_iter().collect::<VecDeque<_>>(),
            source,
            false,
        ),
        |(mut initial_frames, mut source, terminated)| async move {
            if terminated {
                return None;
            }
            if let Some(event) = initial_frames.pop_front() {
                return Some((Ok(event), (initial_frames, source, false)));
            }
            let item = source.next().await?;
            let event = match item {
                ReputationCommittedStreamItem::Event(event) => {
                    reputation_snapshot_sse_event(&event).map_err(io::Error::other)
                }
                ReputationCommittedStreamItem::Lagged(skipped) => Ok(SseEvent::default()
                    .event("lagged")
                    .data(skipped.to_string())),
                ReputationCommittedStreamItem::ReaderFailed => {
                    Err(io::Error::other(REPUTATION_LIVE_READER_ERROR))
                }
            };
            let terminated = event.is_err();
            Some((event, (initial_frames, source, terminated)))
        },
    )
}
struct PreparedReputationSseBacklog {
    frames: Vec<SseEvent>,
    cursor: u64,
}
fn prepare_reputation_sse_backlog(
    initial_events: &[ReputationSnapshotEventV1],
    since: u64,
) -> Result<PreparedReputationSseBacklog, String> {
    let mut frames = Vec::with_capacity(initial_events.len().saturating_add(1));
    if let Some(skipped) = reputation_initial_lag(initial_events, since) {
        frames.push(
            SseEvent::default()
                .event("lagged")
                .data(skipped.to_string()),
        );
    }
    for event in initial_events {
        frames.push(reputation_snapshot_sse_event(event)?);
    }
    let cursor = initial_events.last().map_or(since, |event| event.sequence);
    Ok(PreparedReputationSseBacklog { frames, cursor })
}
struct PreparedReputationWebSocketBacklog {
    frames: Vec<String>,
    cursor: u64,
}
fn prepare_reputation_websocket_backlog(
    initial_events: &[ReputationSnapshotEventV1],
    since: u64,
) -> Result<PreparedReputationWebSocketBacklog, String> {
    let mut frames = Vec::with_capacity(initial_events.len().saturating_add(1));
    if let Some(skipped) = reputation_initial_lag(initial_events, since) {
        frames.push(reputation_lagged_websocket_frame(skipped)?);
    }
    for event in initial_events {
        frames.push(reputation_snapshot_websocket_frame(event)?);
    }
    let cursor = initial_events.last().map_or(since, |event| event.sequence);
    Ok(PreparedReputationWebSocketBacklog { frames, cursor })
}
enum ReputationCommittedStreamItem {
    Event(ReputationSnapshotEventV1),
    Lagged(u64),
    ReaderFailed,
}
fn reputation_committed_event_stream(
    reader: Arc<dyn ReputationCommittedReadApiV1>,
    cursor: u64,
) -> impl futures::Stream<Item = ReputationCommittedStreamItem> {
    struct ReputationCommittedStreamState {
        pending: VecDeque<ReputationSnapshotEventV1>,
        reader: Arc<dyn ReputationCommittedReadApiV1>,
        cursor: u64,
        failed: bool,
    }
    stream::unfold(
        ReputationCommittedStreamState {
            pending: VecDeque::new(),
            reader,
            cursor,
            failed: false,
        },
        |mut state| async move {
            loop {
                if state.failed {
                    return None;
                }
                if let Some(event) = state.pending.pop_front() {
                    state.cursor = event.sequence;
                    return Some((ReputationCommittedStreamItem::Event(event), state));
                }
                tokio::time::sleep(REPUTATION_COMMITTED_POLL_INTERVAL).await;
                let retained_events = match state.reader.committed_events_after(state.cursor) {
                    Ok(events) => events,
                    Err(_) => {
                        state.failed = true;
                        return Some((ReputationCommittedStreamItem::ReaderFailed, state));
                    }
                };
                let mut events = retained_events
                    .into_iter()
                    .filter(|event| event.sequence > state.cursor);
                let Some(first) = events.next() else {
                    continue;
                };
                let skipped = first
                    .sequence
                    .saturating_sub(state.cursor.saturating_add(1));
                state.pending.push_back(first);
                state.pending.extend(events);
                if skipped != 0 {
                    return Some((ReputationCommittedStreamItem::Lagged(skipped), state));
                }
                if let Some(event) = state.pending.pop_front() {
                    state.cursor = event.sequence;
                    return Some((ReputationCommittedStreamItem::Event(event), state));
                }
            }
        },
    )
}
fn reputation_initial_lag(initial_events: &[ReputationSnapshotEventV1], since: u64) -> Option<u64> {
    initial_events.first().and_then(|first| {
        let skipped = first.sequence.saturating_sub(since.saturating_add(1));
        (skipped != 0).then_some(skipped)
    })
}
async fn reputation_event_websocket_stream(
    ws: WebSocket,
    initial_frames: Vec<String>,
    committed_reader: Arc<dyn ReputationCommittedReadApiV1>,
    cursor: u64,
) -> Result<(), String> {
    let (mut sender, mut socket_reader) = ws.split();
    for text in initial_frames {
        sender
            .send(WsMessage::Text(Utf8Bytes::from(text)))
            .await
            .map_err(|err| format!("failed to send reputation initial frame: {err}"))?;
    }
    let event_stream = reputation_committed_event_stream(committed_reader, cursor);
    tokio::pin!(event_stream);
    loop {
        tokio::select! {
            item = event_stream.next() => {
                match item {
                    Some(item) => send_reputation_websocket_stream_item(&mut sender, item).await?,
                    None => return Ok(()),
                }
            }
            message = socket_reader.next() => {
                match message {
                    Some(Ok(WsMessage::Close(_))) | None => return Ok(()),
                    Some(Ok(WsMessage::Ping(payload))) => {
                        sender
                            .send(WsMessage::Pong(payload))
                            .await
                            .map_err(|err| format!("failed to send reputation pong frame: {err}"))?;
                    }
                    Some(Ok(WsMessage::Text(_)
                        | WsMessage::Binary(_)
                        | WsMessage::Pong(_))) => {}
                    Some(Err(err)) => {
                        return Err(format!("failed to receive reputation WebSocket frame: {err}"));
                    }
                }
            }
        }
    }
}
async fn send_reputation_websocket_stream_item<S>(
    sender: &mut S,
    item: ReputationCommittedStreamItem,
) -> Result<(), String>
where
    S: futures::Sink<WsMessage> + Unpin + Send,
    S::Error: std::fmt::Display,
{
    let (text, label) = match item {
        ReputationCommittedStreamItem::Event(event) => {
            let text = match reputation_snapshot_websocket_frame(&event) {
                Ok(text) => text,
                Err(err) => return close_reputation_websocket_on_failure(sender, err).await,
            };
            (text, "live")
        }
        ReputationCommittedStreamItem::Lagged(skipped) => {
            let text = match reputation_lagged_websocket_frame(skipped) {
                Ok(text) => text,
                Err(err) => return close_reputation_websocket_on_failure(sender, err).await,
            };
            (text, "lag")
        }
        ReputationCommittedStreamItem::ReaderFailed => {
            return close_reputation_websocket_on_failure(
                sender,
                REPUTATION_LIVE_READER_ERROR.to_owned(),
            )
            .await;
        }
    };
    sender
        .send(WsMessage::Text(Utf8Bytes::from(text)))
        .await
        .map_err(|err| format!("failed to send reputation {label} frame: {err}"))
}
async fn close_reputation_websocket_on_failure<S>(
    sender: &mut S,
    error: String,
) -> Result<(), String>
where
    S: futures::Sink<WsMessage> + Unpin + Send,
    S::Error: std::fmt::Display,
{
    sender
        .send(reputation_websocket_failure_close_message())
        .await
        .map_err(|close_error| {
            format!("{error}; failed to send reputation WebSocket 1011 close: {close_error}")
        })?;
    Err(error)
}
fn reputation_websocket_failure_close_message() -> WsMessage {
    WsMessage::Close(Some(CloseFrame {
        code: close_code::ERROR,
        reason: Utf8Bytes::from_static(REPUTATION_WEBSOCKET_FAILURE_CLOSE_REASON),
    }))
}
fn reputation_snapshot_sse_event(event: &ReputationSnapshotEventV1) -> Result<SseEvent, String> {
    let data = reputation_event_json(event).and_then(|value| {
        json::to_string(&value)
            .map_err(|err| format!("failed to serialize reputation event: {err}"))
    })?;
    Ok(SseEvent::default()
        .event("reputation_snapshot")
        .id(event.sequence.to_string())
        .data(data))
}
fn reputation_snapshot_websocket_frame(
    event: &ReputationSnapshotEventV1,
) -> Result<String, String> {
    let data = reputation_event_json(event)?;
    let mut frame = Map::new();
    frame.insert("event".into(), Value::from("reputation_snapshot"));
    frame.insert("data".into(), data);
    json::to_string(&Value::Object(frame))
        .map_err(|err| format!("failed to serialize reputation WebSocket event frame: {err}"))
}
fn reputation_lagged_websocket_frame(skipped: u64) -> Result<String, String> {
    let mut frame = Map::new();
    frame.insert("event".into(), Value::from("lagged"));
    frame.insert("skipped".into(), Value::from(skipped));
    json::to_string(&Value::Object(frame))
        .map_err(|err| format!("failed to serialize reputation WebSocket lag frame: {err}"))
}
fn reputation_event_json(event: &ReputationSnapshotEventV1) -> Result<Value, String> {
    event
        .validate()
        .map_err(|err| format!("invalid reputation event: {err}"))?;
    let mut map = Map::new();
    map.insert("version".into(), Value::from(u64::from(event.version)));
    map.insert("sequence".into(), Value::from(event.sequence));
    map.insert(
        "snapshot_id_hex".into(),
        Value::from(hex::encode(event.snapshot_id)),
    );
    map.insert(
        "generated_at_unix".into(),
        Value::from(event.generated_at_unix),
    );
    map.insert(
        "merkle_root_hex".into(),
        Value::from(hex::encode(event.merkle_root)),
    );
    map.insert(
        "provider_count".into(),
        Value::from(u64::from(event.provider_count)),
    );
    map.insert(
        "previous_snapshot_id_hex".into(),
        event
            .previous_snapshot_id
            .map_or(Value::Null, |snapshot_id| {
                Value::from(hex::encode(snapshot_id))
            }),
    );
    Ok(Value::Object(map))
}
fn reputation_weights_json(snapshot: &ReputationSnapshotV1) -> Result<Value, String> {
    let mut root = Map::new();
    root.insert(
        "snapshot_id_hex".into(),
        Value::from(hex::encode(snapshot.snapshot_id)),
    );
    root.insert(
        "generated_at_unix".into(),
        Value::from(snapshot.generated_at_unix),
    );
    root.insert(
        "alpha_bps".into(),
        Value::from(u64::from(snapshot.alpha_bps)),
    );
    root.insert(
        "current_score_weight_bps".into(),
        Value::from(u64::from(snapshot.current_score_weight_bps)),
    );
    root.insert(
        "weights".into(),
        json::to_value(&snapshot.weights)
            .map_err(|err| format!("failed to serialize reputation weights: {err}"))?,
    );
    Ok(Value::Object(root))
}
fn reputation_provider_response_json(
    snapshot: &ReputationSnapshotV1,
    provider: &ProviderReputationV1,
    proof: &ReputationMerkleProofV1,
) -> Result<Value, String> {
    let mut root = Map::new();
    root.insert(
        "snapshot_id_hex".into(),
        Value::from(hex::encode(snapshot.snapshot_id)),
    );
    root.insert(
        "generated_at_unix".into(),
        Value::from(snapshot.generated_at_unix),
    );
    root.insert(
        "merkle_root_hex".into(),
        Value::from(hex::encode(snapshot.merkle_root)),
    );
    root.insert("provider".into(), reputation_provider_json(provider)?);
    root.insert("proof".into(), reputation_proof_json(proof));
    Ok(Value::Object(root))
}
fn reputation_provider_json(provider: &ProviderReputationV1) -> Result<Value, String> {
    let mut map = Map::new();
    map.insert(
        "provider_id".into(),
        Value::from(provider.provider_id.clone()),
    );
    map.insert(
        "score_bps".into(),
        Value::from(u64::from(provider.score_bps)),
    );
    map.insert(
        "degradation_flags".into(),
        json::to_value(&provider.degradation_flags)
            .map_err(|err| format!("failed to serialize reputation flags: {err}"))?,
    );
    map.insert(
        "raw_metrics".into(),
        json::to_value(&provider.raw_metrics)
            .map_err(|err| format!("failed to serialize reputation metrics: {err}"))?,
    );
    map.insert(
        "raw_metrics_hash_hex".into(),
        Value::from(hex::encode(provider.raw_metrics_hash)),
    );
    Ok(Value::Object(map))
}
fn reputation_proof_json(proof: &ReputationMerkleProofV1) -> Value {
    let mut map = Map::new();
    map.insert("provider_id".into(), Value::from(proof.provider_id.clone()));
    map.insert(
        "leaf_index".into(),
        Value::from(u64::from(proof.leaf_index)),
    );
    map.insert(
        "leaf_count".into(),
        Value::from(u64::from(proof.leaf_count)),
    );
    map.insert(
        "siblings_hex".into(),
        Value::Array(
            proof
                .siblings
                .iter()
                .map(|sibling| Value::from(hex::encode(sibling)))
                .collect(),
        ),
    );
    Value::Object(map)
}
pub(crate) async fn handle_post_sorafs_provider_advert(
    State(state): State<SharedAppState>,
    body: Bytes,
) -> Response {
    let Some(cache) = state.sorafs_cache.clone() else {
        return feature_disabled("sorafs discovery API is not enabled on this node");
    };
    let telemetry = state.telemetry.clone();
    let advert = match decode_provider_advert_v1(body.as_ref()) {
        Ok(value) => value,
        Err(err) => {
            warn!(?err, "failed to decode provider advert payload");
            return json_error(
                StatusCode::BAD_REQUEST,
                format!("invalid provider advert payload: {err}"),
            );
        }
    };
    let now = match provider_advert_unix_now() {
        Ok(now) => now,
        Err(response) => return response,
    };
    let advert_profile = advert.body.profile_id.clone();
    let advert_provider_id = advert.body.provider_id;
    let validation_policy = {
        let guard = cache.read().await;
        guard.validation_policy()
    };
    let prepared = match validation_policy.prepare(advert, now) {
        Ok(prepared) => prepared,
        Err(error) => {
            return provider_advert_error_response(
                &state,
                &telemetry,
                error,
                &advert_profile,
                &advert_provider_id,
            );
        }
    };
    let commit_now = match provider_advert_unix_now() {
        Ok(now) => now,
        Err(response) => return response,
    };
    let mut guard = cache.write().await;
    match guard.commit_prepared(prepared, commit_now) {
        Ok(AdvertIngestResult { outcome, warnings }) => {
            if !warnings.is_empty() {
                warn!(
                    ?warnings,
                    "provider advert ingested with downgrade warnings"
                );
                let telemetry = telemetry.clone();
                for warning in &warnings {
                    telemetry.with_metrics(|tel| {
                        tel.inc_torii_sorafs_admission("warn", warning.telemetry_reason())
                    });
                }
            }
            let response = match outcome {
                AdvertIngest::Stored { fingerprint } => {
                    debug!("stored new provider advert");
                    telemetry
                        .with_metrics(|tel| tel.inc_torii_sorafs_admission("accepted", "stored"));
                    advert_ingest_response("stored", &fingerprint, &warnings)
                }
                AdvertIngest::Replaced { fingerprint } => {
                    debug!("replaced provider advert");
                    telemetry
                        .with_metrics(|tel| tel.inc_torii_sorafs_admission("accepted", "replaced"));
                    advert_ingest_response("replaced", &fingerprint, &warnings)
                }
                AdvertIngest::Duplicate { fingerprint } => {
                    debug!("duplicate provider advert ignored");
                    telemetry.with_metrics(|tel| {
                        tel.inc_torii_sorafs_admission("accepted", "duplicate")
                    });
                    advert_ingest_response("duplicate", &fingerprint, &warnings)
                }
            };
            record_range_capability_metrics(&guard, &telemetry);
            response
        }
        Err(error) => provider_advert_error_response(
            &state,
            &telemetry,
            error,
            &advert_profile,
            &advert_provider_id,
        ),
    }
}
fn provider_advert_unix_now() -> Result<u64, Response> {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .map_err(|error| {
            error!(?error, "system clock error while ingesting provider advert");
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "system time error while ingesting advert",
            )
        })
}
fn provider_advert_error_response(
    state: &SharedAppState,
    telemetry: &MaybeTelemetry,
    error: AdvertError,
    advert_profile: &str,
    advert_provider_id: &[u8; 32],
) -> Response {
    warn!(?error, "failed to ingest provider advert");
    let reason = admission_error_reason(&error);
    telemetry.with_metrics(|metrics| metrics.inc_torii_sorafs_admission("rejected", reason));
    match error {
        AdvertError::UnknownCapabilities { capabilities } => {
            let capability_labels = capabilities
                .into_iter()
                .map(|capability| Value::from(capability_name(capability).to_string()))
                .collect();
            gateway_refusal_response(
                state,
                StatusCode::PRECONDITION_REQUIRED,
                "unsupported_capability",
                format!(
                    "provider advert declares unsupported capabilities for profile {advert_profile}"
                ),
                Some(advert_profile),
                Some(advert_provider_id),
                TELEMETRY_ENDPOINT_PROVIDER_ADVERT,
                [("capabilities", Value::Array(capability_labels))],
            )
        }
        other => json_error(StatusCode::BAD_REQUEST, format_advert_error(other)),
    }
}
pub(crate) async fn handle_get_sorafs_capacity_state(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs capacity registry API is not enabled on this node");
    }
    let query = match CapacityStateReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let permit = match crate::acquire_query_admission(state.as_ref(), true).await {
        Ok(permit) => permit,
        Err(error) => return error.into_response(),
    };
    let projection = crate::panic_recovery::join_recoverable(
        crate::panic_recovery::spawn_blocking_recoverable(move || {
            let _permit = permit;
            let world = state.state.world_view();
            let snapshot =
                collect_snapshot(&world, limit).map_err(|error| format!("registry: {error}"))?;
            snapshot_to_json(snapshot, limit).map_err(|error| format!("json: {error}"))
        }),
    )
    .await;
    match projection {
        Ok(Ok(value)) => JsonBody(value).into_response(),
        Ok(Err(error)) => {
            error!(%error, "failed to project capacity registry snapshot");
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to project capacity registry snapshot",
            )
        }
        Err(error) => {
            error!(?error, "capacity registry projection worker failed");
            json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "capacity registry projection worker is unavailable",
            )
        }
    }
}
fn finalized_capacity_identity(
    state: &SharedAppState,
) -> Option<sorafs_node::capacity::CapacityFinalizedCursorV1> {
    let block_hash = state.state.latest_block_hash_fast()?;
    let height = u64::try_from(state.state.committed_height()).ok()?;
    let mut block_hash_bytes = [0_u8; 32];
    block_hash_bytes.copy_from_slice(block_hash.as_ref().as_ref());
    Some(sorafs_node::capacity::CapacityFinalizedCursorV1 {
        height,
        block_hash: block_hash_bytes,
    })
}
fn reconcile_sorafs_capacity_projection(
    state: &SharedAppState,
    mode: sorafs_node::capacity::CapacityReconcileModeV1,
) -> Result<sorafs_node::capacity::CapacityReconciliationOutcomeV1, String> {
    const SNAPSHOT_ATTEMPTS: usize = 3;
    let provider_id = state.sorafs_node.capacity_provider_id().ok_or_else(|| {
        "enabled SoraFS storage has no configured finalized capacity provider identity".to_owned()
    })?;
    for _ in 0..SNAPSHOT_ATTEMPTS {
        let before = finalized_capacity_identity(state).ok_or_else(|| {
            "no finalized block is available for capacity reconciliation".to_owned()
        })?;
        let world = state.state.world_view();
        let declaration = world.capacity_declarations().get(&provider_id).cloned();
        let replication_orders = world
            .replication_orders()
            .iter()
            .filter(|(_, record)| matches!(record.status, ReplicationOrderStatus::Pending))
            .map(|(_, record)| record.clone())
            .collect::<Vec<_>>();
        drop(world);
        let after = finalized_capacity_identity(state).ok_or_else(|| {
            "finalized block disappeared during capacity reconciliation".to_owned()
        })?;
        if before != after {
            continue;
        }
        return state
            .sorafs_node
            .reconcile_finalized_capacity(
                before,
                mode,
                provider_id,
                declaration.as_ref(),
                &replication_orders,
            )
            .map_err(|error| error.to_string());
    }
    Err("finalized capacity snapshot changed during every bounded collection attempt".to_owned())
}
/// Supervise the finalized-ledger projection consumed by the embedded provider scheduler.
///
/// # Errors
///
/// Returns an error when an active provider cannot read its durable finalized cursor.
pub(crate) fn spawn_sorafs_capacity_reconciler_worker(
    state: SharedAppState,
    shutdown_signal: iroha_futures::supervisor::ShutdownSignal,
) -> Result<Option<tokio::task::JoinHandle<crate::ToriiCriticalWorkerExit>>, String> {
    if !state.sorafs_node.is_enabled() {
        return Ok(None);
    }
    if state.sorafs_node.capacity_provider_id().is_none() {
        iroha_logger::debug!(
            "SoraFS capacity reconciler is inactive because this storage node has no configured provider identity"
        );
        return Ok(None);
    }
    let initial_mode = match state.sorafs_node.capacity_finalized_cursor() {
        Ok(Some(_)) => sorafs_node::capacity::CapacityReconcileModeV1::Advance,
        Ok(None) => sorafs_node::capacity::CapacityReconcileModeV1::FullRebuild,
        Err(error) => {
            return Err(format!(
                "failed to read the durable SoraFS capacity finalized cursor: {error}"
            ));
        }
    };
    Ok(Some(tokio::spawn(async move {
        const RECONCILIATION_INTERVAL_SECS: u64 = 1;
        let mut mode = initial_mode;
        let mut ticker = tokio::time::interval(Duration::from_secs(RECONCILIATION_INTERVAL_SECS));
        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            tokio::select! {
                biased;
                _ = shutdown_signal.receive() => {
                    return crate::ToriiCriticalWorkerExit::StoppedByShutdown;
                }
                _ = ticker.tick() => {
                    if shutdown_signal.is_sent() {
                        return crate::ToriiCriticalWorkerExit::StoppedByShutdown;
                    }
                    let worker_state = state.clone();
                    let reconciliation = crate::panic_recovery::join_recoverable(
                        crate::panic_recovery::spawn_blocking_recoverable(move || {
                            reconcile_sorafs_capacity_projection(&worker_state, mode)
                        }),
                    )
                    .await;
                    match reconciliation {
                        Ok(Ok(outcome)) => {
                            mode = sorafs_node::capacity::CapacityReconcileModeV1::Advance;
                            if outcome.changed {
                                iroha_logger::info!(
                                    provider_id = %hex::encode(outcome.provider_id.as_bytes()),
                                    finalized_height = outcome.finalized_cursor.height,
                                    finalized_block_hash = %hex::encode(outcome.finalized_cursor.block_hash),
                                    pending_order_count = outcome.pending_order_count,
                                    "reconciled SoraFS capacity scheduler from finalized ledger state"
                                );
                            }
                        }
                        Ok(Err(error)) => {
                            iroha_logger::error!(
                                %error,
                                mode = ?mode,
                                "failed closed while reconciling SoraFS capacity scheduler from finalized ledger state"
                            );
                        }
                        Err(error) => {
                            iroha_logger::error!(
                                ?error,
                                mode = ?mode,
                                "SoraFS capacity reconciliation blocking worker failed"
                            );
                            return crate::ToriiCriticalWorkerExit::UnexpectedExit;
                        }
                    }
                }
            }
        }
    })))
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_storage_state(
    State(state): State<SharedAppState>,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return storage_disabled_response();
    }
    let schedulers = state.sorafs_node.schedulers();
    let telemetry = schedulers.telemetry_snapshot();
    let utilisation = schedulers.utilisation_snapshot();
    let response = StorageStateResponseDto {
        bytes_used: telemetry.bytes_used,
        bytes_capacity: telemetry.bytes_capacity,
        provider_ingest_inflight: telemetry.provider_ingest_inflight as u64,
        fetch_inflight: telemetry.fetch_inflight as u64,
        fetch_bytes_per_sec: telemetry.fetch_bytes_per_sec,
        por_inflight: telemetry.por_inflight as u64,
        por_samples_success_total: telemetry.por_samples_success,
        por_samples_failed_total: telemetry.por_samples_failed,
        fetch_utilisation_bps: utilisation.fetch_utilisation_bps,
        pin_queue_utilisation_bps: utilisation.pin_queue_utilisation_bps,
        por_utilisation_bps: utilisation.por_utilisation_bps,
    };
    record_storage_metrics(&state);
    let value = match norito::json::to_value(&response) {
        Ok(value) => value,
        Err(err) => {
            error!(?err, "failed to encode storage scheduler state");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode storage scheduler state",
            );
        }
    };
    JsonBody(value).into_response()
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_por_ingestion(
    State(state): State<SharedAppState>,
    Path(manifest_hex): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return storage_disabled_response();
    }
    let query = match PorIngestionReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let manifest_digest = match parse_hex_fixed::<32>(&manifest_hex, "manifest_digest_hex") {
        Ok(bytes) => bytes,
        Err(err) => {
            return json_error(StatusCode::BAD_REQUEST, &err);
        }
    };
    let status = match state.sorafs_node.por_ingestion_status(&manifest_digest) {
        Ok(status) => status,
        Err(NodeStorageError::Disabled) => return storage_disabled_response(),
        Err(NodeStorageError::Storage(err)) => {
            return node_storage_error_response(NodeStorageError::Storage(err));
        }
        Err(NodeStorageError::Scheduler(err)) => {
            return node_storage_error_response(NodeStorageError::Scheduler(err));
        }
    };
    if status.providers.is_empty() {
        return json_error(
            StatusCode::NOT_FOUND,
            "no PoR ingestion data recorded for the requested manifest",
        );
    }
    record_storage_metrics(&state);
    let provider_count = status.providers.len();
    let providers = status
        .providers
        .into_iter()
        .take(limit)
        .map(|entry| PorIngestionProviderStatusDto {
            provider_id_hex: hex::encode(entry.provider_id),
            pending_challenges: entry.pending_challenges,
            oldest_epoch_id: entry.oldest_epoch_id,
            oldest_response_deadline_unix: entry.oldest_response_deadline_unix,
            last_success_unix: entry.last_success_unix,
            last_failure_unix: entry.last_failure_unix,
            failures_total: entry.failures_total,
            consecutive_failures: entry.consecutive_failures,
        })
        .collect::<Vec<_>>();
    let returned_provider_count = providers.len();
    let response = PorIngestionStatusResponseDto {
        manifest_digest_hex: hex::encode(status.manifest_digest),
        provider_count: provider_count as u64,
        returned_provider_count: returned_provider_count as u64,
        limit: limit as u64,
        truncated_providers: provider_count > limit,
        providers,
    };
    let value = match norito::json::to_value(&response) {
        Ok(value) => value,
        Err(err) => {
            error!(?err, "failed to encode PoR ingestion status response");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode PoR ingestion status response",
            );
        }
    };
    JsonBody(value).into_response()
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_storage_manifest(
    State(state): State<SharedAppState>,
    Path(manifest_id_hex): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return storage_disabled_response();
    }
    let query = match StorageMetadataReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let storage_manifest_id = match resolve_manifest_storage_id(&state, &manifest_id_hex) {
        Ok(manifest_id) => manifest_id,
        Err(response) => return response,
    };
    let stored = match state.sorafs_node.manifest_metadata(&storage_manifest_id) {
        Ok(manifest) => manifest,
        Err(err) => return node_storage_error_response(err),
    };
    if let Err(response) = enforce_chunker_support_gateway(
        &state,
        stored.chunk_profile_handle(),
        TELEMETRY_ENDPOINT_MANIFEST,
    ) {
        return response;
    }
    match sorafs_heavy_blocking_task(&state, "SoraFS manifest read", move || {
        let manifest_bytes = stored
            .load_manifest_bytes()
            .map_err(storage_backend_error)?;
        if manifest_bytes.len() > MAX_LOCAL_MANIFEST_RESPONSE_BYTES {
            return Err(json_error(
                StatusCode::PAYLOAD_TOO_LARGE,
                "stored manifest exceeds the local readback byte limit",
            ));
        }
        let manifest_b64 =
            base64::engine::general_purpose::STANDARD.encode(manifest_bytes.as_slice());
        let file_count = stored.files().len();
        let offset = query
            .offset
            .map(|value| usize::try_from(value).unwrap_or(usize::MAX))
            .unwrap_or(0)
            .min(file_count);
        let limit = query
            .limit
            .map(|limit| normalize_limit(Some(limit)))
            .unwrap_or_else(|| file_count.saturating_sub(offset));
        let files = stored
            .files()
            .iter()
            .skip(offset)
            .take(limit)
            .map(storage_stored_file_dto)
            .collect::<Vec<_>>();
        let returned_file_count = files.len();
        let returned_end = offset.saturating_add(returned_file_count);
        let response = StorageManifestResponseDto {
            manifest_id_hex,
            manifest_b64,
            manifest_digest_hex: hex::encode(stored.manifest_digest()),
            payload_digest_hex: hex::encode(stored.payload_digest()),
            content_length: stored.content_length(),
            chunk_count: stored.chunk_count() as u64,
            chunk_profile_handle: stored.chunk_profile_handle().to_owned(),
            stored_at_unix_secs: stored.stored_at_unix_secs(),
            files,
        };
        let mut value = norito::json::to_value(&response).map_err(|err| {
            error!(?err, "failed to encode manifest response");
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to encode manifest response",
            )
        })?;
        if let Value::Object(ref mut obj) = value {
            obj.insert("file_count".into(), Value::from(file_count as u64));
            obj.insert(
                "returned_file_count".into(),
                Value::from(returned_file_count as u64),
            );
            obj.insert("limit".into(), Value::from(limit as u64));
            obj.insert("offset".into(), Value::from(offset as u64));
            obj.insert(
                "truncated_files".into(),
                Value::from(returned_end < file_count),
            );
        }
        Ok(JsonBody(value).into_response())
    })
    .await
    {
        Ok(response) | Err(response) => response,
    }
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_storage_plan(
    State(state): State<SharedAppState>,
    Path(manifest_id_hex): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return storage_disabled_response();
    }
    let query = match StorageMetadataReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let storage_manifest_id = match resolve_manifest_storage_id(&state, &manifest_id_hex) {
        Ok(manifest_id) => manifest_id,
        Err(response) => return response,
    };
    let stored = match state.sorafs_node.manifest_metadata(&storage_manifest_id) {
        Ok(manifest) => manifest,
        Err(err) => return node_storage_error_response(err),
    };
    if let Err(response) = enforce_chunker_support_gateway(
        &state,
        stored.chunk_profile_handle(),
        TELEMETRY_ENDPOINT_PLAN,
    ) {
        return response;
    }
    match sorafs_heavy_blocking_task(&state, "SoraFS plan read", move || {
        let manifest_v1 = stored.load_manifest().map_err(storage_backend_error)?;
        let chunk_profile = match chunk_profile_for_manifest(&manifest_v1) {
            Ok(profile) => profile,
            Err(err) => return Err(err.into_response()),
        };
        let plan = stored
            .try_to_car_plan(chunk_profile)
            .map_err(storage_backend_error)?;
        let specs = plan.try_chunk_fetch_specs().map_err(|err| {
            error!(
                ?err,
                manifest = manifest_id_hex,
                "failed to derive bounded chunk fetch plan"
            );
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to derive bounded chunk plan",
            )
        })?;
        let file_count = stored.files().len();
        let offset = query
            .offset
            .map(|value| usize::try_from(value).unwrap_or(usize::MAX))
            .unwrap_or(0);
        let file_offset = offset.min(file_count);
        let files = stored
            .files()
            .iter()
            .skip(file_offset)
            .take(limit)
            .map(file_listing_entry_json)
            .collect::<Vec<_>>();
        let returned_file_count = files.len();
        let chunk_count = specs.len();
        let chunk_offset = offset.min(chunk_count);
        let chunk_digests = specs
            .iter()
            .skip(chunk_offset)
            .take(limit)
            .map(|spec| Value::String(hex::encode(spec.digest)))
            .collect::<Vec<_>>();
        let chunks = specs
            .iter()
            .skip(chunk_offset)
            .take(limit)
            .map(chunk_fetch_spec_json)
            .collect::<Vec<_>>();
        let mut plan_map = Map::new();
        plan_map.insert("chunk_count".into(), Value::from(chunk_count as u64));
        plan_map.insert("offset".into(), Value::from(offset as u64));
        plan_map.insert(
            "returned_chunk_count".into(),
            Value::from(chunks.len() as u64),
        );
        plan_map.insert("limit".into(), Value::from(limit as u64));
        plan_map.insert(
            "truncated_chunks".into(),
            Value::from(chunk_offset.saturating_add(chunks.len()) < chunk_count),
        );
        plan_map.insert("content_length".into(), Value::from(plan.content_length));
        plan_map.insert(
            "payload_digest_blake3".into(),
            Value::String(hex::encode(plan.payload_digest.as_bytes())),
        );
        plan_map.insert(
            "chunk_profile_handle".into(),
            Value::String(stored.chunk_profile_handle().to_owned()),
        );
        plan_map.insert("file_count".into(), Value::from(file_count as u64));
        plan_map.insert(
            "returned_file_count".into(),
            Value::from(returned_file_count as u64),
        );
        plan_map.insert(
            "truncated_files".into(),
            Value::from(file_offset.saturating_add(returned_file_count) < file_count),
        );
        plan_map.insert("files".into(), Value::Array(files));
        plan_map.insert("chunk_digest_count".into(), Value::from(chunk_count as u64));
        plan_map.insert(
            "returned_chunk_digest_count".into(),
            Value::from(chunk_digests.len() as u64),
        );
        plan_map.insert(
            "truncated_chunk_digests".into(),
            Value::from(chunk_offset.saturating_add(chunk_digests.len()) < chunk_count),
        );
        plan_map.insert("chunk_digests_blake3".into(), Value::Array(chunk_digests));
        plan_map.insert("chunks".into(), Value::Array(chunks));
        let mut root = Map::new();
        root.insert("manifest_id_hex".into(), Value::String(manifest_id_hex));
        root.insert("plan".into(), Value::Object(plan_map));
        Ok(JsonBody(Value::Object(root)).into_response())
    })
    .await
    {
        Ok(response) | Err(response) => response,
    }
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_pin_registry(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    accept: Option<ExtractAccept>,
) -> Response {
    let query = match PinListQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let format = match crate::utils::negotiate_response_format(accept.as_ref().map(|hdr| &hdr.0)) {
        Ok(format) => format,
        Err(err) => return err.into_response(),
    };
    let expected_finalized_cursor = match query.expected_finalized_cursor() {
        Ok(cursor) => cursor,
        Err(response) => return response,
    };
    let page = match FindSorafsPinManifests::new(
        expected_finalized_cursor,
        query.status,
        query.after_digest(),
        query.limit.unwrap_or(DEFAULT_LIST_LIMIT as u32),
        query
            .max_bytes
            .unwrap_or(PIN_MANIFEST_QUERY_MAX_PAGE_BYTES_V1),
    )
    .execute(&state.state.query_view())
    {
        Ok(page) => page,
        Err(error) => return pin_manifest_query_error_response(error),
    };
    let mut response = match format {
        crate::utils::ResponseFormat::Json => (StatusCode::OK, JsonBody(page)).into_response(),
        crate::utils::ResponseFormat::Norito => {
            let bytes = match norito::to_bytes(&page) {
                Ok(bytes) => bytes,
                Err(err) => {
                    error!(?err, "failed to encode finalized pin-manifest page");
                    return json_error(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "failed to encode finalized pin-manifest page",
                    );
                }
            };
            Response::builder()
                .status(StatusCode::OK)
                .header(header::CONTENT_TYPE, crate::utils::NORITO_MIME_TYPE)
                .body(Body::from(bytes))
                .expect("build pin registry Norito response")
        }
    };
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static("no-store, max-age=0"),
    );
    response
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_pin_manifest(
    State(state): State<SharedAppState>,
    Path(digest_hex): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    accept: Option<ExtractAccept>,
) -> Response {
    let query = match PinManifestReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    if let Err(err) =
        crate::utils::negotiate_json_only_response(accept.as_ref().map(|header| &header.0))
    {
        return err.into_response();
    }
    let digest = match parse_manifest_digest_hex(&digest_hex) {
        Ok(bytes) => ManifestDigest::new(bytes),
        Err(err) => return err.into_response(),
    };
    let expected_finalized_cursor = match query.expected_finalized_cursor() {
        Ok(cursor) => cursor,
        Err(response) => return response,
    };
    let finalized = match FindSorafsPinManifest::new(digest, expected_finalized_cursor)
        .execute(&state.state.query_view())
    {
        Ok(finalized) => finalized,
        Err(error) => return pin_manifest_query_error_response(error),
    };
    let mut response = (StatusCode::OK, JsonBody(finalized)).into_response();
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static("no-store, max-age=0"),
    );
    response
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_aliases(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    accept: Option<ExtractAccept>,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs pin registry API is not enabled on this node");
    }
    let query = match AliasListQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let format = match crate::utils::negotiate_json_only_response(accept.as_ref().map(|hdr| &hdr.0))
    {
        Ok(()) => crate::utils::ResponseFormat::Json,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let requested_offset = query.offset.unwrap_or(0) as usize;
    let namespace_filter = query.namespace.as_deref();
    let digest_filter = query.manifest_digest.as_deref();
    let (attestation, page) = match pin_projection_with_attestation(&state, |world| {
        collect_alias_page(
            world,
            requested_offset,
            limit,
            namespace_filter,
            digest_filter,
        )
    }) {
        Ok(page) => page,
        Err(err) => return err.into_response(),
    };
    let total = page.total_count;
    let offset = normalize_offset(query.offset, total);
    let mut alias_values = Vec::with_capacity(page.entries.len());
    let policy = &state.sorafs_alias_cache_policy;
    let enforcement = state.sorafs_alias_enforcement;
    let now_secs = crate::sorafs::unix_now_secs();
    for entry in &page.entries {
        match prepare_alias_presentation(
            &entry.alias,
            &entry.lineage,
            &entry.governance,
            policy,
            enforcement,
            &state.telemetry,
            now_secs,
        ) {
            Ok(json) => alias_values.push(json),
            Err(err) => return err.into_response(),
        }
    }
    let response = json_object(vec![
        json_entry("attestation", attestation),
        json_entry("total_count", total as u64),
        json_entry("returned_count", alias_values.len() as u64),
        json_entry("offset", offset as u64),
        json_entry("limit", limit as u64),
        json_entry("aliases", Value::Array(alias_values)),
    ]);
    crate::utils::respond_value_with_format(response, format)
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_replication_orders(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    accept: Option<ExtractAccept>,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs pin registry API is not enabled on this node");
    }
    let query = match ReplicationListQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let format = match crate::utils::negotiate_json_only_response(accept.as_ref().map(|hdr| &hdr.0))
    {
        Ok(()) => crate::utils::ResponseFormat::Json,
        Err(err) => return err.into_response(),
    };
    let status_filter = match query.status.as_deref() {
        Some(value) => match parse_replication_status_filter(value) {
            Some(filter) => Some(filter),
            None => {
                return json_error(
                    StatusCode::BAD_REQUEST,
                    format!(
                        "invalid status filter `{value}`; expected pending, completed, cancelled, or expired"
                    ),
                );
            }
        },
        None => None,
    };
    let digest_filter = query.manifest_digest.as_deref().map(|raw| {
        let mut bytes = [0_u8; 32];
        hex::decode_to_slice(raw, &mut bytes)
            .ok()
            .map(|()| ManifestDigest::new(bytes))
    });
    let limit = normalize_limit(query.limit);
    let requested_offset = query
        .offset
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or(0);
    let (attestation, page) = match pin_projection_with_attestation(&state, |world| {
        collect_replication_order_page(world, requested_offset, limit, |record| {
            status_filter.is_none_or(|filter| filter.matches_record(record.status))
                && match digest_filter {
                    None => true,
                    Some(Some(digest)) => record.manifest_digest == digest,
                    Some(None) => false,
                }
        })
    }) {
        Ok(page) => page,
        Err(err) => return err.into_response(),
    };
    let total = page.total_count;
    let offset = requested_offset.min(total);
    let order_values = match page
        .orders
        .iter()
        .map(super::registry::RegistryReplicationOrder::to_json)
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(values) => values,
        Err(err) => {
            error!(?err, "failed to serialize replication orders");
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to serialize replication orders",
            );
        }
    };
    let response = json_object(vec![
        json_entry("attestation", attestation),
        json_entry("total_count", total as u64),
        json_entry("returned_count", order_values.len() as u64),
        json_entry("offset", offset as u64),
        json_entry("limit", limit as u64),
        json_entry("replication_orders", Value::Array(order_values)),
    ]);
    crate::utils::respond_value_with_format(response, format)
}
#[cfg(test)]
fn dm_storage_class_from_manifest(
    class: sorafs_manifest::StorageClass,
) -> iroha_data_model::sorafs::pin_registry::StorageClass {
    match class {
        sorafs_manifest::StorageClass::Hot => {
            iroha_data_model::sorafs::pin_registry::StorageClass::Hot
        }
        sorafs_manifest::StorageClass::Warm => {
            iroha_data_model::sorafs::pin_registry::StorageClass::Warm
        }
        sorafs_manifest::StorageClass::Cold => {
            iroha_data_model::sorafs::pin_registry::StorageClass::Cold
        }
    }
}
#[derive(Debug, Clone)]
struct ResolvedSiteHost {
    hostname: String,
    index_document: String,
    spa_fallback: bool,
    stored: StoredManifest,
}
fn normalized_site_request_host(headers: &HeaderMap) -> Result<String, Response> {
    let Some(host) = headers
        .get(header::HOST)
        .and_then(|value| value.to_str().ok())
    else {
        return Err(json_error(StatusCode::BAD_REQUEST, "missing Host header"));
    };
    normalize_host_header(host)
        .ok_or_else(|| json_error(StatusCode::BAD_REQUEST, "invalid Host header"))
}
/// Return whether the canonical request host selects a configured public SoraFS site.
pub(crate) fn request_host_selects_sorafs_site(
    state: &SharedAppState,
    headers: &HeaderMap,
) -> bool {
    let Ok(host) = normalized_site_request_host(headers) else {
        return false;
    };
    let cid_host = state.sorafs_gateway_config.untrusted_hosting.enabled
        && [
            state
                .sorafs_gateway_config
                .untrusted_hosting
                .cid_host_suffixes
                .live
                .as_str(),
            state
                .sorafs_gateway_config
                .untrusted_hosting
                .cid_host_suffixes
                .taira
                .as_str(),
        ]
        .into_iter()
        .filter(|suffix| !suffix.trim().is_empty())
        .any(|suffix| {
            let suffix = suffix.trim().trim_end_matches('.').to_ascii_lowercase();
            host.strip_suffix(&format!(".{suffix}"))
                .is_some_and(|label| !label.is_empty() && !label.contains('.'))
        });
    if cid_host
        || state
            .sorafs_site_bindings
            .as_deref()
            .and_then(|bindings| find_site_binding(bindings, &host))
            .is_some()
    {
        return true;
    }
    let state_view = state.state.view();
    super::site::has_authoritative_public_site_host(state_view.world(), &host)
}
fn decode_canonical_content_cid(cid: &str) -> Option<Vec<u8>> {
    let decoded = decode_content_cid(cid)?;
    (encode_content_cid(&decoded) == cid).then_some(decoded)
}
fn extract_cid_from_untrusted_host(
    host: &str,
    config: &iroha_config::parameters::actual::SorafsGatewayUntrustedHosting,
) -> Result<Option<String>, Response> {
    if !config.enabled {
        return Ok(None);
    }
    for suffix in [
        config.cid_host_suffixes.live.as_str(),
        config.cid_host_suffixes.taira.as_str(),
    ] {
        let suffix = suffix.trim().trim_end_matches('.').to_ascii_lowercase();
        if suffix.is_empty() {
            continue;
        }
        let marker = format!(".{suffix}");
        let Some(cid_label) = host.strip_suffix(&marker) else {
            continue;
        };
        if cid_label.is_empty() || cid_label.contains('.') {
            continue;
        }
        if decode_canonical_content_cid(cid_label).is_none() {
            return Err(json_error(
                StatusCode::BAD_REQUEST,
                "invalid content CID host",
            ));
        }
        return Ok(Some(cid_label.to_owned()));
    }
    Ok(None)
}
fn resolve_site_host_from_authoritative_app(
    state: &SharedAppState,
    host: &str,
) -> Result<Option<ResolvedSiteHost>, Response> {
    let binding = {
        let state_view = state.state.view();
        super::site::authoritative_app_site_binding(state_view.world(), host)
    }
    .map_err(|error| {
        error!(%error, %host, "invalid ledger-authoritative SoraCloud static-site binding");
        json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "the ledger-authoritative SoraCloud site binding is invalid",
        )
    })?;
    let Some(binding) = binding else {
        return Ok(None);
    };
    let manifest_digest =
        parse_hex_fixed::<32>(&binding.manifest_digest_hex, "manifest_digest_hex").map_err(
            |_| {
                json_error(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "the ledger-authoritative SoraCloud site manifest digest is invalid",
                )
            },
        )?;
    let stored = state
        .sorafs_node
        .manifest_metadata_by_digest(&manifest_digest)
        .map_err(node_storage_error_response)?;
    Ok(Some(ResolvedSiteHost {
        hostname: binding.hostname,
        index_document: binding.index_document,
        spa_fallback: binding.spa_fallback,
        stored,
    }))
}
async fn resolve_site_host(
    state: &SharedAppState,
    headers: &HeaderMap,
) -> Result<ResolvedSiteHost, Response> {
    if !state.sorafs_node.is_enabled() {
        return Err(storage_disabled_response());
    }
    let host = normalized_site_request_host(headers)?;
    if let Some(cid) =
        extract_cid_from_untrusted_host(&host, &state.sorafs_gateway_config.untrusted_hosting)?
    {
        let stored = resolve_site_manifest_by_cid(state, &cid).await?;
        return Ok(ResolvedSiteHost {
            hostname: host,
            index_document: "index.html".to_owned(),
            spa_fallback: true,
            stored,
        });
    }
    if let Some(resolved) = resolve_site_host_from_authoritative_app(state, &host)? {
        return Ok(resolved);
    }
    let Some(bindings) = state.sorafs_site_bindings.as_deref() else {
        return Err(StatusCode::NOT_FOUND.into_response());
    };
    let Some(binding) = find_site_binding(bindings, &host).cloned() else {
        return Err(StatusCode::NOT_FOUND.into_response());
    };
    let manifest_digest =
        match parse_hex_fixed::<32>(&binding.manifest_digest_hex, "manifest_digest_hex") {
            Ok(value) => value,
            Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err)),
        };
    let stored = match state
        .sorafs_node
        .manifest_metadata_by_digest(&manifest_digest)
    {
        Ok(manifest) => manifest,
        Err(err) => return Err(node_storage_error_response(err)),
    };
    let hostname = binding.hostname.clone();
    let index_document = binding.index_document().to_owned();
    let spa_fallback = binding.spa_fallback_enabled();
    Ok(ResolvedSiteHost {
        hostname,
        index_document,
        spa_fallback,
        stored,
    })
}
fn find_local_site_manifest_by_cid(
    state: &SharedAppState,
    cid_bytes: &[u8],
) -> Result<Option<StoredManifest>, Response> {
    if !state.sorafs_node.is_enabled() {
        return Err(storage_disabled_response());
    }
    state
        .sorafs_node
        .manifest_metadata_by_cid(cid_bytes)
        .map_err(node_storage_error_response)
}
fn chunk_profile_from_manifest_descriptor(manifest: &ManifestV1) -> Result<ChunkProfile, String> {
    if manifest.chunking.profile_id.0 == 0 {
        if manifest.chunking.min_size == 0
            || manifest.chunking.target_size == 0
            || manifest.chunking.max_size == 0
            || manifest.chunking.min_size > manifest.chunking.target_size
            || manifest.chunking.target_size > manifest.chunking.max_size
        {
            return Err(
                "manifest inline chunker profile has invalid chunk size bounds".to_string(),
            );
        }
        return Ok(ChunkProfile {
            min_size: usize::try_from(manifest.chunking.min_size)
                .map_err(|_| "manifest chunk minimum exceeds host limits".to_string())?,
            target_size: usize::try_from(manifest.chunking.target_size)
                .map_err(|_| "manifest chunk target exceeds host limits".to_string())?,
            max_size: usize::try_from(manifest.chunking.max_size)
                .map_err(|_| "manifest chunk maximum exceeds host limits".to_string())?,
            break_mask: u64::from(manifest.chunking.break_mask),
        });
    }
    let descriptor = chunker_registry::lookup(manifest.chunking.profile_id).ok_or_else(|| {
        format!(
            "manifest chunker profile id {} is not registered",
            manifest.chunking.profile_id.0
        )
    })?;
    if descriptor.multihash_code != manifest.chunking.multihash_code {
        return Err(format!(
            "manifest multihash code {} does not match registry descriptor {}",
            manifest.chunking.multihash_code, descriptor.multihash_code
        ));
    }
    Ok(descriptor.profile)
}
pub(crate) async fn resolve_site_manifest_by_cid_unchecked(
    state: &SharedAppState,
    cid: &str,
) -> Result<StoredManifest, Response> {
    let cid_bytes = decode_canonical_content_cid(cid)
        .ok_or_else(|| json_error(StatusCode::BAD_REQUEST, "invalid content CID"))?;
    if let Some(stored) = find_local_site_manifest_by_cid(state, &cid_bytes)? {
        return Ok(stored);
    }
    enforce_governed_gateway_compliance_for_cid(state, &cid_bytes)?;
    Err(json_error(
        StatusCode::SERVICE_UNAVAILABLE,
        REMOTE_HYDRATION_CAPABILITY_REQUIRED,
    ))
}
async fn resolve_site_manifest_by_cid(
    state: &SharedAppState,
    cid: &str,
) -> Result<StoredManifest, Response> {
    resolve_site_manifest_by_cid_unchecked(state, cid).await
}
async fn validate_local_gateway_manifest(
    state: &SharedAppState,
    stored: &StoredManifest,
) -> Result<(), Response> {
    let stored = stored.clone();
    sorafs_heavy_blocking_task(state, "SoraFS gateway manifest validation", move || {
        let manifest_bytes = stored
            .load_manifest_bytes()
            .map_err(storage_backend_error)?;
        let manifest = decode_manifest_v1_canonical(&manifest_bytes).map_err(|error| {
            json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                format!("stored SoraFS manifest is not canonical: {error}"),
            )
        })?;
        validate_manifest(&manifest, &sorafs_manifest::PinPolicyConstraints::default()).map_err(
            |error| {
                json_error(
                    StatusCode::SERVICE_UNAVAILABLE,
                    format!("stored SoraFS manifest failed validation: {error}"),
                )
            },
        )?;
        let digest = ManifestDigest::from_manifest(&manifest).map_err(|error| {
            json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                format!("stored SoraFS manifest digest failed: {error}"),
            )
        })?;
        if digest.as_bytes() != stored.manifest_digest()
            || manifest.root_cid.as_slice() != stored.manifest_cid()
        {
            return Err(json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "stored SoraFS manifest identity does not match its local index",
            ));
        }
        Ok(())
    })
    .await
}

#[cfg_attr(
    test,
    expect(
        clippy::unnecessary_wraps,
        reason = "tests use loopback when remote headers are absent; production rejects the missing address"
    )
)]
fn gateway_request_remote(headers: &HeaderMap) -> Result<SocketAddr, Response> {
    if let Some(ip) = crate::limits::effective_remote_ip(headers, None) {
        return Ok(SocketAddr::new(ip, 0));
    }
    #[cfg(test)]
    {
        Ok(SocketAddr::from(([127, 0, 0, 1], 0)))
    }
    #[cfg(not(test))]
    Err(json_error(
        StatusCode::SERVICE_UNAVAILABLE,
        "SoraFS gateway request identity is unavailable",
    ))
}

async fn enforce_local_gateway_pre_read(
    state: &SharedAppState,
    headers: &HeaderMap,
    stored: &StoredManifest,
    requested_provider_id: Option<[u8; 32]>,
    remote: SocketAddr,
) -> Result<(), Response> {
    validate_local_gateway_manifest(state, stored).await?;
    let provider_id = authoritative_sorafs_provider_id(state)?;
    if requested_provider_id.is_some_and(|requested| requested != provider_id) {
        return Err(json_error(
            StatusCode::FORBIDDEN,
            "requested SoraFS provider is not the local admitted provider",
        ));
    }
    enforce_gateway_policy_for_request(state, headers, stored, Some(provider_id), remote, true)
}
