fn file_listing_entry_json(file: &StoredFileRecord) -> Value {
    let mut obj = Map::new();
    obj.insert(
        "path".into(),
        Value::Array(file.path.iter().cloned().map(Value::String).collect()),
    );
    obj.insert("offset".into(), Value::from(file.offset));
    obj.insert("size".into(), Value::from(file.size));
    obj.insert("first_chunk".into(), Value::from(file.first_chunk as u64));
    obj.insert("chunk_count".into(), Value::from(file.chunk_count as u64));
    Value::Object(obj)
}
fn bounded_file_listing_json(stored: &StoredManifest, limit: usize) -> (Vec<Value>, usize, bool) {
    let file_count = stored.files().len();
    let files = stored
        .files()
        .iter()
        .take(limit)
        .map(file_listing_entry_json)
        .collect();
    (files, file_count, file_count > limit)
}
fn attach_cid_gateway_headers(response: &mut Response, stored: &StoredManifest) {
    response.headers_mut().insert(
        HeaderName::from_static(HEADER_SORA_CONTENT_CID),
        HeaderValue::from_str(&encode_content_cid(stored.manifest_cid()))
            .unwrap_or_else(|_| HeaderValue::from_static("invalid")),
    );
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static("public, max-age=31536000, immutable"),
    );
}

fn authoritative_inrou_public_discovery_etag(document_bytes: &[u8]) -> Option<HeaderValue> {
    HeaderValue::from_str(&format!("\"{}\"", Hash::new(document_bytes))).ok()
}

async fn authoritative_inrou_public_discovery_response(
    state: &SharedAppState,
    content_cid: &str,
) -> Option<Response> {
    let core_state = Arc::clone(&state.state);
    let content_cid = content_cid.to_owned();
    let worker_content_cid = content_cid.clone();
    let document_bytes = match sorafs_heavy_blocking_task(
        state,
        "authoritative Inrou public discovery read",
        move || {
            let state_view = core_state.view();
            crate::soracloud::authoritative_public_discovery_document_for_content_cid(
                state_view.world(),
                &worker_content_cid,
            )
            .map_err(IntoResponse::into_response)
        },
    )
    .await
    {
        Ok(Some(document_bytes)) => document_bytes,
        Ok(None) => return None,
        Err(response) => return Some(response),
    };
    let document_length = document_bytes.len();
    let Some(document_etag) = authoritative_inrou_public_discovery_etag(&document_bytes) else {
        return Some(json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "authoritative Inrou public discovery hash is not a valid strong ETag",
        ));
    };
    let mut response = Response::new(Body::from(document_bytes));
    *response.status_mut() = StatusCode::OK;
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/json"),
    );
    response.headers_mut().insert(
        header::CONTENT_LENGTH,
        HeaderValue::from_str(&document_length.to_string())
            .unwrap_or_else(|_| HeaderValue::from_static("0")),
    );
    response.headers_mut().insert(ETAG, document_etag);
    response.headers_mut().insert(
        HeaderName::from_static(HEADER_SORA_CONTENT_CID),
        HeaderValue::from_str(content_cid.as_str())
            .unwrap_or_else(|_| HeaderValue::from_static("invalid")),
    );
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static("public, max-age=31536000, immutable"),
    );
    response.headers_mut().insert(
        HeaderName::from_static("x-content-type-options"),
        HeaderValue::from_static("nosniff"),
    );
    Some(response)
}
async fn canonical_inrou_public_discovery_cid_host_response(
    state: &SharedAppState,
    headers: &HeaderMap,
    raw_path: &str,
) -> Option<Response> {
    if raw_path != crate::soracloud::PUBLIC_SERVICE_DISCOVERY_INDEX_DOCUMENT {
        return None;
    }
    let host = match normalized_site_request_host(headers) {
        Ok(host) => host,
        Err(response) => return Some(response),
    };
    let content_cid = match extract_cid_from_untrusted_host(
        &host,
        &state.sorafs_gateway_config.untrusted_hosting,
    ) {
        Ok(Some(content_cid)) => content_cid,
        Ok(None) => return None,
        Err(response) => return Some(response),
    };
    let response = match authoritative_inrou_public_discovery_response(state, &content_cid).await {
        Some(response) => response,
        None if state.sorafs_node.is_enabled() => return None,
        None => return Some(storage_disabled_response()),
    };
    if !response.status().is_success() {
        return Some(response);
    }
    let Some(cid_bytes) = decode_canonical_content_cid(&content_cid) else {
        return Some(json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "authoritative public discovery content CID is not canonical",
        ));
    };
    let remote = match gateway_request_remote(headers) {
        Ok(remote) => remote,
        Err(response) => return Some(response),
    };
    if let Err(response) =
        enforce_authoritative_public_discovery_pre_read(state, headers, &cid_bytes, remote)
    {
        return Some(response);
    }
    Some(response)
}
fn should_use_spa_fallback_enabled(raw_path: &str, enabled: bool) -> bool {
    if !enabled {
        return false;
    }
    let trimmed = raw_path.trim_end_matches('/');
    let last = trimmed.rsplit('/').next().unwrap_or_default();
    !last.contains('.')
}
fn index_document_path(index_document: &str) -> Vec<String> {
    path_components_for_request(index_document, index_document)
        .unwrap_or_else(|| vec![index_document.to_owned()])
}
fn is_browser_document_request(headers: &HeaderMap) -> bool {
    if headers
        .get("sec-fetch-dest")
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.eq_ignore_ascii_case("document"))
    {
        return true;
    }
    if headers
        .get("sec-fetch-mode")
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.eq_ignore_ascii_case("navigate"))
    {
        return true;
    }
    headers
        .get(header::ACCEPT)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| {
            value.split(',').any(|entry| {
                let mime = entry.trim().split(';').next().unwrap_or_default().trim();
                mime.eq_ignore_ascii_case("text/html")
                    || mime.eq_ignore_ascii_case("application/xhtml+xml")
            })
        })
}
fn path_gateway_host_for_cid_suffix(suffix: &str) -> Option<String> {
    suffix
        .strip_prefix("sorafs.")
        .map(|value| value.trim().trim_end_matches('.').to_ascii_lowercase())
        .filter(|value| !value.is_empty())
}
fn canonical_cid_host_suffix_for_request(
    headers: &HeaderMap,
    config: &iroha_config::parameters::actual::SorafsGatewayUntrustedHosting,
) -> Option<String> {
    let host = headers.get(header::HOST)?.to_str().ok()?;
    let normalized_host = normalize_host_header(host)?;
    for suffix in [
        config.cid_host_suffixes.taira.as_str(),
        config.cid_host_suffixes.live.as_str(),
    ] {
        let Some(path_gateway_host) = path_gateway_host_for_cid_suffix(suffix) else {
            continue;
        };
        if normalized_host == path_gateway_host {
            return Some(suffix.to_owned());
        }
    }
    None
}
fn cid_gateway_request_path(uri: &Uri, cid: &str) -> Option<String> {
    let prefix = format!("/sorafs/cid/{cid}");
    let path = uri.path();
    if path == prefix || path == format!("{prefix}/") {
        return Some("/".to_owned());
    }
    path.strip_prefix(&format!("{prefix}/"))
        .map(|suffix| format!("/{suffix}"))
}
fn permanent_redirect(location: String) -> Response {
    let mut response = Response::new(Body::empty());
    *response.status_mut() = StatusCode::PERMANENT_REDIRECT;
    response.headers_mut().insert(
        header::LOCATION,
        HeaderValue::from_str(&location).unwrap_or_else(|_| HeaderValue::from_static("/")),
    );
    response
}
fn maybe_redirect_cid_gateway_request(
    state: &SharedAppState,
    headers: &HeaderMap,
    uri: &Uri,
    cid: &str,
) -> Option<Response> {
    redirect_cid_gateway_request(state, headers, uri, cid, false)
}
fn redirect_cid_gateway_request(
    state: &SharedAppState,
    headers: &HeaderMap,
    uri: &Uri,
    cid: &str,
    active_content: bool,
) -> Option<Response> {
    let config = &state.sorafs_gateway_config.untrusted_hosting;
    if !config.enabled || (!active_content && !config.path_gateway_redirect) {
        return None;
    }
    if !active_content && config.redirect_html_only && !is_browser_document_request(headers) {
        return None;
    }
    let suffix = canonical_cid_host_suffix_for_request(headers, config)?;
    let path = cid_gateway_request_path(uri, cid)?;
    let mut location = format!("https://{cid}.{suffix}{path}");
    if let Some(query) = uri.query() {
        location.push('?');
        location.push_str(query);
    }
    Some(permanent_redirect(location))
}
fn is_cid_derived_isolated_origin(
    headers: &HeaderMap,
    cid: &str,
    config: &iroha_config::parameters::actual::SorafsGatewayUntrustedHosting,
) -> bool {
    if !config.enabled {
        return false;
    }
    let Some(host) = headers
        .get(header::HOST)
        .and_then(|value| value.to_str().ok())
        .and_then(normalize_host_header)
    else {
        return false;
    };
    [
        config.cid_host_suffixes.taira.as_str(),
        config.cid_host_suffixes.live.as_str(),
    ]
    .into_iter()
    .filter(|suffix| !suffix.is_empty())
    .any(|suffix| {
        host == format!(
            "{cid}.{}",
            suffix.trim().trim_end_matches('.').to_ascii_lowercase()
        )
    })
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SiteResponseRange {
    offset: u64,
    length: usize,
    partial: bool,
}
fn site_range_not_satisfiable(file_size: u64) -> Response {
    let mut response = json_error(
        StatusCode::RANGE_NOT_SATISFIABLE,
        "requested site byte range is not satisfiable",
    );
    if let Ok(value) = HeaderValue::from_str(&format!("bytes */{file_size}")) {
        response.headers_mut().insert(header::CONTENT_RANGE, value);
    }
    response
        .headers_mut()
        .insert(header::ACCEPT_RANGES, HeaderValue::from_static("bytes"));
    response
}
fn parse_site_response_range(
    headers: &HeaderMap,
    file_size: u64,
) -> Result<SiteResponseRange, Response> {
    let raw = match single_header_value(headers, "range") {
        Ok(Some(value)) => value,
        Ok(None) => {
            if file_size > MAX_SITE_RESPONSE_BYTES {
                let mut response = json_error(
                    StatusCode::PAYLOAD_TOO_LARGE,
                    format!(
                        "site file exceeds {MAX_SITE_RESPONSE_BYTES} bytes; request one bounded byte range"
                    ),
                );
                response
                    .headers_mut()
                    .insert(header::ACCEPT_RANGES, HeaderValue::from_static("bytes"));
                return Err(response);
            }
            let length = usize::try_from(file_size).map_err(|_| {
                json_error(
                    StatusCode::PAYLOAD_TOO_LARGE,
                    "site file exceeds supported response size",
                )
            })?;
            return Ok(SiteResponseRange {
                offset: 0,
                length,
                partial: false,
            });
        }
        Err(()) => {
            return Err(json_error(
                StatusCode::BAD_REQUEST,
                "duplicate Range header",
            ));
        }
    };
    let raw = raw
        .to_str()
        .map_err(|_| json_error(StatusCode::BAD_REQUEST, "invalid Range header"))?;
    let spec = raw
        .strip_prefix("bytes=")
        .filter(|value| !value.contains(','))
        .ok_or_else(|| json_error(StatusCode::BAD_REQUEST, "only one bytes range is supported"))?;
    let (start, end) = spec
        .split_once('-')
        .ok_or_else(|| json_error(StatusCode::BAD_REQUEST, "invalid bytes range"))?;
    if file_size == 0 {
        return Err(site_range_not_satisfiable(file_size));
    }
    let (start, end) = if start.is_empty() {
        let suffix = end
            .parse::<u64>()
            .ok()
            .filter(|suffix| *suffix != 0)
            .ok_or_else(|| site_range_not_satisfiable(file_size))?;
        (file_size.saturating_sub(suffix), file_size - 1)
    } else {
        let start = start
            .parse::<u64>()
            .map_err(|_| site_range_not_satisfiable(file_size))?;
        let end = if end.is_empty() {
            file_size - 1
        } else {
            end.parse::<u64>()
                .map_err(|_| site_range_not_satisfiable(file_size))?
                .min(file_size - 1)
        };
        (start, end)
    };
    if start >= file_size || end < start {
        return Err(site_range_not_satisfiable(file_size));
    }
    let length = end
        .checked_sub(start)
        .and_then(|length| length.checked_add(1))
        .ok_or_else(|| site_range_not_satisfiable(file_size))?;
    if length > MAX_SITE_RESPONSE_BYTES {
        let mut response = json_error(
            StatusCode::PAYLOAD_TOO_LARGE,
            format!("site byte ranges are limited to {MAX_SITE_RESPONSE_BYTES} bytes"),
        );
        response
            .headers_mut()
            .insert(header::ACCEPT_RANGES, HeaderValue::from_static("bytes"));
        return Err(response);
    }
    Ok(SiteResponseRange {
        offset: start,
        length: usize::try_from(length).map_err(|_| site_range_not_satisfiable(file_size))?,
        partial: true,
    })
}
async fn build_site_file_response(
    state: &SharedAppState,
    stored: &StoredManifest,
    path: &[String],
    request_headers: &HeaderMap,
) -> Response {
    let Some(file) = stored.file_by_path(path) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let response_range = match parse_site_response_range(request_headers, file.size) {
        Ok(range) => range,
        Err(response) => return response,
    };
    let Some(storage_offset) = file.offset.checked_add(response_range.offset) else {
        return json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "stored file offset overflow",
        );
    };
    let worker_state = state.clone();
    let manifest_id = stored.manifest_id().to_owned();
    let bytes = match sorafs_heavy_blocking_task(state, "SoraFS site payload read", move || {
        worker_state
            .sorafs_node
            .read_payload_range(&manifest_id, storage_offset, response_range.length)
            .map_err(node_storage_error_response)
    })
    .await
    {
        Ok(value) => value,
        Err(response) => return response,
    };
    let mut response = Response::new(Body::from(bytes));
    *response.status_mut() = if response_range.partial {
        StatusCode::PARTIAL_CONTENT
    } else {
        StatusCode::OK
    };
    let content_type = content_type_for_path(path);
    response
        .headers_mut()
        .insert(header::CONTENT_TYPE, HeaderValue::from_static(content_type));
    response.headers_mut().insert(
        header::CONTENT_LENGTH,
        HeaderValue::from_str(&response_range.length.to_string())
            .unwrap_or_else(|_| HeaderValue::from_static("0")),
    );
    response
        .headers_mut()
        .insert(header::ACCEPT_RANGES, HeaderValue::from_static("bytes"));
    response.headers_mut().insert(
        HeaderName::from_static("x-content-type-options"),
        HeaderValue::from_static("nosniff"),
    );
    if content_type == "application/octet-stream" {
        response.headers_mut().insert(
            header::CONTENT_DISPOSITION,
            HeaderValue::from_static("attachment"),
        );
    }
    if response_range.partial {
        let end = response_range
            .offset
            .saturating_add(u64::try_from(response_range.length).unwrap_or_default())
            .saturating_sub(1);
        if let Ok(value) = HeaderValue::from_str(&format!(
            "bytes {}-{end}/{}",
            response_range.offset, file.size
        )) {
            response.headers_mut().insert(header::CONTENT_RANGE, value);
        }
    }
    response
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_site_manifest(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let query = match SiteFileListReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let resolved = match resolve_site_host(&state, &headers).await {
        Ok(value) => value,
        Err(response) => return response,
    };
    let remote = match gateway_request_remote(&headers) {
        Ok(remote) => remote,
        Err(response) => return response,
    };
    if let Err(response) =
        enforce_local_gateway_pre_read(&state, &headers, &resolved.stored, None, remote).await
    {
        return response;
    }
    match sorafs_heavy_blocking_task(&state, "SoraFS site manifest read", move || {
        let manifest_bytes = resolved
            .stored
            .load_manifest_bytes()
            .map_err(storage_backend_error)?;
        if manifest_bytes.len() > MAX_LOCAL_MANIFEST_RESPONSE_BYTES {
            return Err(json_error(
                StatusCode::PAYLOAD_TOO_LARGE,
                "stored manifest exceeds the local readback byte limit",
            ));
        }
        let (files, file_count, truncated_files) =
            bounded_file_listing_json(&resolved.stored, limit);
        let returned_file_count = files.len();
        let value = json_object(vec![
            json_entry("hostname", Value::from(resolved.hostname.clone())),
            json_entry(
                "content_cid",
                Value::from(encode_content_cid(resolved.stored.manifest_cid())),
            ),
            json_entry(
                "manifest_digest_hex",
                Value::from(hex::encode(resolved.stored.manifest_digest())),
            ),
            json_entry(
                "manifest_id_hex",
                Value::from(resolved.stored.manifest_id().to_owned()),
            ),
            json_entry(
                "manifest_b64",
                Value::from(BASE64_STANDARD.encode(manifest_bytes)),
            ),
            json_entry(
                "index_document",
                Value::from(resolved.index_document.clone()),
            ),
            json_entry("spa_fallback", Value::from(resolved.spa_fallback)),
            json_entry("file_count", Value::from(file_count as u64)),
            json_entry(
                "returned_file_count",
                Value::from(returned_file_count as u64),
            ),
            json_entry("limit", Value::from(limit as u64)),
            json_entry("truncated_files", Value::from(truncated_files)),
            json_entry("files", Value::Array(files)),
        ]);
        Ok(JsonBody(value).into_response())
    })
    .await
    {
        Ok(response) | Err(response) => response,
    }
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_site_root(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
) -> Response {
    handle_get_sorafs_site_path(State(state), headers, Path(String::new())).await
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_site_path(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    Path(raw_path): Path<String>,
) -> Response {
    if let Some(response) =
        canonical_inrou_public_discovery_cid_host_response(&state, &headers, &raw_path).await
    {
        return response;
    }
    let resolved = match resolve_site_host(&state, &headers).await {
        Ok(value) => value,
        Err(response) => return response,
    };
    let remote = match gateway_request_remote(&headers) {
        Ok(remote) => remote,
        Err(response) => return response,
    };
    if let Err(response) =
        enforce_local_gateway_pre_read(&state, &headers, &resolved.stored, None, remote).await
    {
        return response;
    }
    let Some(mut path) = path_components_for_request(&raw_path, &resolved.index_document) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    if resolved.stored.file_by_path(&path).is_none()
        && should_use_spa_fallback_enabled(&raw_path, resolved.spa_fallback)
    {
        path = index_document_path(&resolved.index_document);
    }
    build_site_file_response(&state, &resolved.stored, &path, &headers).await
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_cid_lookup(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    Path(cid): Path<String>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let query = match SiteFileListReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let stored = match resolve_site_manifest_by_cid(&state, &cid).await {
        Ok(value) => value,
        Err(response) => return response,
    };
    let remote = match gateway_request_remote(&headers) {
        Ok(remote) => remote,
        Err(response) => return response,
    };
    if let Err(response) =
        enforce_local_gateway_pre_read(&state, &headers, &stored, None, remote).await
    {
        return response;
    }
    let (files, file_count, truncated_files) = bounded_file_listing_json(&stored, limit);
    let returned_file_count = files.len();
    let value = json_object(vec![
        json_entry(
            "content_cid",
            Value::from(encode_content_cid(stored.manifest_cid())),
        ),
        json_entry(
            "manifest_digest_hex",
            Value::from(hex::encode(stored.manifest_digest())),
        ),
        json_entry(
            "manifest_id_hex",
            Value::from(stored.manifest_id().to_owned()),
        ),
        json_entry(
            "index_document",
            stored
                .file_by_path(&["index.html".to_owned()])
                .map(|_| Value::from("index.html"))
                .unwrap_or(Value::Null),
        ),
        json_entry("file_count", Value::from(file_count as u64)),
        json_entry(
            "returned_file_count",
            Value::from(returned_file_count as u64),
        ),
        json_entry("limit", Value::from(limit as u64)),
        json_entry("truncated_files", Value::from(truncated_files)),
        json_entry("files", Value::Array(files)),
    ]);
    JsonBody(value).into_response()
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_cid_root(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    uri: Uri,
    Path(cid): Path<String>,
) -> Response {
    handle_get_sorafs_cid_path(State(state), headers, uri, Path((cid, String::new()))).await
}
#[cfg(feature = "app_api")]
pub(crate) async fn handle_get_sorafs_cid_path(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    uri: Uri,
    Path((cid, raw_path)): Path<(String, String)>,
) -> Response {
    if decode_canonical_content_cid(&cid).is_none() {
        return json_error(StatusCode::BAD_REQUEST, "invalid content CID");
    }
    let stored = match resolve_site_manifest_by_cid(&state, &cid).await {
        Ok(value) => value,
        Err(response) => return response,
    };
    let remote = match gateway_request_remote(&headers) {
        Ok(remote) => remote,
        Err(response) => return response,
    };
    if let Err(response) =
        enforce_local_gateway_pre_read(&state, &headers, &stored, None, remote).await
    {
        return response;
    }
    // Keep browser redirects behind the same local admission boundary as byte reads.
    if let Some(response) = maybe_redirect_cid_gateway_request(&state, &headers, &uri, &cid) {
        return response;
    }
    if raw_path == crate::soracloud::PUBLIC_SERVICE_DISCOVERY_INDEX_DOCUMENT
        && let Some(response) = authoritative_inrou_public_discovery_response(&state, &cid).await
    {
        return response;
    }
    let Some(path) = path_components_for_request(&raw_path, "index.html") else {
        return StatusCode::NOT_FOUND.into_response();
    };
    if stored.file_by_path(&path).is_some_and(|_| {
        iroha_torii_shared::content_mime::is_active_media_type(content_type_for_path(&path))
    }) && !is_cid_derived_isolated_origin(
        &headers,
        &cid,
        &state.sorafs_gateway_config.untrusted_hosting,
    ) {
        if let Some(response) = redirect_cid_gateway_request(&state, &headers, &uri, &cid, true) {
            return response;
        }
        return json_error(
            StatusCode::MISDIRECTED_REQUEST,
            "active CID content is available only from its CID-derived isolated origin",
        );
    }
    let mut response = build_site_file_response(&state, &stored, &path, &headers).await;
    if response.status().is_success() {
        attach_cid_gateway_headers(&mut response, &stored);
    }
    response
}
