#[derive(Debug)]
struct ProofStreamInflightGuard {
    telemetry: MaybeTelemetry,
    kind: &'static str,
}
impl ProofStreamInflightGuard {
    fn new(telemetry: MaybeTelemetry, kind: &'static str) -> Self {
        telemetry.with_metrics(|metrics| {
            metrics.inc_sorafs_proof_stream_inflight(kind);
        });
        Self { telemetry, kind }
    }
}
impl Drop for ProofStreamInflightGuard {
    fn drop(&mut self) {
        self.telemetry.with_metrics(|metrics| {
            metrics.dec_sorafs_proof_stream_inflight(self.kind);
        });
    }
}
#[cfg_attr(not(feature = "telemetry"), allow(dead_code))]
fn round_clamped_u32(value: f64) -> u32 {
    let rounded = value.round();
    let bounded = rounded.clamp(0.0, f64::from(u32::MAX));
    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
    {
        bounded as u32
    }
}
#[cfg_attr(not(feature = "telemetry"), allow(dead_code))]
fn round_clamped_u64(value: f64) -> u64 {
    let rounded = value.round();
    let bounded = rounded.clamp(0.0, u64::MAX as f64);
    #[allow(clippy::cast_sign_loss)]
    {
        bounded as u64
    }
}
fn manifest_envelope_valid(headers: &HeaderMap, record: Option<&PinManifestRecord>) -> bool {
    let Ok(Some(envelope_header)) = single_header_value(headers, HEADER_SORA_MANIFEST_ENVELOPE)
    else {
        return false;
    };
    let Some(envelope_b64) = envelope_header
        .to_str()
        .ok()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return false;
    };
    let Some(record) = record else {
        return false;
    };
    let Ok(envelope) = BASE64_STANDARD.decode(envelope_b64.as_bytes()) else {
        return false;
    };
    validate_manifest_envelope_bytes(record, &envelope)
}
fn validate_manifest_envelope_bytes(record: &PinManifestRecord, envelope: &[u8]) -> bool {
    let parsed: Value = match json::from_slice(envelope) {
        Ok(value) => value,
        Err(_) => return false,
    };
    let Some(obj) = parsed.as_object() else {
        return false;
    };
    let expected_manifest_hex = hex::encode(record.digest.as_bytes());
    if obj.get("manifest_blake3").and_then(Value::as_str) != Some(expected_manifest_hex.as_str()) {
        return false;
    }
    let expected_chunk_hex = hex::encode(record.chunk_digest_sha3_256);
    if obj.get("chunk_digest_sha3_256").and_then(Value::as_str) != Some(expected_chunk_hex.as_str())
    {
        return false;
    }
    let canonical_profile = record.chunker.to_handle();
    if obj.get("profile").and_then(Value::as_str) != Some(canonical_profile.as_str()) {
        return false;
    }
    if let Some(stored_digest) = record.council_envelope_digest
        && blake3_hash(envelope).as_bytes() != &stored_digest
    {
        return false;
    }
    let Some(signatures) = obj.get("signatures").and_then(Value::as_array) else {
        return false;
    };
    if signatures.is_empty() {
        return false;
    }
    signatures
        .iter()
        .all(|entry| validate_manifest_envelope_signature(entry, record.digest.as_bytes()))
}
fn validate_manifest_envelope_signature(entry: &Value, message: &[u8]) -> bool {
    let Some(algorithm) = entry.get("algorithm").and_then(Value::as_str) else {
        return false;
    };
    if !algorithm.eq_ignore_ascii_case("ed25519") {
        return false;
    }
    let Some(signer_hex) = entry.get("signer").and_then(Value::as_str) else {
        return false;
    };
    let Ok(signer_bytes) = hex::decode(signer_hex) else {
        return false;
    };
    let Ok(public_key) = PublicKey::from_bytes(Algorithm::Ed25519, &signer_bytes) else {
        return false;
    };
    if let Some(multihash) = entry.get("signer_multihash").and_then(Value::as_str)
        && multihash != public_key.to_string()
    {
        return false;
    }
    let Some(signature_hex) = entry.get("signature").and_then(Value::as_str) else {
        return false;
    };
    let Ok(signature_bytes) = hex::decode(signature_hex) else {
        return false;
    };
    if signature_bytes.len() != 64 {
        return false;
    }
    let Ok(signature) = iroha_crypto::ed25519_parse_signature(&signature_bytes) else {
        return false;
    };
    signature.verify(&public_key, message).is_ok()
}
fn parse_cache_control_max_age(value: &str) -> Option<u64> {
    value.split(',').find_map(|directive| {
        let (name, raw) = directive.trim().split_once('=')?;
        if !name.trim().eq_ignore_ascii_case("max-age") {
            return None;
        }
        raw.trim().trim_matches('"').parse::<u64>().ok()
    })
}
fn parse_cache_ttl(headers: &HeaderMap) -> Option<u64> {
    match single_header_value(headers, HEADER_SORA_CACHE_TTL) {
        Ok(Some(raw)) => return raw.to_str().ok()?.trim().parse::<u64>().ok(),
        Ok(None) => {}
        Err(()) => return None,
    }
    let mut ttl = None;
    for value in headers.get_all(CACHE_CONTROL).iter() {
        let value = value.to_str().ok()?;
        for directive in value.split(',') {
            let Some((name, _)) = directive.trim().split_once('=') else {
                continue;
            };
            if !name.trim().eq_ignore_ascii_case("max-age") {
                continue;
            }
            let parsed = parse_cache_control_max_age(directive)?;
            if ttl.is_some_and(|existing| existing != parsed) {
                return None;
            }
            ttl = Some(parsed);
        }
    }
    ttl
}
fn parse_trusted_gateway_region(
    headers: &HeaderMap,
    remote: SocketAddr,
    trusted_proxies: &[crate::limits::IpNet],
) -> Option<RegionCode> {
    if !crate::limits::cidr_contains(trusted_proxies, remote.ip()) {
        return None;
    }
    single_header_value(headers, HEADER_SORA_REGION)
        .ok()
        .flatten()
        .and_then(|value| value.to_str().ok())
        .and_then(RegionCode::parse)
}
#[derive(Debug)]
struct ManifestResolution {
    manifest_id: String,
    blinded_b64: Option<String>,
}
fn resolve_manifest_request(
    state: &SharedAppState,
    manifest_param: &str,
    headers: &HeaderMap,
) -> Result<ManifestResolution, Response> {
    let raw_blinded = match single_header_value(headers, HEADER_SORA_REQ_BLINDED_CID) {
        Ok(Some(value)) => value,
        Ok(None) => {
            return Ok(ManifestResolution {
                manifest_id: manifest_param.to_owned(),
                blinded_b64: None,
            });
        }
        Err(()) => {
            return Err(json_error(
                StatusCode::BAD_REQUEST,
                "Sora-Req-Blinded-CID header must occur at most once",
            ));
        }
    };
    let blinded_str = raw_blinded.to_str().map_err(|_| {
        json_error(
            StatusCode::BAD_REQUEST,
            "Sora-Req-Blinded-CID header must contain ASCII data",
        )
    })?;
    let trimmed = blinded_str.trim();
    if trimmed.is_empty() {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "Sora-Req-Blinded-CID header must not be empty",
        ));
    }
    let decoded = URL_SAFE_NO_PAD.decode(trimmed.as_bytes()).map_err(|err| {
        json_error(
            StatusCode::BAD_REQUEST,
            format!("invalid Sora-Req-Blinded-CID header: {err}"),
        )
    })?;
    if decoded.len() != BLINDED_CID_LEN {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            format!("Sora-Req-Blinded-CID must decode to {BLINDED_CID_LEN} bytes"),
        ));
    }
    let blinded_array: [u8; BLINDED_CID_LEN] = decoded
        .as_slice()
        .try_into()
        .expect("length checked above; qed");
    let nonce_header = single_header_value(headers, HEADER_SORA_REQ_NONCE).map_err(|()| {
        json_error(
            StatusCode::BAD_REQUEST,
            "Sora-Req-Nonce header must occur at most once",
        )
    })?;
    if let Some(nonce_header) = nonce_header {
        nonce_header.to_str().map_err(|_| {
            json_error(
                StatusCode::BAD_REQUEST,
                "Sora-Req-Nonce header must contain ASCII data",
            )
        })?;
    }
    let epoch_header = match single_header_value(headers, HEADER_SORA_REQ_SALT_EPOCH) {
        Ok(Some(value)) => value,
        Ok(None) => {
            return Err(json_error(
                StatusCode::PRECONDITION_REQUIRED,
                "Sora-Req-Salt-Epoch header is required when requesting by blinded CID",
            ));
        }
        Err(()) => {
            return Err(json_error(
                StatusCode::BAD_REQUEST,
                "Sora-Req-Salt-Epoch header must occur exactly once",
            ));
        }
    };
    let epoch_str = epoch_header.to_str().map_err(|_| {
        json_error(
            StatusCode::BAD_REQUEST,
            "Sora-Req-Salt-Epoch header must contain ASCII digits",
        )
    })?;
    let epoch = epoch_str.trim().parse::<u32>().map_err(|_| {
        json_error(
            StatusCode::BAD_REQUEST,
            "Sora-Req-Salt-Epoch header must be an unsigned integer",
        )
    })?;
    let resolver = state.blinded_resolver().ok_or_else(|| {
        json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "blinded CID support is not configured on this gateway",
        )
    })?;
    let storage = state
        .sorafs_node
        .storage()
        .ok_or_else(storage_disabled_response)?;
    let manifests = storage.manifests();
    let manifest_id = match resolver.resolve_manifest_id(&manifests, epoch, &blinded_array) {
        Ok(Some(id)) => id,
        Ok(None) => {
            return Err(json_error(
                StatusCode::NOT_FOUND,
                "no manifest matches the supplied blinded CID",
            ));
        }
        Err(crate::sorafs::BlindedResolveError::UnknownEpoch(missing_epoch)) => {
            return Err(json_error(
                StatusCode::PRECONDITION_REQUIRED,
                format!("salt epoch {missing_epoch} is not available on this gateway"),
            ));
        }
    };
    if !manifest_param.is_empty()
        && manifest_param != BLINDED_PATH_PLACEHOLDER
        && manifest_param != manifest_id
    {
        return Err(json_error(
            StatusCode::CONFLICT,
            "manifest identifier in the path does not match the blinded CID",
        ));
    }
    Ok(ManifestResolution {
        manifest_id,
        blinded_b64: Some(trimmed.to_owned()),
    })
}
fn resolve_manifest_storage_id(
    state: &SharedAppState,
    manifest_reference: &str,
) -> Result<String, Response> {
    let reference = manifest_reference.trim();
    if reference.is_empty() {
        return Err(json_error(
            StatusCode::BAD_REQUEST,
            "manifest_id_hex must not be empty",
        ));
    }
    let storage = state
        .sorafs_node
        .storage()
        .ok_or_else(storage_disabled_response)?;
    let manifests = storage.manifests();
    if let Some(stored) = manifests
        .iter()
        .find(|stored| stored.manifest_id().eq_ignore_ascii_case(reference))
    {
        return Ok(stored.manifest_id().to_owned());
    }
    if let Ok(cid_bytes) = hex::decode(reference)
        && let Some(stored) = manifests
            .iter()
            .find(|stored| stored.manifest_cid() == cid_bytes.as_slice())
    {
        return Ok(stored.manifest_id().to_owned());
    }
    Err(storage_backend_error(
        StorageBackendError::ManifestNotFound {
            manifest_id: reference.to_owned(),
        },
    ))
}
fn gateway_client_fingerprint(
    remote: SocketAddr,
    headers: &HeaderMap,
    _trusted_proxies: &[crate::limits::IpNet],
) -> ClientFingerprint {
    let effective_ip = crate::limits::effective_remote_ip(headers, Some(remote.ip()))
        .unwrap_or_else(|| remote.ip());
    ClientFingerprint::from_identifier(&effective_ip.to_string())
}
#[allow(clippy::result_large_err)]
fn enforce_authoritative_public_discovery_pre_read(
    state: &SharedAppState,
    headers: &HeaderMap,
    cid_bytes: &[u8],
    remote: SocketAddr,
) -> Result<(), Response> {
    let fingerprint = gateway_client_fingerprint(remote, headers, &state.trusted_proxy_nets);
    let mut context = RequestContext::new(&fingerprint, SystemTime::now(), Instant::now())
        .with_content_cid(cid_bytes)
        .with_remote_addr(remote);
    if let Some(host) = headers
        .get(header::HOST)
        .and_then(|value| value.to_str().ok())
        .and_then(CanonicalHost::parse_authority)
    {
        context = context.with_canonical_host(host);
    }
    if let Some(region) = parse_trusted_gateway_region(headers, remote, &state.trusted_proxy_nets) {
        context = context.with_region(region);
    }
    if let Some(ttl) = parse_cache_ttl(headers) {
        context = context.with_cache_ttl_secs(ttl);
    }
    if let Some(policy) = &state.sorafs_gateway_policy {
        match policy.evaluate_rate_only(&context) {
            PolicyDecision::Allow => {}
            PolicyDecision::Deny(violation) => {
                #[cfg(feature = "telemetry")]
                {
                    let (reason, detail) = violation.telemetry_labels();
                    state.telemetry.with_metrics(|metrics| {
                        metrics.record_sorafs_gar_violation(reason, detail);
                    });
                }
                state.publish_gar_violation_event(&context, &violation);
                let (policy_reason, policy_detail) = violation.telemetry_labels();
                warn!(
                    policy_reason,
                    policy_detail, "gateway policy denied authoritative public discovery request"
                );
                return Err(gateway_policy_violation_response(violation));
            }
        }
    }
    enforce_governed_gateway_compliance_for_cid(state, cid_bytes)
}
#[allow(clippy::result_large_err)]
fn enforce_gateway_policy_for_request(
    state: &SharedAppState,
    headers: &HeaderMap,
    manifest: &StoredManifest,
    provider_id: Option<[u8; 32]>,
    remote: SocketAddr,
    local_manifest_validated: bool,
) -> Result<(), Response> {
    let provider_id = provider_id.ok_or_else(|| {
        record_gateway_compliance_serving_failure(state, "unavailable");
        gateway_compliance_unavailable_response()
    })?;
    let fingerprint = gateway_client_fingerprint(remote, headers, &state.trusted_proxy_nets);
    let now = SystemTime::now();
    let monotonic_now = Instant::now();
    let pin_record = state
        .state
        .view()
        .world()
        .pin_manifests()
        .get(&ManifestDigest::new(*manifest.manifest_digest()))
        .cloned();
    let mut context = RequestContext::new(&fingerprint, now, monotonic_now)
        .with_manifest_digest(manifest.manifest_digest())
        .with_content_cid(manifest.manifest_cid())
        .with_manifest_envelope(
            local_manifest_validated || manifest_envelope_valid(headers, pin_record.as_ref()),
        )
        .with_remote_addr(remote);
    if let Some(host) = headers
        .get(header::HOST)
        .and_then(|value| value.to_str().ok())
        .and_then(CanonicalHost::parse_authority)
    {
        context = context.with_canonical_host(host);
    }
    if let Some(region) = parse_trusted_gateway_region(headers, remote, &state.trusted_proxy_nets) {
        context = context.with_region(region);
    }
    if let Some(ttl) = parse_cache_ttl(headers) {
        context = context.with_cache_ttl_secs(ttl);
    }
    context = context.with_provider_id(&provider_id);
    match state.evaluate_gateway_policy(context) {
        Ok(()) => enforce_governed_gateway_compliance_for_subjects(
            state,
            manifest.manifest_digest(),
            manifest.manifest_cid(),
            provider_id,
            None,
        ),
        Err(violation) => {
            let (policy_reason, policy_detail) = violation.telemetry_labels();
            warn!(
                policy_reason,
                policy_detail, "gateway policy denied request"
            );
            Err(gateway_policy_violation_response(violation))
        }
    }
}
fn authoritative_sorafs_provider_id(state: &SharedAppState) -> Result<[u8; 32], Response> {
    if let Some(provider_id) = state.sorafs_node.capacity_usage().provider_id {
        return Ok(provider_id);
    }
    #[cfg(test)]
    if let Some(provider_id) = state.sorafs_gateway_test_provider_id {
        return Ok(provider_id);
    }
    record_gateway_compliance_serving_failure(state, "unavailable");
    Err(gateway_compliance_unavailable_response())
}
fn enforce_governed_gateway_compliance_for_subjects(
    state: &SharedAppState,
    manifest_digest: &[u8; 32],
    cid_bytes: &[u8],
    provider_id: [u8; 32],
    source_url: Option<&str>,
) -> Result<(), Response> {
    let controller = state
        .sorafs_gateway_compliance_controller
        .as_ref()
        .ok_or_else(|| {
            record_gateway_compliance_serving_failure(state, "unavailable");
            gateway_compliance_unavailable_response()
        })?;
    let observed_at_unix = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|_| {
            warn!("gateway compliance serving clock is before the Unix epoch");
            record_gateway_compliance_serving_failure(state, "unavailable");
            gateway_compliance_unavailable_response()
        })?
        .as_secs();
    let manifest_digest = hex::encode(manifest_digest);
    evaluate_governed_gateway_compliance_subject(
        state,
        controller,
        observed_at_unix,
        GatewayComplianceSubjectKindV1::ManifestDigest,
        &manifest_digest,
    )?;
    let cid = canonical_lower_base32_cid(cid_bytes);
    evaluate_governed_gateway_compliance_subject(
        state,
        controller,
        observed_at_unix,
        GatewayComplianceSubjectKindV1::Cid,
        &cid,
    )?;
    let provider = hex::encode(provider_id);
    evaluate_governed_gateway_compliance_subject(
        state,
        controller,
        observed_at_unix,
        GatewayComplianceSubjectKindV1::Provider,
        &provider,
    )?;
    if let Some(source_url) = source_url {
        evaluate_governed_gateway_compliance_subject(
            state,
            controller,
            observed_at_unix,
            GatewayComplianceSubjectKindV1::Url,
            source_url,
        )?;
    }
    Ok(())
}
fn enforce_governed_gateway_compliance_for_cid(
    state: &SharedAppState,
    cid_bytes: &[u8],
) -> Result<(), Response> {
    let controller = state
        .sorafs_gateway_compliance_controller
        .as_ref()
        .ok_or_else(|| {
            record_gateway_compliance_serving_failure(state, "unavailable");
            gateway_compliance_unavailable_response()
        })?;
    let observed_at_unix = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|_| {
            record_gateway_compliance_serving_failure(state, "unavailable");
            gateway_compliance_unavailable_response()
        })?
        .as_secs();
    let cid = canonical_lower_base32_cid(cid_bytes);
    evaluate_governed_gateway_compliance_subject(
        state,
        controller,
        observed_at_unix,
        GatewayComplianceSubjectKindV1::Cid,
        &cid,
    )
}
fn evaluate_governed_gateway_compliance_subject(
    state: &SharedAppState,
    controller: &GatewayComplianceController,
    observed_at_unix: u64,
    kind: GatewayComplianceSubjectKindV1,
    subject: &str,
) -> Result<(), Response> {
    match controller.evaluate_serving(kind, subject, observed_at_unix) {
        Ok(decision) => {
            let subject_kind = gateway_compliance_subject_kind_label(kind);
            let disposition = gateway_compliance_disposition_label(decision.disposition);
            let source = gateway_compliance_decision_source_label(decision.source);
            state.telemetry.with_metrics(|metrics| {
                metrics.record_sorafs_gateway_compliance_serving_decision(
                    subject_kind,
                    disposition,
                    source,
                );
                metrics.record_sorafs_gateway_compliance_serving_catalog(
                    Some(decision.catalog_sequence),
                    Some(decision.catalog_valid_until_unix),
                    true,
                );
            });
            gateway_compliance_decision_response(state, decision)
        }
        Err(error) => {
            record_gateway_compliance_serving_failure(
                state,
                gateway_compliance_serving_error_class(&error),
            );
            warn!("governed gateway compliance serving evaluation failed closed");
            Err(gateway_compliance_unavailable_response())
        }
    }
}
fn gateway_compliance_subject_kind_label(kind: GatewayComplianceSubjectKindV1) -> &'static str {
    match kind {
        GatewayComplianceSubjectKindV1::Provider => "provider",
        GatewayComplianceSubjectKindV1::ManifestDigest => "manifest_digest",
        GatewayComplianceSubjectKindV1::Cid => "cid",
        GatewayComplianceSubjectKindV1::Url => "url",
    }
}
fn gateway_compliance_disposition_label(disposition: GatewayComplianceDisposition) -> &'static str {
    match disposition {
        GatewayComplianceDisposition::Allow => "allow",
        GatewayComplianceDisposition::Deny => "deny",
    }
}
fn gateway_compliance_decision_source_label(
    source: GatewayComplianceDecisionSource,
) -> &'static str {
    match source {
        GatewayComplianceDecisionSource::NoMatch => "no_match",
        GatewayComplianceDecisionSource::Baseline => "baseline",
        GatewayComplianceDecisionSource::AcceptedAppeal => "accepted_appeal",
        GatewayComplianceDecisionSource::LegalSafetyHold => "legal_safety_hold",
    }
}
fn gateway_compliance_serving_error_class(error: &GatewayComplianceError) -> &'static str {
    match error {
        GatewayComplianceError::CatalogNotFresh => "expired_catalog",
        GatewayComplianceError::NoServingCatalog => "unavailable",
        GatewayComplianceError::Persistence(_)
        | GatewayComplianceError::InvalidCheckpoint(_)
        | GatewayComplianceError::LeaseHeld
        | GatewayComplianceError::CheckpointConflict
        | GatewayComplianceError::StatePoisoned => "persistence",
        _ => "internal",
    }
}
fn record_gateway_compliance_serving_failure(state: &SharedAppState, class: &'static str) {
    state.telemetry.with_metrics(|metrics| {
        metrics.mark_sorafs_gateway_compliance_unready();
        metrics.record_sorafs_gateway_compliance_failure("serving", class);
    });
}
fn gateway_compliance_decision_response(
    state: &SharedAppState,
    decision: GatewayComplianceDecision,
) -> Result<(), Response> {
    let denial = match canonical_gateway_compliance_denial(&decision) {
        Ok(denial) => denial,
        Err(reason) => {
            record_gateway_compliance_serving_failure(state, "internal");
            warn!(
                reason,
                "governed gateway compliance returned an invalid serving decision"
            );
            return Err(gateway_compliance_unavailable_response());
        }
    };
    let Some((source, catalog_digest)) = denial else {
        return Ok(());
    };
    #[cfg(feature = "telemetry")]
    state.telemetry.with_metrics(|metrics| {
        metrics.record_sorafs_gar_violation("gateway_compliance", source);
    });
    #[cfg(not(feature = "telemetry"))]
    let _ = state;
    Err(gateway_compliance_denial_http_response(
        source,
        catalog_digest,
    ))
}
fn canonical_gateway_compliance_denial(
    decision: &GatewayComplianceDecision,
) -> Result<Option<(&'static str, [u8; 32])>, &'static str> {
    match (decision.disposition, decision.source) {
        (
            GatewayComplianceDisposition::Allow,
            GatewayComplianceDecisionSource::NoMatch
            | GatewayComplianceDecisionSource::AcceptedAppeal,
        ) => Ok(None),
        (
            GatewayComplianceDisposition::Deny,
            GatewayComplianceDecisionSource::Baseline
            | GatewayComplianceDecisionSource::LegalSafetyHold,
        ) => {
            let source = gateway_compliance_decision_source_label(decision.source);
            let catalog_digest = decision
                .catalog_digest
                .ok_or("denial_missing_catalog_digest")?;
            Ok(Some((source, catalog_digest)))
        }
        (GatewayComplianceDisposition::Allow, _) => Err("allow_with_denial_source"),
        (GatewayComplianceDisposition::Deny, _) => Err("deny_with_allow_source"),
    }
}
fn gateway_compliance_denial_http_response(source: &str, catalog_digest: [u8; 32]) -> Response {
    let body = json_object(vec![
        json_entry("error", Value::from("gateway_compliance_denied")),
        json_entry("source", Value::from(source)),
        json_entry(
            "catalog_digest_hex",
            Value::from(hex::encode(catalog_digest)),
        ),
    ]);
    let mut response = (StatusCode::UNAVAILABLE_FOR_LEGAL_REASONS, JsonBody(body)).into_response();
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static("private, no-store, max-age=0"),
    );
    response
}
fn gateway_compliance_unavailable_response() -> Response {
    let body = json_object(vec![
        json_entry("error", Value::from("gateway_compliance_unavailable")),
        json_entry(
            "message",
            Value::from("the governed gateway compliance serving policy is unavailable"),
        ),
    ]);
    let mut response = (StatusCode::SERVICE_UNAVAILABLE, JsonBody(body)).into_response();
    response.headers_mut().insert(
        CACHE_CONTROL,
        HeaderValue::from_static("private, no-store, max-age=0"),
    );
    response
}
fn canonical_lower_base32_cid(bytes: &[u8]) -> String {
    const ALPHABET: &[u8; 32] = b"abcdefghijklmnopqrstuvwxyz234567";
    let mut encoded = String::with_capacity(1 + bytes.len().saturating_mul(8).div_ceil(5));
    encoded.push('b');
    let mut accumulator = 0_u16;
    let mut bits = 0_u8;
    for byte in bytes {
        accumulator = (accumulator << 8) | u16::from(*byte);
        bits += 8;
        while bits >= 5 {
            bits -= 5;
            let index = usize::from((accumulator >> bits) & 0x1f);
            encoded.push(char::from(ALPHABET[index]));
        }
        accumulator = if bits == 0 {
            0
        } else {
            accumulator & ((1_u16 << bits) - 1)
        };
    }
    if bits != 0 {
        let index = usize::from((accumulator << (5 - bits)) & 0x1f);
        encoded.push(char::from(ALPHABET[index]));
    }
    encoded
}
fn gateway_policy_violation_response(violation: PolicyViolation) -> Response {
    match violation {
        PolicyViolation::ManifestEnvelopeMissing => {
            let body = json_object(vec![
                json_entry("error", Value::from("manifest_envelope_required")),
                json_entry(
                    "message",
                    Value::from("manifest envelope must be attached to the request"),
                ),
            ]);
            (StatusCode::PRECONDITION_REQUIRED, JsonBody(body)).into_response()
        }
        PolicyViolation::MissingProviderId => {
            let body = json_object(vec![
                json_entry("error", Value::from("provider_id_missing")),
                json_entry(
                    "message",
                    Value::from("stream token provider identifier is required"),
                ),
            ]);
            (StatusCode::PRECONDITION_REQUIRED, JsonBody(body)).into_response()
        }
        PolicyViolation::AdmissionUnavailable => {
            let body = json_object(vec![
                json_entry("error", Value::from("admission_unavailable")),
                json_entry(
                    "message",
                    Value::from("gateway admission registry is unavailable"),
                ),
            ]);
            (StatusCode::PRECONDITION_FAILED, JsonBody(body)).into_response()
        }
        PolicyViolation::ProviderNotAdmitted { provider_id } => {
            let body = json_object(vec![
                json_entry("error", Value::from("provider_not_admitted")),
                json_entry("provider_id_hex", Value::from(hex::encode(provider_id))),
                json_entry(
                    "message",
                    Value::from("provider is not admitted according to governance records"),
                ),
            ]);
            (StatusCode::PRECONDITION_FAILED, JsonBody(body)).into_response()
        }
        PolicyViolation::RateLimited(error) => {
            let mut headers = HeaderMap::new();
            let (status, code, retry_after) = match error {
                RateLimitError::Limited { retry_after } => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "rate_limited",
                    Some(retry_after),
                ),
                RateLimitError::Banned { retry_after } => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "temporarily_banned",
                    retry_after,
                ),
            };
            if let Some(duration) = retry_after {
                let seconds = duration.as_secs().max(1);
                headers.insert(
                    RETRY_AFTER,
                    HeaderValue::from_str(&seconds.to_string())
                        .unwrap_or_else(|_| HeaderValue::from_static("1")),
                );
            }
            let body = json_object(vec![
                json_entry("error", Value::from(code)),
                json_entry(
                    "message",
                    Value::from("gateway rejected the request due to rate limiting"),
                ),
            ]);
            (status, headers, JsonBody(body)).into_response()
        }
    }
}
