    #[test]
    fn ensure_chunk_alignment_accepts_aligned_range() {
        let temp_dir = tempdir().expect("temp dir");
        let physical_parent = temp_dir
            .path()
            .canonicalize()
            .expect("physical temp parent");
        let backend = StorageBackend::new(
            StorageConfig::builder()
                .enabled(true)
                .data_dir(physical_parent.join("storage"))
                .build(),
        )
        .expect("backend init");
        let payload = b"deterministic payload for alignment";
        let plan = CarBuildPlan::single_file(payload).expect("plan");
        let car_stats = canonical_fixture_car_stats(&plan, payload);
        let manifest = ManifestBuilder::new()
            .root_cid(car_stats.root_cids[0].clone())
            .dag_codec(DagCodecId(car_stats.dag_codec))
            .chunking_from_profile(
                sorafs_chunker::ChunkProfile::DEFAULT,
                BLAKE3_256_MULTIHASH_CODE,
            )
            .chunk_digest_sha3_256(compute_chunk_plan_digest_sha3(&plan.chunks))
            .por_root(
                sorafs_car::compute_por_root(payload, &plan)
                    .expect("derive canonical alignment fixture PoR root"),
            )
            .content_length(plan.content_length)
            .car_digest(car_stats.car_archive_digest.into())
            .car_size(car_stats.car_size)
            .pin_policy(PinPolicy::default())
            .build()
            .expect("manifest");
        let mut reader = &payload[..];
        let manifest_id = backend
            .ingest_manifest(&manifest, &plan, &mut reader)
            .expect("ingest");
        let stored = backend.manifest(&manifest_id).expect("stored manifest");
        let range = ByteRange {
            start: 0,
            end_inclusive: stored.content_length().saturating_sub(1),
        };
        let chunk_count = ensure_chunk_alignment(&stored, range).expect("aligned range");
        assert!(chunk_count > 0);
    }
