fn advert_ingest_response(
    status: &str,
    fingerprint: &[u8; 32],
    warnings: &[AdvertWarning],
) -> Response {
    let warnings_json = warnings
        .iter()
        .map(|warning| Value::String(warning.as_str().to_string()))
        .collect::<Vec<_>>();
    let response = json_object(vec![
        json_entry("status", status.to_string()),
        json_entry("fingerprint_hex", fingerprint.encode_hex::<String>()),
        json_entry("warnings", Value::Array(warnings_json)),
    ]);
    (StatusCode::OK, JsonBody(response)).into_response()
}
fn snapshot_to_json(snapshot: CapacitySnapshot, limit: usize) -> Result<Value, json::Error> {
    let declaration_count = snapshot.declaration_count;
    let ledger_count = snapshot.fee_ledger_count;
    let credit_count = snapshot.credit_ledger_count;
    let dispute_count = snapshot.dispute_count;
    let truncated_declarations = declaration_count > limit;
    let truncated_fee_ledger = ledger_count > limit;
    let truncated_credit_ledger = credit_count > limit;
    let truncated_disputes = dispute_count > limit;
    let mut declarations_json = Vec::with_capacity(declaration_count.min(limit));
    for declaration in snapshot.declarations.into_iter().take(limit) {
        declarations_json.push(declaration.into_json()?);
    }
    let mut ledger_json = Vec::with_capacity(ledger_count.min(limit));
    for entry in snapshot.fee_ledger.into_iter().take(limit) {
        ledger_json.push(entry.into_json()?);
    }
    let mut credit_json = Vec::with_capacity(credit_count.min(limit));
    for entry in snapshot.credit_ledger.into_iter().take(limit) {
        credit_json.push(entry.into_json()?);
    }
    let mut disputes_json = Vec::with_capacity(dispute_count.min(limit));
    for dispute in snapshot.disputes.into_iter().take(limit) {
        disputes_json.push(dispute.into_json()?);
    }
    let returned_declaration_count = declarations_json.len();
    let returned_ledger_count = ledger_json.len();
    let returned_credit_ledger_count = credit_json.len();
    let returned_dispute_count = disputes_json.len();
    Ok(json_object(vec![
        json_entry("declaration_count", declaration_count as u64),
        json_entry(
            "returned_declaration_count",
            returned_declaration_count as u64,
        ),
        json_entry("declarations", Value::Array(declarations_json)),
        json_entry("ledger_count", ledger_count as u64),
        json_entry("returned_ledger_count", returned_ledger_count as u64),
        json_entry("fee_ledger", Value::Array(ledger_json)),
        json_entry("credit_ledger_count", credit_count as u64),
        json_entry(
            "returned_credit_ledger_count",
            returned_credit_ledger_count as u64,
        ),
        json_entry("credit_ledger", Value::Array(credit_json)),
        json_entry("dispute_count", dispute_count as u64),
        json_entry("returned_dispute_count", returned_dispute_count as u64),
        json_entry("disputes", Value::Array(disputes_json)),
        json_entry("limit", limit as u64),
        json_entry("truncated_declarations", truncated_declarations),
        json_entry("truncated_fee_ledger", truncated_fee_ledger),
        json_entry("truncated_credit_ledger", truncated_credit_ledger),
        json_entry("truncated_disputes", truncated_disputes),
    ]))
}
fn pin_projection_with_attestation<T>(
    state: &SharedAppState,
    project: impl FnOnce(&iroha_core::state::WorldView<'_>) -> Result<T, PinRegistryError>,
) -> ApiResult<(Value, T)> {
    // The full state view retries across concurrent commits, keeping the world
    // projection, height, block hash, and chain id on one committed generation.
    let view = state.state.view();
    let block_hash = view.latest_block_hash();
    let height = u64::try_from(view.height()).unwrap_or(u64::MAX);
    let attestation = match build_attestation_value(height, block_hash.as_ref(), &view.chain_id) {
        Ok(value) => value,
        Err(err) => {
            error!(?err, "failed to serialize registry attestation metadata");
            return Err(json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to serialize registry attestation metadata",
            )
            .into());
        }
    };
    match project(view.world()) {
        Ok(projection) => Ok((attestation, projection)),
        Err(err) => {
            error!(?err, "failed to collect pin registry projection");
            Err(json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "failed to collect pin registry snapshot",
            )
            .into())
        }
    }
}
fn parse_manifest_digest_hex(hex_str: &str) -> ApiResult<[u8; 32]> {
    let digest = parse_canonical_hex_fixed::<32>(hex_str, "manifest digest")
        .map_err(|error| ResponseError::from(json_error(StatusCode::BAD_REQUEST, error)))?;
    if digest == [0; 32] {
        return Err(ResponseError::from(json_error(
            StatusCode::BAD_REQUEST,
            "manifest digest must be non-zero",
        )));
    }
    Ok(digest)
}
fn storage_stored_file_dto(file: &StoredFileRecord) -> StorageStoredFileDto {
    StorageStoredFileDto {
        path: file.path.clone(),
        offset: file.offset,
        size: file.size,
        first_chunk: file.first_chunk as u64,
        chunk_count: file.chunk_count as u64,
    }
}
fn chunk_fetch_spec_json(spec: &ChunkFetchSpec) -> Value {
    let mut obj = Map::new();
    obj.insert("chunk_index".into(), Value::from(spec.chunk_index as u64));
    obj.insert("offset".into(), Value::from(spec.offset));
    obj.insert("length".into(), Value::from(spec.length as u64));
    obj.insert(
        "digest_blake3".into(),
        Value::from(hex::encode(spec.digest)),
    );
    Value::Object(obj)
}
fn normalize_limit(limit: Option<u32>) -> usize {
    limit.unwrap_or(DEFAULT_LIST_LIMIT as u32) as usize
}
fn normalize_moderation_read_limit(limit: Option<u32>) -> usize {
    limit.unwrap_or(DEFAULT_LIST_LIMIT as u32) as usize
}
fn limit_governance_readback_values(mut entries: Vec<Value>, limit: usize) -> (Vec<Value>, bool) {
    let truncated = entries.len() > limit;
    entries.truncate(limit);
    (entries, truncated)
}
fn normalize_offset(offset: Option<u32>, total: usize) -> usize {
    (offset.unwrap_or(0) as usize).min(total)
}
impl ReplicationStatusFilter {
    fn matches_record(self, status: ReplicationOrderStatus) -> bool {
        matches!(
            (self, status),
            (Self::Pending, ReplicationOrderStatus::Pending)
                | (Self::Completed, ReplicationOrderStatus::Completed(_))
                | (Self::Cancelled, ReplicationOrderStatus::Cancelled(_))
                | (Self::Expired, ReplicationOrderStatus::Expired(_))
        )
    }
}
fn parse_replication_status_filter(value: &str) -> Option<ReplicationStatusFilter> {
    match value {
        "pending" => Some(ReplicationStatusFilter::Pending),
        "completed" => Some(ReplicationStatusFilter::Completed),
        "cancelled" => Some(ReplicationStatusFilter::Cancelled),
        "expired" => Some(ReplicationStatusFilter::Expired),
        _ => None,
    }
}
fn build_attestation_value(
    height: u64,
    block_hash: Option<&HashOf<BlockHeader>>,
    chain_id: &ChainId,
) -> Result<Value, json::Error> {
    let mut map = Map::new();
    map.insert("block_height".into(), json::to_value(&height)?);
    map.insert(
        "block_hash_hex".into(),
        block_hash
            .map(|hash| Value::String(hex::encode(hash.as_ref().as_ref())))
            .unwrap_or(Value::Null),
    );
    map.insert("chain_id".into(), Value::String(chain_id.to_string()));
    Ok(Value::Object(map))
}
fn json_error(status: StatusCode, message: impl Into<String>) -> Response {
    let response = json_object(vec![json_entry("error", message.into())]);
    (status, JsonBody(response)).into_response()
}
fn feature_disabled(message: &str) -> Response {
    json_error(StatusCode::NOT_FOUND, message)
}
fn storage_disabled_response() -> Response {
    feature_disabled("sorafs storage API is not enabled on this node")
}
fn parse_canonical_hex_fixed<const N: usize>(input: &str, field: &str) -> Result<[u8; N], String> {
    let parsed = parse_hex_fixed::<N>(input, field)?;
    if input != hex::encode(parsed) {
        return Err(format!(
            "{field} must use canonical lowercase hexadecimal without surrounding whitespace"
        ));
    }
    Ok(parsed)
}
fn parse_hex_fixed<const N: usize>(input: &str, field: &str) -> Result<[u8; N], String> {
    let trimmed = input.trim();
    if trimmed.len() != N * 2 {
        return Err(format!("{field} must be {} hexadecimal characters", N * 2));
    }
    let mut out = [0u8; N];
    hex::decode_to_slice(trimmed, &mut out).map_err(|err| format!("invalid {field}: {err}"))?;
    Ok(out)
}
fn record_storage_metrics(state: &SharedAppState) {
    #[cfg(feature = "telemetry")]
    {
        if let Some(provider_id) = state.sorafs_node.capacity_usage().provider_id {
            let provider_hex = hex::encode(provider_id);
            let schedulers = state.sorafs_node.schedulers();
            let snapshot = schedulers.telemetry_snapshot();
            state.telemetry.with_metrics(|metrics| {
                metrics.record_sorafs_storage(
                    &provider_hex,
                    snapshot.bytes_used,
                    snapshot.bytes_capacity,
                    snapshot.provider_ingest_inflight as u64,
                    snapshot.fetch_inflight as u64,
                    snapshot.fetch_bytes_per_sec,
                    snapshot.por_inflight as u64,
                    snapshot.por_samples_success,
                    snapshot.por_samples_failed,
                );
                for status in state.sorafs_node.por_ingestion_overview() {
                    let manifest_hex = hex::encode(status.manifest_digest);
                    let entry_provider_hex = hex::encode(status.provider_id);
                    metrics.record_sorafs_por_ingestion_backlog(
                        &entry_provider_hex,
                        &manifest_hex,
                        status.pending_challenges,
                    );
                    metrics.record_sorafs_por_ingestion_failures(
                        &entry_provider_hex,
                        &manifest_hex,
                        status.failures_total,
                    );
                }
            });
        }
    }
    #[cfg(not(feature = "telemetry"))]
    let _ = state;
}
fn node_storage_error_response(err: NodeStorageError) -> Response {
    match err {
        NodeStorageError::Disabled => storage_disabled_response(),
        NodeStorageError::Storage(inner) => storage_backend_error(inner),
        NodeStorageError::Scheduler(inner) => scheduler_admission_error_response(inner),
    }
}
fn scheduler_admission_error_response(
    err: sorafs_node::scheduler::SchedulerAdmissionError,
) -> Response {
    use sorafs_node::scheduler::SchedulerAdmissionError;
    if matches!(err, SchedulerAdmissionError::StateUnavailable { .. }) {
        error!(?err, "SoraFS storage scheduler state unavailable");
        let mut response = json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "SoraFS storage scheduler is temporarily unavailable",
        );
        response
            .headers_mut()
            .insert(RETRY_AFTER, HeaderValue::from_static("1"));
        return response;
    }
    let retry_after_secs = match err {
        SchedulerAdmissionError::RateLimited { retry_after, .. } => {
            u64::try_from(retry_after.as_millis().saturating_add(999) / 1_000)
                .unwrap_or(u64::MAX)
                .max(1)
        }
        _ => 1,
    };
    error!(?err, "SoraFS storage scheduler refused work");
    let mut response = json_error(
        StatusCode::TOO_MANY_REQUESTS,
        "SoraFS storage scheduler is busy; retry later",
    );
    if let Ok(value) = HeaderValue::from_str(&retry_after_secs.to_string()) {
        response.headers_mut().insert(RETRY_AFTER, value);
    }
    response
}
fn storage_backend_error(err: StorageBackendError) -> Response {
    match err {
        StorageBackendError::ManifestExists { manifest_id } => json_error(
            StatusCode::CONFLICT,
            format!("manifest {manifest_id} already stored"),
        ),
        StorageBackendError::CapacityExceeded {
            required,
            available,
        } => json_error(
            StatusCode::BAD_REQUEST,
            format!(
                "storage capacity exceeded (required {required} bytes, available {available} bytes)"
            ),
        ),
        StorageBackendError::PinLimitReached { limit } => json_error(
            StatusCode::BAD_REQUEST,
            format!("storage pin limit of {limit} manifests reached"),
        ),
        StorageBackendError::ManifestNotFound { manifest_id } => json_error(
            StatusCode::NOT_FOUND,
            format!("manifest {manifest_id} not found"),
        ),
        StorageBackendError::PayloadUnavailable { .. } => json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "manifest payload is quarantined pending verified repair",
        ),
        StorageBackendError::ManifestRetirementInProgress { manifest_id } => json_error(
            StatusCode::CONFLICT,
            format!("manifest {manifest_id} retirement is already in progress"),
        ),
        StorageBackendError::ChunkNotFound {
            manifest_id,
            digest_hex,
        } => json_error(
            StatusCode::NOT_FOUND,
            format!("chunk {digest_hex} not found in manifest {manifest_id}"),
        ),
        StorageBackendError::RangeOutOfBounds {
            offset,
            len,
            content_length,
        } => json_error(
            StatusCode::BAD_REQUEST,
            format!(
                "requested range offset {offset} length {len} exceeds payload length {content_length}"
            ),
        ),
        StorageBackendError::ChunkDigestMismatch { chunk_index } => json_error(
            StatusCode::BAD_REQUEST,
            format!("chunk digest mismatch for chunk {chunk_index}"),
        ),
        StorageBackendError::PayloadLengthMismatch { expected, actual } => json_error(
            StatusCode::BAD_REQUEST,
            format!("payload length mismatch: expected {expected}, read {actual}"),
        ),
        StorageBackendError::UnsupportedManifestVersion { version } => json_error(
            StatusCode::BAD_REQUEST,
            format!("unsupported manifest version {version}"),
        ),
        StorageBackendError::ChunkProfileMismatch => json_error(
            StatusCode::BAD_REQUEST,
            "chunk profile mismatch between manifest and payload plan",
        ),
        request_error @ (StorageBackendError::PersistentArtifactTooLarge { .. }
        | StorageBackendError::PorCommitmentGeometryOverflow { .. }
        | StorageBackendError::AllocationGeometryOverflow { .. }
        | StorageBackendError::PorRootMismatch
        | StorageBackendError::ManifestChunkPlanDigestMismatch
        | StorageBackendError::CarArchiveReconstruction { .. }
        | StorageBackendError::ManifestCarArchiveDigestMismatch
        | StorageBackendError::ManifestCarSizeMismatch { .. }
        | StorageBackendError::ManifestDagCodecMismatch { .. }
        | StorageBackendError::PorSampleCountTooLarge { .. }
        | StorageBackendError::PdpTree(_)
        | StorageBackendError::PdpCommitment(_)
        | StorageBackendError::ManifestContentLengthMismatch) => json_error(
            StatusCode::BAD_REQUEST,
            format!("invalid storage request: {request_error}"),
        ),
        StorageBackendError::PdpTreeMemoryExceeded {
            required,
            available,
        } => json_error(
            StatusCode::BAD_REQUEST,
            format!(
                "PDP tree memory budget exceeded (required {required} bytes, available {available} bytes)"
            ),
        ),
        StorageBackendError::PdpUnavailable { manifest_id } => json_error(
            StatusCode::NOT_FOUND,
            format!("manifest {manifest_id} has no PDP commitment"),
        ),
        StorageBackendError::ChunkRoleLengthMismatch { expected, actual } => json_error(
            StatusCode::BAD_REQUEST,
            format!("chunk_roles length {actual} does not match chunk count {expected}"),
        ),
        StorageBackendError::RetentionMetadata(err) => json_error(
            StatusCode::BAD_REQUEST,
            format!("retention metadata invalid: {err}"),
        ),
        StorageBackendError::LayoutValueTooLarge { field, value, max } => json_error(
            StatusCode::BAD_REQUEST,
            format!("storage layout field {field} value {value} exceeds limit {max}"),
        ),
        StorageBackendError::InvalidFileLayout { reason } => json_error(
            StatusCode::BAD_REQUEST,
            format!("invalid storage file layout: {reason}"),
        ),
        StorageBackendError::StorageDirectoryInUse { .. } => json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "storage backend directory is already in use",
        ),
        durability_error @ (StorageBackendError::DurabilityUncertain { .. }
        | StorageBackendError::DurabilityPoisoned { .. }) => {
            error!(
                ?durability_error,
                "SoraFS storage backend fail-stopped after a durability failure"
            );
            json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "storage backend is unavailable pending durability recovery",
            )
        }
        state_error @ (StorageBackendError::UnsupportedIndexVersion { .. }
        | StorageBackendError::CorruptStorageState { .. }) => {
            error!(
                ?state_error,
                "SoraFS storage backend state failed integrity validation"
            );
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "storage backend state failed integrity validation",
            )
        }
        pdp_runtime_error @ (StorageBackendError::InvalidPdpSampleWindow { .. }
        | StorageBackendError::PdpWitness { .. }
        | StorageBackendError::InvalidSystemTime) => {
            error!(?pdp_runtime_error, "SoraFS storage backend PDP failure");
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "storage backend PDP operation failed",
            )
        }
        StorageBackendError::Io(err) => {
            error!(?err, "SoraFS storage backend I/O error");
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "storage backend I/O error",
            )
        }
        StorageBackendError::Norito(err) => {
            error!(?err, "SoraFS storage backend serialization error");
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "storage backend serialization error",
            )
        }
        StorageBackendError::ChunkStore(err) => {
            error!(?err, "SoraFS PoR store error");
            json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "storage backend PoR error",
            )
        }
    }
}
#[cfg(test)]
mod storage_backend_error_tests {
    use super::{
        NodeStorageError, RETRY_AFTER, StorageBackendError, node_storage_error_response,
        storage_backend_error,
    };
    use sorafs_manifest::retention::RetentionMetadataError;
    #[tokio::test]
    async fn quarantined_payload_is_unavailable_without_disclosing_manifest_metadata() {
        let response = storage_backend_error(StorageBackendError::PayloadUnavailable {
            manifest_id: "damaged-manifest".to_owned(),
        });
        assert_eq!(
            response.status(),
            axum::http::StatusCode::SERVICE_UNAVAILABLE
        );
        let bytes = axum::body::to_bytes(response.into_body(), 1024)
            .await
            .unwrap();
        let text = std::str::from_utf8(&bytes).unwrap();
        assert!(text.contains("quarantined"));
        assert!(!text.contains("damaged-manifest"));
    }
    use sorafs_node::scheduler::{FetchRateScope, SchedulerAdmissionError};
    use std::time::Duration;
    #[test]
    fn retention_metadata_maps_to_bad_request() {
        let err = StorageBackendError::RetentionMetadata(RetentionMetadataError::DuplicateKey {
            key: "sorafs.retention.deal_end_epoch".to_string(),
        });
        let response = storage_backend_error(err);
        assert_eq!(response.status(), super::StatusCode::BAD_REQUEST);
    }
    #[test]
    fn concurrent_manifest_retirement_maps_to_conflict() {
        let err = StorageBackendError::ManifestRetirementInProgress {
            manifest_id: "deadbeef".to_owned(),
        };
        let response = storage_backend_error(err);
        assert_eq!(response.status(), super::StatusCode::CONFLICT);
    }
    #[test]
    fn manifest_archive_binding_errors_map_to_bad_request() {
        for error in [
            StorageBackendError::ManifestChunkPlanDigestMismatch,
            StorageBackendError::CarArchiveReconstruction {
                reason: "fixture".to_owned(),
            },
            StorageBackendError::ManifestCarArchiveDigestMismatch,
            StorageBackendError::ManifestCarSizeMismatch {
                expected: 1,
                actual: 2,
            },
            StorageBackendError::ManifestDagCodecMismatch {
                expected: 0x55,
                actual: 0x71,
            },
        ] {
            assert_eq!(
                storage_backend_error(error).status(),
                super::StatusCode::BAD_REQUEST
            );
        }
    }
    #[test]
    fn storage_integrity_and_ownership_errors_map_to_server_failures() {
        let corrupt = storage_backend_error(StorageBackendError::CorruptStorageState {
            path: "/secret/storage/index.norito".to_owned(),
            reason: "tampered".to_owned(),
        });
        assert_eq!(corrupt.status(), super::StatusCode::INTERNAL_SERVER_ERROR);
        let in_use = storage_backend_error(StorageBackendError::StorageDirectoryInUse {
            path: "/secret/storage/.storage.lock".to_owned(),
        });
        assert_eq!(in_use.status(), super::StatusCode::SERVICE_UNAVAILABLE);
    }
    #[test]
    fn oversized_storage_layout_maps_to_bad_request() {
        let response = storage_backend_error(StorageBackendError::LayoutValueTooLarge {
            field: "chunk_count",
            value: usize::MAX,
            max: u64::from(u32::MAX),
        });
        assert_eq!(response.status(), super::StatusCode::BAD_REQUEST);
    }
    #[test]
    fn invalid_file_layout_maps_to_bad_request() {
        let response = storage_backend_error(StorageBackendError::InvalidFileLayout {
            reason: "out-of-bounds chunk range".to_owned(),
        });
        assert_eq!(response.status(), super::StatusCode::BAD_REQUEST);
    }
    #[test]
    fn durability_fail_stop_maps_to_opaque_service_unavailable() {
        let response = storage_backend_error(StorageBackendError::DurabilityPoisoned {
            reason: "/secret/storage/index.norito: injected failure".to_owned(),
        });
        assert_eq!(response.status(), super::StatusCode::SERVICE_UNAVAILABLE);
    }
    #[test]
    fn scheduler_refusal_maps_to_retryable_rate_limit() {
        let response = node_storage_error_response(NodeStorageError::Scheduler(
            SchedulerAdmissionError::RateLimited {
                scope: FetchRateScope::Global,
                retry_after: Duration::from_millis(1_001),
            },
        ));
        assert_eq!(response.status(), super::StatusCode::TOO_MANY_REQUESTS);
        assert_eq!(
            response
                .headers()
                .get(RETRY_AFTER)
                .expect("Retry-After header"),
            "2"
        );
    }
    #[test]
    fn poisoned_scheduler_state_maps_to_service_unavailable() {
        let response = node_storage_error_response(NodeStorageError::Scheduler(
            SchedulerAdmissionError::StateUnavailable {
                component: "fetch concurrency",
            },
        ));
        assert_eq!(response.status(), super::StatusCode::SERVICE_UNAVAILABLE);
        assert_eq!(
            response
                .headers()
                .get(RETRY_AFTER)
                .expect("Retry-After header"),
            "1"
        );
    }
}
