    #[test]
    fn replication_page_decodes_only_the_bounded_selection() {
        let state = make_state();
        let issuer = test_account();
        let manifest_digest = ManifestDigest::new([0x71; 32]);
        let manifest_root_cid = canonical_fixture_manifest_root_cid();
        let valid_id = ReplicationOrderId::new([0x11; 32]);
        let poisoned_id = ReplicationOrderId::new([0x22; 32]);
        let mut block = state.block(default_block_header());
        let mut tx = block.transaction();
        for (order_id, canonical_order) in [
            (
                valid_id,
                encode_replication_order_bytes(
                    &valid_id,
                    &manifest_digest,
                    &manifest_root_cid,
                    1,
                    10,
                ),
            ),
            (poisoned_id, vec![0xFF]),
        ] {
            tx.world_mut_for_testing()
                .replication_orders_mut_for_testing()
                .insert(
                    order_id,
                    ReplicationOrderRecord {
                        order_id,
                        manifest_digest,
                        manifest_root_cid: manifest_root_cid.clone(),
                        musubi_archive: None,
                        issued_by: issuer.clone(),
                        issued_epoch: 1,
                        deadline_epoch: 10,
                        canonical_order,
                        assignment_revision: 1,
                        provider_completions: Vec::new(),
                        status: ReplicationOrderStatus::Pending,
                    },
                );
        }
        tx.apply();
        block
            .commit_world_overlay_for_testing()
            .expect("commit replication page fixture");
        let view = state.view();
        let page = collect_replication_order_page(view.world(), 0, 1, |_| true)
            .expect("the selected valid order should decode");
        assert_eq!(page.total_count, 2);
        assert_eq!(page.orders.len(), 1);
        let projected = page.orders[0].to_json().expect("project selected order");
        let expected_id = hex::encode(valid_id.as_bytes());
        assert_eq!(
            projected.get("order_id_hex").and_then(Value::as_str),
            Some(expected_id.as_str())
        );
        assert!(
            collect_replication_order_page(view.world(), 1, 1, |_| true).is_err(),
            "the poisoned order must fail only when its page is selected"
        );
    }
    fn encode_replication_order_bytes_with_providers(
        order_id: &ReplicationOrderId,
        manifest_digest: &ManifestDigest,
        manifest_cid: &[u8],
        providers: Vec<[u8; 32]>,
        issued_epoch: u64,
        deadline_epoch: u64,
    ) -> Vec<u8> {
        let target_replicas =
            u16::try_from(providers.len()).expect("fixture provider count fits u16");
        let ingest_deadline_secs = u32::try_from(deadline_epoch.saturating_sub(issued_epoch))
            .expect("fixture deadline delta fits u32");
        let order = ReplicationOrderV1 {
            version: REPLICATION_ORDER_VERSION_V1,
            order_id: *order_id.as_bytes(),
            manifest_cid: manifest_cid.to_vec(),
            manifest_digest: *manifest_digest.as_bytes(),
            chunking_profile: "sorafs.sf1@1.0.0".to_owned(),
            target_replicas,
            assignments: providers
                .into_iter()
                .map(|provider_id| ReplicationAssignmentV1 {
                    provider_id,
                    slice_gib: 1,
                    lane: None,
                })
                .collect(),
            issued_at: issued_epoch,
            deadline_at: deadline_epoch,
            sla: ReplicationOrderSlaV1 {
                ingest_deadline_secs,
                min_availability_percent_milli: 99_000,
                min_por_success_percent_milli: 98_000,
            },
            metadata: Vec::new(),
        };
        norito::to_bytes(&order).expect("encode replication order")
    }
    fn provider_ingest_completion(
        provider_id: [u8; 32],
        completed_by: AccountId,
        completion_epoch: u64,
    ) -> ReplicationOrderCompletionRecord {
        ReplicationOrderCompletionRecord {
            provider_id: ProviderId::new(provider_id),
            completed_by: completed_by.clone(),
            completion_epoch,
            assignment_revision: 1,
            completion_authority: ProviderIngestCompletionAuthorityV1::new(
                completed_by.clone(),
                completed_by,
                ProviderIngestCompletionSignerPolicyV1 {
                    policy_id: [0xA1; 32],
                    revision: 1,
                    predecessor_digest: None,
                    policy_digest: [0xA2; 32],
                },
            ),
            finalized_anchor: ProviderIngestFinalizedAnchorV1 {
                height: completion_epoch.max(1),
                block_hash: [0xA3; 32],
            },
        }
    }
    fn encode_replication_order_bytes(
        order_id: &ReplicationOrderId,
        manifest_digest: &ManifestDigest,
        manifest_root_cid: &ManifestRootCid,
        issued_epoch: u64,
        deadline_epoch: u64,
    ) -> Vec<u8> {
        let id_bytes = *order_id.as_bytes();
        let providers = vec![[id_bytes[0]; 32], [id_bytes[0].wrapping_add(1); 32]];
        encode_replication_order_bytes_with_providers(
            order_id,
            manifest_digest,
            manifest_root_cid.as_bytes(),
            providers,
            issued_epoch,
            deadline_epoch,
        )
    }
