    #[tokio::test]
    async fn car_range_missing_dag_scope_returns_structured_refusal() {
        let context = token_test_context();
        let manifest = context.manifest();
        let end = manifest.content_length().saturating_sub(1);
        let mut headers = HeaderMap::new();
        headers.insert(
            header::RANGE,
            HeaderValue::from_str(&format!("bytes=0-{end}")).expect("range header"),
        );
        insert_api_test_header(
            &mut headers,
            HEADER_SORA_CHUNKER,
            manifest.chunk_profile_handle(),
        );
        insert_static_api_test_header(&mut headers, HEADER_SORA_NONCE, "nonce-download");

        let response = context.car_range(headers, 8082).await;
        assert_eq!(response.status(), StatusCode::PRECONDITION_REQUIRED);
        let request_id_header = response
            .headers()
            .get(HeaderName::from_static(HEADER_SORA_REQUEST_ID))
            .expect("request id header present");
        let request_id = request_id_header
            .to_str()
            .expect("request id header must be ASCII");
        assert!(
            !request_id.is_empty(),
            "request id header should not be empty"
        );

        let value = api_test_response_json(response).await;
        assert_json_fields!(value; json_at ["error"] => Some(&Value::String("missing_header".into())));
        let reason = value.json_str(&["reason"]).expect("reason field present");
        assert!(
            reason.contains("dag-scope"),
            "reason should mention dag-scope"
        );
        let header_value = value
            .json_object(&["details"])
            .and_then(|map| map.get("header"))
            .and_then(Value::as_str)
            .expect("details.header present");
        assert_eq!(header_value, "Sora-Dag-Scope");
    }
    #[cfg(feature = "telemetry")]
    #[tokio::test]
    async fn car_range_missing_dag_scope_increments_refusal_metric() {
        let context = token_test_context();
        let manifest = context.manifest();
        let end = manifest.content_length().saturating_sub(1);
        let label_values = [
            "missing_header",
            manifest.chunk_profile_handle(),
            "",
            TELEMETRY_ENDPOINT_CAR_RANGE,
        ];
        let metrics_before = context.app.telemetry.metrics();
        let counter_before = metrics_before
            .torii_sorafs_gateway_refusals_total
            .with_label_values(&label_values)
            .get();
        let mut headers = HeaderMap::new();
        headers.insert(
            header::RANGE,
            HeaderValue::from_str(&format!("bytes=0-{end}")).expect("range header"),
        );
        insert_api_test_header(
            &mut headers,
            HEADER_SORA_CHUNKER,
            manifest.chunk_profile_handle(),
        );
        insert_static_api_test_header(&mut headers, HEADER_SORA_NONCE, "nonce-download");

        let response = context.car_range(headers, 8090).await;
        assert_eq!(response.status(), StatusCode::PRECONDITION_REQUIRED);
        let metrics_after = context.app.telemetry.metrics();
        let counter_after = metrics_after
            .torii_sorafs_gateway_refusals_total
            .with_label_values(&label_values)
            .get();
        assert_eq!(
            counter_after,
            counter_before + 1,
            "gateway refusal counter should increment for missing dag-scope header"
        );
    }
    #[tokio::test]
    async fn car_range_accepts_valid_stream_token() {
        // Serving also requires the provider's governance-admitted capability advert.
        let advert = make_signed_advert();
        let mut context =
            capability_token_context(&advert, b"stream token payload fixture".to_vec());
        let mut app =
            Arc::try_unwrap(context.app).unwrap_or_else(|_| panic!("exclusive route app"));
        let admission = ServingAdmissionFixture::new();
        app.stream_token_admission_capture = Some(admission.capture.clone());
        let cleanup = RangeCleanupTestOwner::install(&mut app, 64);
        context.app = Arc::new(app);
        assert!(context.app.sorafs_gateway_config.enforce_capabilities);
        assert_eq!(
            context
                .app
                .provider_supports_chunk_range(&advert.provider_id()),
            Some(true)
        );
        let manifest = context.manifest();
        let end = manifest.content_length().saturating_sub(1);
        let token_base64 = issue_token_base64(&context, TokenOverrides::default()).await;
        let expected_length = manifest.content_length();
        let headers = alias_bound_car_range_headers(
            manifest.chunk_profile_handle(),
            manifest.content_length(),
            &token_base64,
            "nonce-download",
        );
        let response = context.car_range(headers, 8081).await;
        assert_eq!(response.status(), StatusCode::PARTIAL_CONTENT);
        assert_eq!(admission.active_leases(), 1);
        assert_eq!(admission.outcomes()[0].status, CustodyStatus::Accepted);
        let (parts, body) = response.into_parts();
        let headers = parts.headers;
        let body_bytes = body::to_bytes(body, usize::MAX)
            .await
            .expect("collect CAR body");
        let car_bytes = body_bytes.to_vec();
        assert_eq!(
            api_test_header_str(&headers, header::CONTENT_TYPE),
            Some(MIME_CAR)
        );
        let expected_length_header = car_bytes.len().to_string();
        assert_eq!(
            api_test_header_str(&headers, header::CONTENT_LENGTH),
            Some(expected_length_header.as_str())
        );
        let tls_state = headers
            .get(HeaderName::from_static(SORA_TLS_STATE_HEADER))
            .and_then(|value| value.to_str().ok())
            .expect("TLS state header present");
        assert!(
            tls_state.starts_with("ech-"),
            "unexpected TLS state header: {tls_state}"
        );
        let chunk_range_header = headers
            .get(header::HeaderName::from_static(HEADER_SORA_CHUNK_RANGE))
            .and_then(|value| value.to_str().ok())
            .expect("chunk range header present");
        let manifest_v1 = manifest.load_manifest().expect("load manifest");
        let chunk_profile =
            chunk_profile_for_manifest(&manifest_v1).expect("resolve chunk profile");
        let full_plan = manifest.to_car_plan(chunk_profile);
        let expected_range = 0..=end;
        let report = CarVerifier::verify_block_car(
            &manifest_v1,
            &full_plan,
            &car_bytes,
            expected_range.clone(),
        )
        .expect("CAR verification");
        assert_eq!(
            report.payload_bytes, expected_length,
            "verified payload length must match manifest length"
        );
        assert_eq!(
            report.payload_range, expected_range,
            "verified payload range should equal requested range"
        );
        assert_eq!(
            report.chunk_indices.len(),
            manifest.chunk_count(),
            "full range should contain every manifest chunk"
        );
        assert!(
            chunk_range_header.contains(&format!("chunks={}", report.chunk_indices.len())),
            "chunk range header must report the verified chunk count"
        );
        wait_for_range_cleanup(|| admission.active_leases() == 0).await;
        cleanup.finish().await;
    }
    #[tokio::test]
    async fn car_range_streams_verified_middle_chunk_window() {
        let payload_len = sorafs_chunker::ChunkProfile::DEFAULT.max_size * 3 + 17;
        let payload = (0..payload_len)
            .map(|idx| (idx as u8).wrapping_mul(37).wrapping_add(11))
            .collect::<Vec<_>>();
        let context = token_test_context_with_payload(payload);
        let manifest = context.manifest();
        assert!(
            manifest.chunk_count() >= 3,
            "fixture must produce at least three chunks"
        );
        let first_chunk = manifest.chunk(1).expect("second chunk metadata");
        let second_chunk = manifest.chunk(2).expect("third chunk metadata");
        let range_start = first_chunk.offset;
        let range_end = second_chunk
            .offset
            .checked_add(u64::from(second_chunk.length))
            .and_then(|value| value.checked_sub(1))
            .expect("non-empty second chunk");
        let requested_range = range_start..=range_end;
        let expected_chunk_count = 2usize;
        let token_base64 = issue_token_base64(&context, TokenOverrides::default()).await;
        let mut headers = HeaderMap::new();
        headers.insert(
            header::RANGE,
            HeaderValue::from_str(&format!("bytes={range_start}-{range_end}"))
                .expect("range header"),
        );
        insert_static_api_test_header(&mut headers, HEADER_DAG_SCOPE, "block");
        insert_api_test_header(
            &mut headers,
            HEADER_SORA_CHUNKER,
            manifest.chunk_profile_handle(),
        );
        insert_static_api_test_header(&mut headers, HEADER_SORA_NONCE, "middle-window");
        insert_api_test_header(&mut headers, HEADER_SORA_STREAM_TOKEN, &token_base64);
        insert_api_test_header(&mut headers, HEADER_SORA_NAME, "alias/test");
        headers.insert(
            header::HeaderName::from_static(HEADER_SORA_PROOF),
            alias_proof_header("alias/test"),
        );
        let response = context.car_range(headers, 8086).await;
        assert_eq!(response.status(), StatusCode::PARTIAL_CONTENT);
        let (parts, body) = response.into_parts();
        let headers = parts.headers;
        let body_bytes = body::to_bytes(body, usize::MAX)
            .await
            .expect("collect middle CAR body");
        let car_bytes = body_bytes.to_vec();
        let manifest_v1 = manifest.load_manifest().expect("load manifest");
        let chunk_profile =
            chunk_profile_for_manifest(&manifest_v1).expect("resolve chunk profile");
        let full_plan = manifest.to_car_plan(chunk_profile);
        let report = CarVerifier::verify_block_car(
            &manifest_v1,
            &full_plan,
            &car_bytes,
            requested_range.clone(),
        )
        .expect("middle CAR verification");
        assert_eq!(report.payload_range, requested_range);
        assert_eq!(report.chunk_indices, vec![1, 2]);
        assert_eq!(
            report.payload_bytes,
            u64::from(first_chunk.length) + u64::from(second_chunk.length)
        );
        let expected_content_range = format!(
            "bytes {range_start}-{range_end}/{}",
            manifest.content_length()
        );
        assert_eq!(
            api_test_header_str(&headers, header::CONTENT_RANGE),
            Some(expected_content_range.as_str())
        );
        let chunk_range_header = headers
            .get(header::HeaderName::from_static(HEADER_SORA_CHUNK_RANGE))
            .and_then(|value| value.to_str().ok())
            .expect("chunk range header present");
        assert!(
            chunk_range_header.contains(&format!("chunks={expected_chunk_count}")),
            "chunk range header must report only the served middle chunks"
        );
    }
