    #[tokio::test]
    async fn car_range_enforces_request_quota() {
        let context = token_test_context();
        let manifest = context.manifest();
        let token_base64 = issue_token_base64(
            &context,
            TokenOverrides {
                requests_per_minute: Some(1),
                ..TokenOverrides::default()
            },
        )
        .await;
        let first_headers = alias_bound_car_range_headers(
            manifest.chunk_profile_handle(),
            manifest.content_length(),
            &token_base64,
            "quota-nonce",
        );
        let first_response = context.car_range(first_headers, 8083).await;
        assert_eq!(first_response.status(), StatusCode::PARTIAL_CONTENT);
        let second_headers = alias_bound_car_range_headers(
            manifest.chunk_profile_handle(),
            manifest.content_length(),
            &token_base64,
            "quota-nonce",
        );
        let second_response = context.car_range(second_headers, 8084).await;
        assert_eq!(second_response.status(), StatusCode::TOO_MANY_REQUESTS);
        let retry_after = second_response
            .headers()
            .get(RETRY_AFTER)
            .expect("retry-after header present")
            .to_str()
            .expect("retry-after header must be ASCII")
            .parse::<u32>()
            .expect("retry-after header numeric");
        assert!(
            (1..=60).contains(&retry_after),
            "retry-after must be between 1 and 60 seconds (got {retry_after})"
        );
        let value = api_test_response_json(second_response).await;
        assert_eq!(
            value.get("error"),
            Some(&Value::String(
                "stream token request quota exceeded".to_string()
            ))
        );
    }
    #[tokio::test]
    async fn car_range_validated_local_manifest_satisfies_envelope_policy() {
        let mut context = token_test_context();
        let mut app_inner = Arc::try_unwrap(context.app)
            .unwrap_or_else(|_| panic!("token test context should hold unique app state"));
        app_inner.sorafs_gateway_config.require_manifest_envelope = true;
        refresh_api_test_gateway_security(&mut app_inner);
        context.app = Arc::new(app_inner);

        let manifest = context.manifest();
        let end = manifest.content_length().saturating_sub(1);
        let token_base64 = issue_token_base64(&context, TokenOverrides::default()).await;
        let mut headers = HeaderMap::new();
        headers.insert(
            header::RANGE,
            HeaderValue::from_str(&format!("bytes=0-{end}")).expect("range header"),
        );
        insert_static_api_test_header(&mut headers, HEADER_DAG_SCOPE, "block");
        insert_api_test_header(
            &mut headers,
            HEADER_SORA_CHUNKER,
            manifest.chunk_profile_handle(),
        );
        insert_static_api_test_header(&mut headers, HEADER_SORA_NONCE, "nonce-download");
        insert_api_test_header(&mut headers, HEADER_SORA_STREAM_TOKEN, &token_base64);

        // Without a validated local manifest or signed envelope, policy still refuses.
        let denied = enforce_gateway_policy_for_request(
            &context.app,
            &headers,
            &manifest,
            Some(authoritative_sorafs_provider_id(&context.app).unwrap()),
            SocketAddr::from(([127, 0, 0, 1], 8085)),
            false,
        )
        .expect_err("unvalidated manifest authority must be refused");
        let value =
            api_test_response_json_with_status(denied, StatusCode::PRECONDITION_REQUIRED).await;
        assert_json_fields!(value; json_at ["error"] => Some(&Value::String("manifest_envelope_required".into())));
        // The serving path authenticates its retained local manifest before policy evaluation.
        let response = context.car_range(headers, 8085).await;
        assert_eq!(response.status(), StatusCode::PARTIAL_CONTENT);
    }
